import type {
  EduType, IAppEligibilityInformation, LegalAgeGroupClassificationType, PersonaType, UserCohortType
} from '@1js/m365-chat-shared-types';
import type { MetaOSEligibility, MetaOSEligibilityResponse } from './UserEligibilityService';

/**
 * Type guard to check if data is a valid MetaOSEligibilityResponse
 * @param data - The data to check
 * @returns True if data is a valid MetaOSEligibilityResponse, false otherwise
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function isMetaOSEligibilityResponse(data: any): data is MetaOSEligibilityResponse {
  // Check if data is an object and not null
  if (!data || typeof data !== 'object') {
    return false;
  }

  // Check required properties exist and have correct types
  if (typeof data.idType !== 'string') {
    return false;
  }

  if (!Array.isArray(data.eligibilities)) {
    return false;
  }

  if (typeof data.nextInterval !== 'number') {
    return false;
  }

  return true;
}

/**
 * Converts a MetaOSEligibility object to IAppEligibilityInformation.
 */
export function metaOSEligibilityToAppEligibilityInformation(
  meta: MetaOSEligibility
): IAppEligibilityInformation {
  if (meta.eligibility === undefined) {
    throw new Error('Invalid MetaOSEligibility: eligibility is undefined');
  }
  const cohort = (meta.eligibility.cohort?.toLowerCase() ?? 'none') as UserCohortType;
  const persona = (meta.eligibility.userClassification?.persona?.toLowerCase() ?? 'none') as PersonaType;
  const ageGroup = (meta.eligibility.ageGroup?.toLowerCase() ?? 'none') as LegalAgeGroupClassificationType;
  const eduType = (meta.eligibility.userClassification?.eduType?.toLowerCase() ?? 'none') as EduType;
  return {
    cohort,
    persona,
    ageGroup,
    isCopilotEnabledRegion: meta.eligibility.isCopilotEnabledRegion,
    isCopilotEligible: meta.eligibility.isCopilotEligible,
    isOptedOutByAdmin: meta.eligibility.isOptedOutByAdmin,
    eduType,
    isError: false,
    featureSet: meta.eligibility.featureSet
  };
}

export function hasEligibilities(eligibilities: MetaOSEligibility[]): boolean {
  return eligibilities.length > 0 && eligibilities[0].eligibility !== undefined;
}

export function buildErrorAppEligibilityInformation(): IAppEligibilityInformation {
  return {
    cohort: 'none',
    persona: 'none',
    ageGroup: 'none',
    isCopilotEnabledRegion: false,
    isCopilotEligible: false,
    isOptedOutByAdmin: false,
    eduType: 'none',
    isError: true,
    featureSet: {}
  };
}
