import type { WorkspaceCreateType } from '@fluidx/loop-workspace-types';
import type { AppWorkspaceManager } from '../service/workspaceManager/AppWorkspaceManager';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';

export interface NativeEvent_AddReferenceToNotebookArgs {
  podId: string;
  refUrls: string[];
  refTitles: string[];
}

export interface NativeEvent_AppRequestDeleteNotebookArgs {
  podId: string;
}

export interface NativeEvent_NavigateToNotebookArgs {
  podId: string;
  spoId?: string;
}

export interface NativeEvent_NavigateToNotebookPageArgs {
  docUrl: string;
  podId?: string;
  requiresRedeem?: boolean;
}

export interface NativeEvent_NavigateToCreateNotebookArgs {
  chatConversationIds?: string[];
  pageDocUrls?: string[];
  workspaceCreateType?: WorkspaceCreateType;
  notebookName?: string;
}

export interface NativeEvent_NavigateToSearchResultArgs {
  siteUrl: string;
  webFallbackUrl: string;
}

export interface NativeEvent_NavigateToLinkArgs {
  linkUrl: string;
}

export interface NativeEvent_RenameNotebookArgs {
  podId: string;
  name: string;
}

export interface NativeEvent_ToggleFavoriteNotebookArgs {
  podId: string;
}

export const GetNativeEventHandler = (appWorkspaceManager: AppWorkspaceManager) => {
  const handlers: Record<string, (args: unknown) => void> = {
    appRequestDeleteNotebook: (a) => void appWorkspaceManager.appRequestDeleteNotebook(a as NativeEvent_AppRequestDeleteNotebookArgs),
    addReferenceToNotebook: (a) => void appWorkspaceManager.appAddReferenceToNotebook(a as NativeEvent_AddReferenceToNotebookArgs),
    navigateToModuleHome: () => void appWorkspaceManager.appNavigateToHome(),
    navigateToCreateNotebook: (a) => void appWorkspaceManager.appNavigateToCreateNotebook(a as NativeEvent_NavigateToCreateNotebookArgs),
    navigateToNotebookHome: (a) => void appWorkspaceManager.appNavigateToNotebook(a as NativeEvent_NavigateToNotebookArgs),
    navigateToNotebookPage: (a) => void appWorkspaceManager.appNavigateToPage(a as NativeEvent_NavigateToNotebookPageArgs),
    renameNotebook: (a) => void appWorkspaceManager.renameNotebook(a as NativeEvent_RenameNotebookArgs),
    toggleFavoriteNotebook: (a) => void appWorkspaceManager.toggleFavoriteNotebook(a as NativeEvent_ToggleFavoriteNotebookArgs),
    tryNavigateToLink: (a) => void appWorkspaceManager.appNavigateToLink(a as NativeEvent_NavigateToLinkArgs),
    tryNavigateToSearchResult: (a) => void appWorkspaceManager.appNavigateToSearchResult(a as NativeEvent_NavigateToSearchResultArgs),
  };

  return (event: string, args: unknown): void => {
    TelemetryLogger.Instance.logEvent('NativeEventReceived', { EventName: event });
    try {
      const handler = handlers[event];
      if (!handler) {
        throw new Error('Unsupported native event');
      }
      handler(args);
    }
    catch (error) {
      TelemetryLogger.Instance.logError('NativeEventHandlerError', error, { ErrorMethod: 'GetNativeEventHandler', ErrorEvent: event });
    }
  };
};
