import type { ScenarioNames } from '@fluidx/loop-workspace-types';


export const getCopilotScenarioName = (isMSA: boolean, isPremium = false): ScenarioNames => {
  if (isMSA) {
    return isPremium ? 'OneNoteCopilotNotebookPremiumConsumer' : 'OneNoteCopilotNotebookPaidConsumer';
  }
  return 'OneNoteCopilotNotebook';
};
