// Usage example:
// import { featureGates } from '../utils/FeatureGates';
// const isFeatureEnabled = featureGates.getBooleanFeatureGate('example', false);
export const featureGates = {
  getBooleanFeatureGate: (featureName: FeatureName, defaultValue: boolean) => {
    try {
      const featureGateName = featureGateNames[featureName];
      return OfficeRuntime.experimentation.getBooleanFeatureGate(featureGateName, defaultValue);
    } catch (e) {
      TelemetryLogger.Instance.logError('FeatureGatesError', e, { ErrorMethod: 'getBooleanFeatureGate' });
      return defaultValue;
    }
  },
  getIntFeatureGate: (featureName: FeatureName, defaultValue: number, options?: { min?: number; max?: number }) => {
    try {
      const featureGateName = featureGateNames[featureName];
      const raw = OfficeRuntime.experimentation.getIntFeatureGate(featureGateName, defaultValue);
      const value = Number.isNaN(raw) ? defaultValue : raw;
      const clamped = options?.min !== undefined ? Math.max(options.min, value) : value;
      return options?.max !== undefined ? Math.min(options.max, clamped) : clamped;
    } catch (e) {
      TelemetryLogger.Instance.logError('FeatureGatesError', e, { ErrorMethod: 'getIntFeatureGate' });
      return defaultValue;
    }
  },
  getStringFeatureGate: (featureName: FeatureName, defaultValue: string) => {
    try {
      const featureGateName = featureGateNames[featureName];
      return OfficeRuntime.experimentation.getStringFeatureGate(featureGateName, defaultValue);
    } catch (e) {
      TelemetryLogger.Instance.logError('FeatureGatesError', e, { ErrorMethod: 'getStringFeatureGate' });
      return defaultValue;
    }
  },

};

export const changeGates = {
  getBooleanChangeGate: (changeGateName: ChangeGateName) => {
    try {
      return OfficeRuntime.experimentation.getBooleanFeatureGate(changeGateNames[changeGateName], true);
    } catch (e) {
      TelemetryLogger.Instance.logError('FeatureGatesError', e, { ErrorMethod: 'getBooleanChangeGate' });
      return true;
    }
  }
};

// eslint-disable-next-line @typescript-eslint/no-namespace
export declare namespace OfficeRuntime {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace experimentation {
    function getBooleanFeatureGate(flight: string, defaultValue?: boolean): boolean;
    function getIntFeatureGate(flight: string, defaultValue?: number): number;
    function getStringFeatureGate(flight: string, defaultValue?: string): string;
  }
}
