
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import type { CloudType } from '../utils/Cloud';
import { hasMessageProperty } from '../utils/ErrorUtils';
import {
  CLOUD_RESOURCES_MAP, ResourcesMSA, ResourcesPublic, type TokenType,
} from './endpoints';
import { getMappedErrorStringMessage, isMSA } from './utils';

import { changeGates } from '../utils/FeatureGates';

// Cloud types that must NOT fall back to public endpoints.
// Requests for undefined token types in these clouds will throw.
const STRICT_CLOUD_TYPES: ReadonlySet<string> = new Set([
  'GCCH', 'DoD',
]);

let cachedStrictEndpointsEnabled: boolean | undefined;
function isStrictSovereignEndpointsEnabled(): boolean {
  if (cachedStrictEndpointsEnabled === undefined) {
    cachedStrictEndpointsEnabled = changeGates.getBooleanChangeGate('useStrictSovereignEndpoints');
  }
  return cachedStrictEndpointsEnabled;
}

export type Identity = {
  id: string;
  name: string;
  tenantId: string;
  identityType: number;
  oid?: string;
  upn?: string;
};

export type OfficeAuthContext = {
  userObjectId: string;
  tenantId: string;
  userPrincipalName: string;
  authorityType: string;
  authorityBaseUri: string;
  puid: string;
  loginHint: string;
};

export type UserAccountType = 'MSA' | 'AAD';
export type TokenDefinition = {
  resource: string;
  tokenType: TokenType;
  appendDefaultScope: boolean;
};

export const getResourceForTokenType = (tokenType: TokenType, accountType: UserAccountType, cloudType: CloudType): string | undefined => {
  // Only allow MSA in public cloud
  if (accountType === 'MSA' && cloudType !== 'Public' && cloudType !== 'Public1CDN') {
    return undefined;
  }

  // MSA-specific resources. ODSP consumer resources are normalized to /v2.
  if (accountType === 'MSA' && tokenType in ResourcesMSA) {
    return updateOdspResourceForConsumer(ResourcesMSA[tokenType as keyof typeof ResourcesMSA]);
  }

  // Get the resource map for the cloud
  const resourceMap = CLOUD_RESOURCES_MAP[cloudType];
  if (tokenType in resourceMap) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (resourceMap as any)[tokenType];
  }

  // For strict sovereign clouds, do not fall back to public endpoints
  if (STRICT_CLOUD_TYPES.has(cloudType) && isStrictSovereignEndpointsEnabled()) {
    const error = new Error(`Token type '${tokenType}' is not supported in cloud '${cloudType}'`);
    TelemetryLogger.Instance.logError('AuthError', error, {
      ErrorMethod: 'getResourceForTokenType',
      TokenType: tokenType,
      CloudType: cloudType,
    });
    throw error;
  }

  // For public-compatible clouds (Public, Public1CDN, GCCM), fall back to public resources
  if (tokenType in ResourcesPublic) {
    return ResourcesPublic[tokenType as keyof typeof ResourcesPublic];
  }

  return undefined;
};

// Consumer ODSP (OneDrive/SharePoint) endpoints live under this domain. Resources
// may be the apex, the well-known home/my hosts, or tenant-specific subdomains.
const ODSP_CONSUMER_DOMAIN = 'microsoftpersonalcontent.com';

export const isODSPResource = (resource: string): boolean => {
  const normalized = resource.toLowerCase();
  let host: string;
  try {
    host = new URL(normalized).hostname;
  } catch {
    // Not a fully-qualified URL; treat the input as a bare host (drop any path).
    host = normalized.split('/')[0];
  }
  return host === ODSP_CONSUMER_DOMAIN || host.endsWith(`.${ODSP_CONSUMER_DOMAIN}`);
};

export const updateOdspResourceForConsumer = (resource: string): string => {
  if (!isODSPResource(resource)) {
    return resource;
  }
  // ODSP consumer endpoints must target /v2. Strip any trailing slash and avoid
  // double-appending when the resource already points at /v2.
  const trimmed = resource.replace(/\/+$/, '');
  return trimmed.toLowerCase().endsWith('/v2') ? trimmed : `${trimmed}/v2`;
};

export const getConsumerScope = (resource: string, tokenType: TokenType): string => {
  // MSA-specific resources use a different scope format
  if (tokenType === 'MRUDF' || tokenType === 'MRU') {
    return 'service::officeapps.live.com::MBI_SSL_SHORT';
  }
  return resource.endsWith('/') ? `${resource}.default` : `${resource}/.default`;
};

export const getTokenDefinitionFromResourceStrings = (resourceStrings: string[], accountType: UserAccountType, cloudType: CloudType): TokenDefinition | undefined => {
  // Only allow MSA in public cloud
  if (accountType === 'MSA' && cloudType !== 'Public' && cloudType !== 'Public1CDN') {
    return undefined;
  }

  const normalizedResources = resourceStrings.map(resource => resource.toLowerCase());

  const findLongestMatch = (resourceMap: Record<string, unknown>): { key: string; value: string } | undefined => {
    let longest: { key: string; value: string } | undefined;
    for (const [key, value] of Object.entries(resourceMap)) {
      if (typeof value === 'string' && normalizedResources.includes(value.toLowerCase())) {
        if (!longest || value.length > longest.value.length) {
          longest = { key, value };
        }
      }
    }
    return longest;
  };

  // MSA-specific resources
  if (accountType === 'MSA') {
    const match = findLongestMatch(ResourcesMSA);
    if (match) {
      // Update ODSP resource for consumer accounts
      const resource = updateOdspResourceForConsumer(match.value);
      return {
        resource,
        tokenType: match.key as TokenType,
        appendDefaultScope: resource.includes('://'),
      };
    }

    // ODSP consumer resources can use tenant-specific subdomains that are not in
    // the static resource map (e.g. <tenant>-my.microsoftpersonalcontent.com).
    // Detect them by host and target the /v2 endpoint.
    const odspResource = normalizedResources.find(isODSPResource);
    if (odspResource) {
      const resource = updateOdspResourceForConsumer(odspResource);
      return {
        resource,
        tokenType: 'ODSP',
        appendDefaultScope: resource.includes('://'),
      };
    }
  }

  // Cloud-specific resources
  const resourceMap = CLOUD_RESOURCES_MAP[cloudType] as Record<string, unknown>;
  const cloudMatch = findLongestMatch(resourceMap);
  if (cloudMatch) {
    return {
      resource: cloudMatch.value,
      tokenType: cloudMatch.key as TokenType,
      appendDefaultScope: true,
    };
  }

  // For public-compatible clouds (Public, Public1CDN, GCCM), fall back to public resources
  if (!STRICT_CLOUD_TYPES.has(cloudType) || !isStrictSovereignEndpointsEnabled()) {
    const publicMatch = findLongestMatch(ResourcesPublic);
    if (publicMatch) {
      return {
        resource: publicMatch.value,
        tokenType: publicMatch.key as TokenType,
        appendDefaultScope: true,
      };
    }
  }

  return undefined;
};

export const getOfficeAuthContext = async (): Promise<Office.AsyncResult<OfficeAuthContext> | undefined> => {
  const getPrimaryIdentityAuthContext = new Promise(
    (resolve: (authContext: Office.AsyncResult<OfficeAuthContext>) => void, reject: (error: Error) => void) => {
      const timeout = setTimeout(() => {
        reject(new Error('getAuthContextAsync timed out'));
      }, 2000); // 2 seconds timeout
      Office.context.auth.getAuthContextAsync((authContext) => {
        clearTimeout(timeout);
        resolve(authContext);
      });
    }
  );
  try {
    const authContext = await getPrimaryIdentityAuthContext;
    if (authContext.status !== Office.AsyncResultStatus.Succeeded) {
      throw new Error(authContext.error?.message ?? 'Failed to get office auth context');
    }
    return authContext;
  } catch (error) {
    TelemetryLogger.Instance.logError(
      'AuthError',
      hasMessageProperty(error) ? getMappedErrorStringMessage(error.message) : 'Failed to get office auth context',
      {
        ErrorMethod: 'getOfficeAuthContext',
      },
    );
    return undefined;
  }
};

export const getUserAccountType = (identity?: Identity): UserAccountType => {
  if (isMSA(identity?.identityType)) {
    return 'MSA';
  }
  return 'AAD';
};
