import type {
  ChatReference, LoopPageData, LoopWorkspaceData, NavigationNotebookParams, NavigationPageParams, PageReference
} from '@fluidx/loop-workspace-types';
import {
  emptyId, emptyTitle
} from '../../service/workspaceManager/constants';

export interface InteropIdentityInfo {
  userId: string;
  userName: string;
  email: string;
  tenantId: string;
  accountType: number;
}

export interface InteropWorkspaceDataModel {
  title: string;
  podId: string;
  spoId: string;
  isFavorite: boolean;
  lastOpened: number;
  forceSetAsSelected: boolean;
}

export interface InteropPageDataModel {
  title: string;
  docUrl: string;
  podId: string;
  spoId: string;
}

export interface InteropChatReferenceDataModel {
  conversationId: string;
}

export interface InteropPageReferenceDataModel {
  docUrl: string;
}

export interface InteropPageNavigationDataModel {
  title: string;
  docUrl: string;
  podId: string;
  requiresRedeem: boolean;
}

export interface InteropNotebookNavigationDataModel {
  podId: string;
  spoId: string;
}

export interface InteropWorkspaceDataModelCollection {
  workspaces: InteropWorkspaceDataModel[];
}

export interface InteropPageCollection {
  recentPages: InteropPageDataModel[];
}

export interface InteropSearchResultNavigationDataModel {
  siteUrl: string;
  webFallbackUrl: string;
  navSuccess: boolean;
}

export interface InteropLinkNavigationDataModel {
  originalUrl: string;
  navSuccess: boolean;
}

export interface InteropReferenceLinkNavigationDataModel {
  originalUrl: string;
}

export interface InteropAddReferenceToNotebookDataModel {
  success: boolean;
}

export function TranslateWorkspaceData(data: LoopWorkspaceData, forceSetAsSelected: boolean): InteropWorkspaceDataModel {

  // The keys are case-sensitive; they need to match what is in the native client, otherwise we get a runtime error in the native client
  // when deserializing the JSON object.
  return {
    title: data.title,
    podId: data.mfsPodId,
    spoId: data.spoId,
    isFavorite: data.isFavorite,
    lastOpened: typeof data.lastOpened === 'string' ? Date.parse(data.lastOpened) || 0 : data.lastOpened?.getTime() ?? 0,
    forceSetAsSelected,
  };
}

export function TranslatePageData(data: LoopPageData): InteropPageDataModel {

  // The keys are case-sensitive; they need to match what is in the native client, otherwise we get a runtime error in the native client
  // when deserializing the JSON object.
  return {
    title: data.title,
    podId: data.mfsPodId ?? emptyId,
    docUrl: data.docUrl,
    spoId: data.id,
  };
}

export function TranslateChatReferenceData(data: ChatReference): InteropChatReferenceDataModel {

  // The keys are case-sensitive; they need to match what is in the native client, otherwise we get a runtime error in the native client
  // when deserializing the JSON object.
  return {
    conversationId: data.conversationId,
  };
}

export function TranslatePageReferenceData(data: PageReference): InteropPageReferenceDataModel {

  // The keys are case-sensitive; they need to match what is in the native client, otherwise we get a runtime error in the native client
  // when deserializing the JSON object.
  return {
    docUrl: data.docUrl,
  };
}

export function TranslateNotebookNavigationData(data: NavigationNotebookParams): InteropNotebookNavigationDataModel {

  // The keys are case-sensitive; they need to match what is in the native client, otherwise we get a runtime error in the native client
  // when deserializing the JSON object.
  return {
    podId: data.mfsPodId,
    spoId: data.spoId ?? emptyId,
  };
}

export function TranslatePageNavigationData(data: NavigationPageParams, title?: string): InteropPageNavigationDataModel {

  // The keys are case-sensitive; they need to match what is in the native client, otherwise we get a runtime error in the native client
  // when deserializing the JSON object.
  return {
    title: title ?? emptyTitle,
    docUrl: data.docUrl,
    podId: data.mfsPodId ?? emptyId,
    requiresRedeem: data.requiresRedeem ?? false,
  };
}
