import type { IAppEligibilityInformation } from '@1js/m365-chat-shared-types';
import type { HostAuthService } from '../../auth/HostAuthService';
import { getResourceForTokenType, getUserAccountType } from '../../auth/HostAuthServiceUtils';
import { isMSA, toError } from '../../auth/utils';
import { TelemetryActivityTracker } from '../../telemetry/TelemetryActivityTracker';
import { TelemetryLogger } from '../../telemetry/TelemetryLogger';
import { getCloudType } from '../../utils/Cloud';
import {
  CopilotNotebooksApplicationID, Identifiers, MAX_WAIT_SECONDS
} from './constants';
import {
  buildErrorAppEligibilityInformation, hasEligibilities, isMetaOSEligibilityResponse, metaOSEligibilityToAppEligibilityInformation
} from './utils';

// Eligibility type based on API response
export type MetaOSEligibility = {
  identity: string;
  eligibility: {
    ageGroup: string;
    cohort: string;
    userClassification: {
      persona: string;
      eduType: string;
    };
    isCopilotEligible: boolean;
    isCopilotEnabledRegion: boolean;
    isOptedOutByAdmin: boolean;
    featureSet: {
      uxFeatures: string[];
      serverFeatures: string[];
    };
  };
  settings: {
    feedbackSettings: {
      sendFeedback: boolean;
      logCollection: boolean;
      sendSurvey: boolean;
      sendCopilotFeedback: boolean;
      screenshot: boolean;
      emailCollection: boolean;
    };
    conversationSettings: {
      isOptionalConnectedExperiencesEnabled: boolean;
      copilotWebSearch: string;
    };
  };
};
export interface MetaOSEligibilityResponse {
  /** Type of identifier used in the request */
  idType: string;
  /** Array of eligibility entries for requested identities */
  eligibilities: MetaOSEligibility[];
  /** Next polling interval in seconds */
  nextInterval: number;
}

/**
 * Service for checking user eligibility by making API calls to the MetaOS endpoint
 */
export class UserEligibilityService {
  private userEligibilities: IAppEligibilityInformation | undefined;
  private userEligibilitiesPromise: Promise<void> | undefined;
  private readonly hostAuthService: HostAuthService;

  constructor(hostAuthService: HostAuthService) {
    this.hostAuthService = hostAuthService;
  }

  private getBaseUrl(): string {
    const cloudType = getCloudType();
    const accountType = getUserAccountType(this.hostAuthService.getIdentity());
    const resource = getResourceForTokenType('METAOS', accountType, cloudType);

    return `${resource}/catalog/v1`;
  }

  /**
   * Makes an authenticated API call to the MetaOS endpoint
   * @param endpoint - The API endpoint to call (relative to base URL)
   * @param options - Additional fetch options
   * @returns Promise resolving to the API response
   */
  private async makeAuthenticatedRequest(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<MetaOSEligibilityResponse> {
    return TelemetryActivityTracker.runActivity(
      'UserEligibilityServiceAPICall',
      async () => {
        // Get the MetaOS token from the auth service
        const token = await this.hostAuthService.getOfficeFirstPartyAuthResultByTokenType('METAOS');

        if (!token?.accessToken) {
          throw new Error('Failed to obtain MetaOS access token');
        }

        // Prepare the request URL
        const url = `${this.getBaseUrl()}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`;

        // Prepare headers with authorization
        const headers = {
          'Authorization': `Bearer ${token.accessToken}`,
          ...options.headers,
        };

        // Make the API call
        const response = await fetch(url, {
          ...options,
          headers,
        });

        if (!response.ok) {
          throw new Error(`API request failed: ${response.status} ${response.statusText}`);
        }

        // Parse and validate the response
        const data = await response.json();
        if (!isMetaOSEligibilityResponse(data)) {
          throw new Error('Invalid MetaOS eligibility response');
        }
        return data as MetaOSEligibilityResponse;
      }
    );
  }

  /**
   * Makes a request to the eligibility API
   * @returns Promise resolving to the eligibility information for the user
   */
  private async makeEligibilityRequest(): Promise<MetaOSEligibilityResponse> {
    const body = {
      'IdType': 'TitleId',
      'Identifiers': [ isMSA(this.hostAuthService.getIdentity()?.identityType)
        ? Identifiers.MSA
        : Identifiers.AAD]
    };
    const url = '/users/titles/eligibilities';
    const options = {
      method: 'POST',
      headers: {
        //'X-MSEdge-ClientIP': '0.0.0.1', // Use actual IP if available
        'X-Office-Application': CopilotNotebooksApplicationID,
      },
      body: JSON.stringify(body)
    };
    return this.makeAuthenticatedRequest(url, options);
  }

  /**
   * Returns cached user eligibility information if available, otherwise populates it
   * by making an API call to the MetaOS endpoint.
   * This method should be called when eligibility information is needed.
   * @returns Promise resolving to the user's eligibility information or undefined
   */
  public async getUserEligibilityInformation(): Promise<IAppEligibilityInformation> {
    if (this.userEligibilities && !this.userEligibilities.isError) {
      // If eligibilities are already populated, return them
      return this.userEligibilities;
    }
    if (!this.userEligibilitiesPromise) {
      // If no promise is running, start populating user eligibility information
      this.populateUserEligibilityInformation();
    }
    // Wait for the promise to resolve
    await this.userEligibilitiesPromise;
    // After waiting, check if we successfully got the eligibilities
    if (this.userEligibilities) {
      return this.userEligibilities;
    }

    throw new Error('User eligibility information not available');
  }

  /**
   * Populates the user eligibility information by making an API call.
   * If the API call fails or no eligibilities are found, it retries after a specified interval.
   * This method can be called during app initialization to ensure user eligibility information is available.
   */
  public populateUserEligibilityInformation() {
    if (this.userEligibilitiesPromise) {
      // If the promise is already running, return.
      return;
    }
    const getUserEligibilitiesWithRetryPromise = async () => {
      try {
        await TelemetryActivityTracker.runActivity(
          'PopulateUserEligibilityInformation',
          async (activity) => {
            let response = await this.makeEligibilityRequest();
            activity.addData('hasEligibilities', response.eligibilities.length > 0);
            activity.addData('nextInterval', response.nextInterval);
            // If no eligibilities are found, check if we need to retry
            if (!hasEligibilities(response.eligibilities)) {
              // wait the interval duration in seconds and retry, maxing it to MAX_WAIT_SECONDS
              const waitTime = Math.min(response.nextInterval, MAX_WAIT_SECONDS);
              await new Promise(resolve => setTimeout(resolve, waitTime * 1000));
              response = await this.makeEligibilityRequest();
              if (!hasEligibilities(response.eligibilities)) {
                throw new Error(`No eligibility information found after retry for ${waitTime} seconds`);
              }
            }
            this.userEligibilities = metaOSEligibilityToAppEligibilityInformation(response.eligibilities[0]);
            this.userEligibilitiesPromise = undefined; // Reset the promise after completion
          }
        );
      } catch (error) {
        const lastError = toError(error);
        this.userEligibilitiesPromise = undefined; // Reset the promise on error
        this.userEligibilities = buildErrorAppEligibilityInformation();
        TelemetryLogger.Instance.logError('UserEligibilityServiceError', lastError, {
          ErrorMethod: 'getUserEligibilitiesWithRetryPromise'
        });

      }
    };
    // Start the promise to populate user eligibility information
    this.userEligibilitiesPromise = getUserEligibilitiesWithRetryPromise();
  }
}
