import { apiBridge } from '../interop';
import { OfficeTelemetrySinkWrapper } from '../telemetry/OfficeTelemetrySinkWrapper';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { changeGates } from './FeatureGates';
import { HostAppSettings } from './HostAppSettings';
import { LoadStateTracker } from './loadStateTracker';
import { closeOpenTrackersOnTeardown } from './teardown';

/**
 * Installs the page-teardown handler on `window`.
 *
 * Listens for `beforeunload` ONLY, never `pagehide`. The SDX webview is a persistent singleton the
 * host REPARENTS (not destroys) on a canvas<->notebook switch — which fires `pagehide` — so running
 * our destructive teardown on a mere hide would brick telemetry + interop. `beforeunload` fires only
 * on a real navigate / reload / close. Idempotent via `unloadFired`; the returned fn removes the listener.
 */
export function installUnloadHandlers(): () => void {
  let unloadFired = false;

  const handleUnload = (): void => {
    if (unloadFired) return;
    unloadFired = true;

    const loadPhase = LoadStateTracker.getPhase();
    const openScenarioCount = LoadStateTracker.getOpenScenarioCount();
    const loadInProgress = openScenarioCount > 0;
    const isUILessLoad = HostAppSettings.isUILessLoad();
    const scenarioForceCloseEnabled = changeGates.getBooleanChangeGate('useUnloadScenarioForceClose');

    // Snapshot queue pressure before draining so PageUnload records how much telemetry was
    // pending / dropped at teardown.
    const sink = OfficeTelemetrySinkWrapper.Instance;
    let droppedEventCount = 0;
    let queueLength = 0;
    let maxQueueSize = 0;
    try {
      droppedEventCount = sink.droppedEventCount;
      queueLength = sink.queueLength;
      maxQueueSize = sink.maxQueueSize;
    } catch { /* best-effort */ }

    // 1. PageUnload breadcrumb via the priority path (bypasses the batched queue). no-PII
    try {
      TelemetryLogger.Instance.logPriorityEvent('PageUnload', {
        UnloadEvent: 'beforeunload',
        PageLifetimeMs: LoadStateTracker.getPageLifetimeMs(),
        LoadInProgress: loadInProgress,
        LoadPhase: loadPhase,
        IsUILessLoad: isUILessLoad,
        DocumentHidden: document.hidden,
        VisibilityState: document.visibilityState,
        IsAppInitialized: LoadStateTracker.isAppInitialized(),
        OpenScenarioCount: openScenarioCount,
        ScenarioForceCloseEnabled: scenarioForceCloseEnabled,
        DroppedEventCount: droppedEventCount,
        QueueLength: queueLength,
        MaxQueueSize: maxQueueSize,
      });
    } catch { /* never let telemetry block cleanup */ }

    // 2. Force-close open trackers (markers queued before shutdown).
    try {
      closeOpenTrackersOnTeardown(new Error(`PageUnloadedDuringLoad_${loadPhase}`));
    } catch { /* helper logs; never block cleanup */ }

    // 3. apiBridge cleanup.
    try { apiBridge.cleanup(); } catch { /* ignore */ }

    // 4. Drain + shut the sink down (also emits the overflow summary).
    try { TelemetryLogger.Instance.shutdown(); } catch { /* ignore */ }
  };

  const beforeUnloadListener = (): void => handleUnload();
  window.addEventListener('beforeunload', beforeUnloadListener);

  return () => {
    window.removeEventListener('beforeunload', beforeUnloadListener);
  };
}
