import type {
  Environment, SettingType, UserContext,
} from '@fluidx/loop-types';
import { EcsSettingsProvider } from '@fluidx/settings-provider';
import { featureGates } from '../utils/FeatureGates';

class InjectedSettingsProvider extends EcsSettingsProvider {
  private injectedSettings = new Map<string, SettingType>();

  /**
   * Checks to see if the setting was overridden and returns that value.
   * Otherwise returns the ecs provided setting
   */
  override getSetting<T extends SettingType>(settingName: string, defaultValue: T, namespace: string): T {
    if (this.injectedSettings.has(settingName)) {
      return this.injectedSettings.get(settingName) as T;
    }
    return super.getSetting(settingName, defaultValue, namespace);
  }

  /**
   * Sets the setting to be a specific value on the SettingsProvider
   * @param settingName SettingName to be overridden
   * @param value overridden value
   */
  setSetting<T extends SettingType>(settingName: string, value: T) {
    this.injectedSettings.set(settingName, value);
  }
}

export function createFrontendLoopSettingsProvider(environment: Environment, userContext: UserContext): EcsSettingsProvider {
  const settingsProvider = new InjectedSettingsProvider({
    ecsFilters: {
      audience: environment.audience,
      userContext: userContext,
    },
    hostName: 'Office',
    cacheExpiresDurationOverrideInMin: featureGates.getIntFeatureGate('ecsCacheExpirationTimeInMinutes', 10080), // 7 days default
    alwaysFetchNewSettings: true,
  });

  settingsProvider.setSetting('loopApp.isNotebooksExperienceEnabled', true);
  settingsProvider.setSetting('loopApp.isOneNoteNavbarEnabled', true);
  settingsProvider.setSetting('loopApp.isOneNoteSuggestionPrioritizationEnabled', true);
  settingsProvider.setSetting('loopApp.isCopilotNotebooksStudyGuideEnabled', true);
  settingsProvider.setSetting('loopApp.isAutoPopulateTitleOnCreateNotebookEnabled', true);

  settingsProvider.setSetting('loopApp.isL2NavRefreshEnabled', true);
  settingsProvider.setSetting('loopApp.isSimplifiedL2NavCustomizationsEnabled', true);

  const useShadowCopilotNotebookOption = featureGates.getBooleanFeatureGate('useShadowCopilotNotebookOption', false /* defaultValue */);
  const isOneNoteNotebooksInfographicEnabled = featureGates.getBooleanFeatureGate('isOneNoteNotebooksInfographicEnabled', true /* defaultValue */);
  settingsProvider.setSetting('loopApp.isNotebooksInfographicEnabled', isOneNoteNotebooksInfographicEnabled);
  settingsProvider.setSetting('loopApp.isSuggestedPagesToolbarEnabled', useShadowCopilotNotebookOption);
  settingsProvider.setSetting('loopApp.isNotebookWeeklyReportGenerationEnabled', useShadowCopilotNotebookOption);
  settingsProvider.setSetting('loopApp.isCPNBCreateWeeklyReportAutomaticGenerationEnabled', useShadowCopilotNotebookOption);
  settingsProvider.setSetting('loopApp.isCPNBCreateAutoSummaryGenerationEnabled', useShadowCopilotNotebookOption);

  settingsProvider.setSetting('loopApp.vodcast.isFullScreenDisabled', true);

  return settingsProvider;
}
