import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { toError } from './ErrorUtils';
import { changeGates, featureGates } from './FeatureGates';
import { closeOpenTrackersOnTeardown } from './teardown';

export const RELOAD_COUNTER_KEY = 'copilotworkspaces_error_reload_count';
export const DEFAULT_MAX_RETRIES = 3;
const DEFAULT_RELOAD_DELAY_MS = 1000;

/**
 * Attempts to recover from a load/render error by reloading the page.
 * Tracks retry count in sessionStorage to prevent infinite reload loops.
 * Resets on successful render via clearErrorReloadCount().
 */
export const attemptErrorRecoveryReload = (error: unknown): void => {
  // Change gate to disable error recovery entirely if it causes issues
  if (!changeGates.getBooleanChangeGate('useErrorRecoveryReload')) {
    return;
  }

  const maxRetries = featureGates.getIntFeatureGate('errorRecoveryMaxRetries', DEFAULT_MAX_RETRIES, { min: 0 });
  // maxRetries of 0 disables the feature
  if (maxRetries <= 0) {
    return;
  }

  try {
    const parsed = parseInt(sessionStorage.getItem(RELOAD_COUNTER_KEY) ?? '0', 10);
    const currentCount = Math.max(0, Number.isNaN(parsed) ? 0 : parsed);

    if (currentCount < maxRetries) {
      sessionStorage.setItem(RELOAD_COUNTER_KEY, (currentCount + 1).toString());
      // Resolve the (gated, bounded) post-flush delay up front so the reload can be scheduled in a
      // finally: a telemetry/teardown throw must NEVER prevent the recovery reload — that is the
      // whole point of recovery. (sessionStorage.setItem above is the one step allowed to abort it,
      // via the outer catch, since without a committed counter we can't bound the retry loop.)
      const reloadDelayMs = featureGates.getIntFeatureGate(
        'errorRecoveryReloadDelayMs',
        DEFAULT_RELOAD_DELAY_MS,
        { min: 0 },
      );
      try {
        TelemetryLogger.Instance.logEvent('LoadErrorRecovery', {
          Action: 'Reload',
          AttemptNumber: currentCount + 1,
          MaxRetries: maxRetries,
          ErrorMessage: toError(error).message,
        });
        console.warn(`HostedWorkspaceUI: load failed, reloading (attempt ${currentCount + 1}/${maxRetries})`);
        // Force-close open trackers BEFORE shutting the sink down so their terminal markers flush;
        // otherwise the reload-triggered beforeunload would cancel them after shutdown and drop them,
        // leaving the load stuck as a Fluid Start-without-End across the reload.
        closeOpenTrackersOnTeardown(toError(error));
        // Flush all pending telemetry before reloading to avoid data loss.
        TelemetryLogger.Instance.shutdown();
      } finally {
        // Defense-in-depth delay buffers the (plausibly async over WebView2 IPC) telemetry egress
        // before the reload truncates in-flight events. Always scheduled, even if teardown threw.
        setTimeout(() => {
          window.location.reload();
        }, reloadDelayMs);
      }
    } else {
      TelemetryLogger.Instance.logError('LoadErrorRecovery', toError(error), {
        ErrorMethod: 'attemptErrorRecoveryReload',
        Action: 'RetriesExhausted',
        AttemptNumber: currentCount,
        MaxRetries: maxRetries,
      });
      console.error(`HostedWorkspaceUI: load failed, retries exhausted (${currentCount}/${maxRetries})`);
    }
  } catch (storageError) {
    // sessionStorage may be unavailable (e.g., storage quota, privacy mode)
    console.error('HostedWorkspaceUI: failed to access sessionStorage for error recovery', storageError);
  }
};

/**
 * Resets the reload counter on successful load+render.
 * Called after the component is confirmed working.
 */
export const clearErrorReloadCount = (): void => {
  try {
    sessionStorage.removeItem(RELOAD_COUNTER_KEY);
  } catch {
    // Ignore sessionStorage errors
  }
};
