import type {
  ProvideDisposable,
} from '@fluidx/loop-types';
import type { BizChatTokenProvider } from '@fluidx/loop-workspace-types';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { getCloudType } from '../utils/Cloud';
import { changeGates } from '../utils/FeatureGates';
import {
  getTokenDefinitionFromResourceStrings,
  getUserAccountType,
  isODSPResource,
  updateOdspResourceForConsumer,
} from './HostAuthServiceUtils';
import type { Identity } from './HostAuthServiceUtils';
import { NestedAppAuthService } from './NestedAppAuthService';
import {
  BIZCHAT_CORE_APPID
} from './constants';
import { type TokenType } from './endpoints';
import { Resources as ResourcesMSA } from './endpoints/MSAEndpoints';
import { Resources as ResourcesPublic } from './endpoints/PublicEndpoints';
import {
  CLOUD_TYPE_TO_REDIRECT,
  extractResourceForPreauth,
  isOneDriveConsumer,
} from './utils';

export class BizChatAuthServiceV1 implements BizChatTokenProvider, ProvideDisposable {
  private hasLoggedUnknownOboRequest = false;
  private appId = BIZCHAT_CORE_APPID;
  private redirectUri = CLOUD_TYPE_TO_REDIRECT[getCloudType()];
  private identity: Identity;
  private nestedAppAuthService: NestedAppAuthService;

  constructor(identity: Identity) {
    this.identity = identity;
    this.nestedAppAuthService = new NestedAppAuthService(this.appId, this.redirectUri, identity);
  }

  public aeaToken = () => this.nestedAppAuthService.getToken({ tokenType: 'AEA' });
  public amsToken = (shouldForceRefresh?: boolean, _headers?: Headers) => this.nestedAppAuthService.getToken({ tokenType: 'AMS', forceRefresh: shouldForceRefresh });
  public apiHub = () => this.nestedAppAuthService.getToken({ tokenType: 'APIHUB' });
  public apiSkype = () => this.nestedAppAuthService.getToken({ tokenType: 'SKYPE' });
  public apiUrlp = () => this.nestedAppAuthService.getToken({ tokenType: 'URLP' });
  public augloop = (_headers?: Headers, claims?: { value?: string }) => this.nestedAppAuthService.getToken({ tokenType: 'AUGLOOP', claims: claims?.value });
  public azRms = (_clusterCategory?: string) => Promise.reject(new Error('Azure RMS token not yet supported'));
  public bap = () => this.nestedAppAuthService.getToken({ tokenType: 'BAP' });
  public copilotStudio = (realm: string) => this.nestedAppAuthService.getToken({ tokenType: realm === 'prod' ? 'COPILOTSTUDIOPROD' : 'COPILOTSTUDIOTEST' });
  public coworker = (_realm: string, _forceRefresh?: boolean) => Promise.reject(new Error('Coworker token not yet supported'));
  public dataverse = (_instanceUrl: string) => Promise.reject(new Error('Dataverse token not yet supported'));
  public designer = () => this.nestedAppAuthService.getToken({ tokenType: 'DESIGNERAPPSERVICE' });
  public eligibility = () => Promise.reject(new Error('Eligibility token not yet supported'));
  public feed = (_headers?: Headers, shouldForceRefresh?: boolean, _correlationId?: string) => this.nestedAppAuthService.getToken({ tokenType: 'SUBSTRATE', forceRefresh: shouldForceRefresh });
  public forms = (shouldForceRefresh?: boolean) => this.nestedAppAuthService.getToken({ tokenType: 'FORMS', forceRefresh: shouldForceRefresh });
  public gcs = () => this.nestedAppAuthService.getToken({ tokenType: 'GCS' });
  public graph = () => this.nestedAppAuthService.getToken({ tokenType: 'GRAPH' });
  public iris = () => this.nestedAppAuthService.getToken({ tokenType: 'IRIS' });
  public leact = (shouldForceRefresh?: boolean) => this.nestedAppAuthService.getToken({ tokenType: 'LEACT', forceRefresh: shouldForceRefresh });
  public loki = async () => {
    const tokenString = await this.nestedAppAuthService.getToken({ tokenType: 'LOKI' });
    return {
      accessToken: tokenString,
      expirationTime: 0,
    };
  };
  public m365copilotapp = () => Promise.reject(new Error('M365 Copilot app token not yet supported'));
  public mos = () => this.nestedAppAuthService.getToken({ tokenType: 'METAOS' });
  public mruPlusPlus = () => this.nestedAppAuthService.getToken({ tokenType: 'MRUPLUSPLUS' });
  public oboToken = (resource: string): Promise<string> => {
    // NOTE: BizChat requests the IRIS token via OBO as of initial GA.
    const resourceLowerCase = resource.toLowerCase();
    let resourceURL: URL | undefined;
    try {
      resourceURL = new URL(resourceLowerCase);
    }
    catch (_e) {
      TelemetryLogger.Instance.logError('BizChatAuthError', new Error('Unsupported BizChat obo token request: Maybe invalid request URL'), { ErrorMethod: 'oboToken.parseResourceURL' });
    }

    const tokenDefinition = getTokenDefinitionFromResourceStrings([resourceLowerCase, resourceURL?.origin.toLowerCase() ?? ''], getUserAccountType(this.identity), getCloudType());
    const finalResourceUrl = tokenDefinition?.resource ?? resourceLowerCase;
    const tokenType = tokenDefinition?.tokenType ?? 'UNKNOWN';
    const appendDefaultScope = tokenDefinition?.appendDefaultScope ?? true;
    if (!this.hasLoggedUnknownOboRequest && tokenType === 'UNKNOWN') {
      this.hasLoggedUnknownOboRequest = true;
      TelemetryLogger.Instance.logEvent('GetBizChatToken', {
        AuthAppId: this.appId,
        TokenType: 'OboToken',
        Message: 'Unknown endpoint requested'
      });
    }

    const tokenString = this.nestedAppAuthService.getToken({
      resourceUri: finalResourceUrl,
      tokenType,
      appendDefaultScope,
    });
    return tokenString;
  };
  public ocps = () => this.nestedAppAuthService.getToken({ tokenType: 'OCPS' });
  public odc = async () => {
    const tokenString = await this.nestedAppAuthService.getToken({
      resourceUri: ResourcesMSA.ODC,
      tokenType: 'ODC',
      appendDefaultScope: false,
    });
    return {
      AuthToken: tokenString,
      AuthTokenTtl: undefined,
    };
  };
  public onenote = () => this.nestedAppAuthService.getToken({ tokenType: 'ONENOTE' });
  public orchard = (_clusterCategory: string) => Promise.reject(new Error('Orchard token not yet supported'));
  public outlook = () => this.nestedAppAuthService.getToken({ tokenType: 'OUTLOOK' });
  public pacman = () => this.nestedAppAuthService.getToken({ tokenType: 'PACMAN' });
  public powerAutomate = () => this.nestedAppAuthService.getToken({ tokenType: 'POWERAUTOMATE' });
  public powerPlatform = (clusterCategory: string) => {
    let category: TokenType;
    switch (clusterCategory) {
      case 'prod':
        category = 'PPAPIPROD';
        break;
      case 'preprod':
        category = 'PPAPIPREPROD';
        break;
      case 'test':
        category = 'PPAPITEST';
        break;
      default:
        return Promise.reject(new Error('Unknown clusterCategory'));
    }
    return this.nestedAppAuthService.getToken({ tokenType: category });
  };
  public powerbi = () => this.nestedAppAuthService.getToken({ tokenType: 'POWERBI' });
  public pushChannel = () => this.nestedAppAuthService.getToken({ tokenType: 'FLUIDPUSH' });
  public safeLinks = (isLegacy?: boolean) => this.nestedAppAuthService.getToken({ tokenType: (isLegacy ?? false) ? 'SAFELINKSLEGACY' : 'SAFELINKS' });
  public spo = async (domain: string, _headers?: Headers) => {
    // Preauth contract (matches HostAuthService): strip any caller-supplied
    // scope segment and always request `.default` on the bare resource.
    const resource = extractResourceForPreauth(domain?.toLowerCase() ?? '');

    if (isOneDriveConsumer(this.identity, resource)) {
      return this.odc();
    }

    // First-party SPO: the SPAC well-known GUID (literal equality), any
    // `.sharepoint` host, or ODSP. Everything else falls through to a customer
    // vanity domain (gated) or NAA's canonical SHAREPOINT URL when the gate is off.
    const isOdsp = isODSPResource(resource);
    const isFirstPartySpo =
      resource === ResourcesPublic.SPAC
      || resource.includes('.sharepoint')
      || isOdsp;

    let tokenString: string;
    if (isFirstPartySpo) {
      tokenString = await this.nestedAppAuthService.getToken({
        // ODSP consumer resources must target the /v2 endpoint.
        resourceUri: isOdsp ? updateOdspResourceForConsumer(resource) : resource,
        tokenType: isOdsp ? 'ODSP' : 'SHAREPOINT',
        appendDefaultScope: true,
      });
    } else if (changeGates.getBooleanChangeGate('useSpoVanityDomain')) {
      tokenString = await this.nestedAppAuthService.getToken({
        resourceUri: resource,
        tokenType: 'VANITYODSP',
        appendDefaultScope: true,
      });
    } else {
      // Vanity-disabled fallback: omit resourceUri so NAA resolves the
      // canonical SHAREPOINT URL from the public resource map.
      tokenString = await this.nestedAppAuthService.getToken({ tokenType: 'SHAREPOINT' });
    }

    return {
      AuthToken: tokenString,
      AuthTokenTtl: undefined,
    };
  };
  public substrate = () => this.nestedAppAuthService.getToken({ tokenType: 'SUBSTRATE' });
  public sydney = (shouldForceRefresh?: boolean, _headers?: Headers, _correlationId?: string) => this.nestedAppAuthService.getToken({ tokenType: 'SYDNEY', forceRefresh: shouldForceRefresh });
  public teams = () => this.nestedAppAuthService.getToken({ tokenType: 'TEAMS' });
  public tenantFeedback = () => this.nestedAppAuthService.getToken({ tokenType: 'TENANTFEEDBACK' });
  public thirdPartyToken = (_resource?: string) => Promise.reject(new Error('Third party token not yet supported'));
  public tgsToken = () => Promise.reject(new Error('TGS token not yet supported'));
  public trouter = () => this.nestedAppAuthService.getToken({ tokenType: 'TROUTER' });
  public turbo = () => Promise.reject(new Error('Turbo token not yet supported'));
  public vivaSubstrate = (_headers?: Headers, _claims?: { value?: string }, _correlationId?: string) => Promise.reject(new Error('Viva Substrate token not yet supported'));
  public yammer = () => this.nestedAppAuthService.getToken({ tokenType: 'YAMMER' });

  public get BizChatTokenProvider(): BizChatTokenProvider {
    return this;
  }

  public get Disposable() {
    return this;
  }

  public dispose() {
    this.clearCache();
  }

  public clearCache() {
    this.nestedAppAuthService.clearCache();
  }

  public setIdentity(identity: Identity): void {
    this.identity = identity;
    this.nestedAppAuthService.setIdentity(identity);
  }
}

// Compile-time completeness guard: fails the build if any optional TokenProviders member is left
// unimplemented (e.g. a future upstream-added token). Asserts the INSTANCE type — NOT .prototype,
// since the token methods are arrow-function instance fields. No runtime effect.
const _assertTokenProviderComplete: Required<BizChatTokenProvider> =
  null as unknown as BizChatAuthServiceV1;
void _assertTokenProviderComplete;
