/*
  Private API contract:
  In SDX when we invoke a private API, we send the following object (serialized) to native:
    {
      __api: <API name>,
      ...<API args>,
    }
  In the native side, this API request is handled by
    SDXPrivateApiImpl in the HostedWorkspace component

  The above method handles the request and send back the response.
  If the method is handled successfully, the response should be like:
    {
      __error: 0,
      ...<response properties>,
    }
  or, if there are any errors:
    {
      __error: <HRESULT>,
    }

  In the case when this method is an async method, the API response goes like:
    {
      __error: 0,
      __async: <GUID>,
    }
  where the field `__async` is an operation id.
  The native client will raise events sending back the async method result.
  In this class, `ApiBridge` we cache a GUID-promise map.
  Once such event is raised, we mark the corresponding promise as fulfilled.

  The async result event payload should be like:
    {
      __type: 'AsyncApiResult',
      __apiId: <GUID>,
      __error: <0 | HRESULT>,
      ...<response properties>,
    }

  For a native event, to differentiate it from an async result event,
  the payload goes like:
    {
      __type: 'Event',
      __eventName: <Name>,
      ...<event properties>,
    }
*/

import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { PromiseCompat } from '../utils/promise';
import type {
  PrivateApi,
  PrivateApiSignatures,
} from './Api';
import {
  InvalidArgumentsError,
  NativeInteropError,
  NotImplementedError,
} from './Error';

declare type NullaryPrivateApi = keyof {
  [
    K in PrivateApi as PrivateApiSignatures[K]['args'] extends void
      ? K
      : never
  ]: unknown;
};

declare type NativeEventArgs =
  | {
      __type: 'AsyncApiResult';
      __apiId: string;
      __error: number;
    }
  | {
      __type: 'Event';
      __eventName: string;
    };

declare type DeferredApi<T = unknown> = {
  api: string;
  resolve: (result: T) => void;
  reject: (error: unknown) => void;
};

declare type NativeEventHandler = (event: string, args: unknown) => void;

export class ApiBridge {
  private readonly defers: Record<string, DeferredApi> = {};
  private readonly results: Record<string, Extract<NativeEventArgs, { __type: 'AsyncApiResult' }>> = {};
  private readonly eventHandlers: NativeEventHandler[] = [];
  private initialized = false;
  private eventRevoker: OfficeFirstParty.PrivateEventRevoker | undefined;

  async initialize() {
    if (this.initialized) {
      return;
    }
    this.initialized = true;

    if (window.OfficeFirstParty && OfficeFirstParty.PrivateApi?.onPrivateEvent) {
      const onNativeEvent = this.onNativeEvent.bind(this);

      // the promise is rejected with RichApi.Error if the native client
      // does not provide an `ISdxPrivateApi` implementation.
      try {
        const revoker = await OfficeFirstParty.PrivateApi.onPrivateEvent(onNativeEvent);
        this.eventRevoker = revoker;
      } catch (error) {
        this.eventRevoker = undefined;
        if (__IS_DEV__) {
          throw error;
        }
      }
    }
  }

  cleanup() {
    if (this.eventRevoker) {
      this.eventRevoker();
    }
    this.eventRevoker = undefined;
  }

  registerEvent(handler: NativeEventHandler) {
    this.eventHandlers.push(handler);
  }

  unregisterEvent(handler: NativeEventHandler) {
    const index = this.eventHandlers.indexOf(handler);
    if (index >= 0) {
      this.eventHandlers.splice(index, 1);
    }
  }

  private onNativeEvent(eventData: string) {
    const event = JSON.parse(eventData) as NativeEventArgs;
    if (event.__type === 'AsyncApiResult') {
      const {
        __type,
        __apiId: apiId,
        __error: error,
        ...ret
      } = event;
      if (apiId in this.defers) {
        const deferred = this.defers[apiId];
        delete this.defers[apiId];
        if (error !== 0) {
          const exception = ApiBridge.createErrorObject(deferred.api, error);
          deferred.reject(exception);
        } else {
          deferred.resolve(ret);
        }
      } else {
        // Sometimes the AsyncApiResult event can come earlier than
        // the `execute` promise being resolved due to native thread scheduling.
        // Hence, here we cache the result and consume the value later.
        this.results[apiId] = event;
      }
    } else if (event.__type === 'Event') {
      const {
        __type,
        __eventName: eventName,
        ...args
      } = event;
      for (const handler of this.eventHandlers) {
        handler(eventName, args);
      }
    }
  }

  execute<TApi extends NullaryPrivateApi>(
    api: TApi
  ): Promise<PrivateApiSignatures[TApi]['ret']>;
  execute<TApi extends PrivateApi>(
    api: TApi,
    args: PrivateApiSignatures[TApi]['args']
  ): Promise<PrivateApiSignatures[TApi]['ret']>;
  execute<TApi extends PrivateApi>(
    api: TApi,
    args?: PrivateApiSignatures[TApi]['args']
  ): Promise<PrivateApiSignatures[TApi]['ret']> {
    if (!window.OfficeFirstParty || !OfficeFirstParty.PrivateApi?.execute) {
      return Promise.reject(new NativeInteropError(NativeInteropError.E_FAIL, 'PrivateApi is not available'));
    }

    const obj = Object.assign({
      __api: api,
    }, args);
    const message = JSON.stringify(obj);

    return OfficeFirstParty.PrivateApi.execute(message).then((result) => {
      const response = JSON.parse(result) as PrivateApiSignatures[TApi]['ret'] & {
        __error: number;
        __async: string | undefined;
      };
      const {
        __error: error,
        __async: asyncId,
        ...ret
      } = response;

      if (error !== 0) {
        const exception = ApiBridge.createErrorObject(api, error);
        TelemetryLogger.Instance.logError('ApiBridgeError', error, {
          ErrorMethod: api, ErrorDetails: exception.message, ErrorCode: exception.errorCode, ErrorName: exception.name,
        });
        throw exception;
      }

      if (typeof asyncId !== 'string') {
        return ret as unknown as PrivateApiSignatures[TApi]['ret'];
      } else if (!(asyncId in this.results)) {
        const {
          promise,
          resolve,
          reject,
        } = PromiseCompat.withResolvers();
        this.defers[asyncId] = {
          api,
          resolve,
          reject,
        };
        return promise as Promise<PrivateApiSignatures[TApi]['ret']>;
      } else {
        const {
          __type,
          __apiId,
          __error: error,
          ...ret
        } = this.results[asyncId];
        delete this.results[asyncId];
        if (error !== 0) {
          const exception = ApiBridge.createErrorObject(api, error);
          throw exception;
        } else {
          return ret as PrivateApiSignatures[TApi]['ret'];
        }
      }
    });
  }

  private static createErrorObject(api: string, error: number): NativeInteropError {
    const convertedError = error >>> 0;
    switch (convertedError) {
      case NotImplementedError.E_NOTIMPL:
        return new NotImplementedError(`The private API '${api}' is not implemented`);
      case InvalidArgumentsError.E_INVALIDARG:
        return new InvalidArgumentsError(`Invalid arguments are passed to the private API '${api}'`);
      default:
        return new NativeInteropError(error, `Calling private API '${api}' gives error code: ${error} | ${convertedError} (converted error code)`);
    }
  }
}
