import type { UserContext } from '@fluidx/loop-types';
import type { HostScenarioLifecycle } from '@fluidx/telemetry';
import { OfficeFluidLogger } from '@fluidx/telemetry';
import { getAudience } from '../utils/Environment';
import { HostAppSettings } from '../utils/HostAppSettings';
import { OfficeTelemetrySinkWrapper } from './OfficeTelemetrySinkWrapper';

export const createOfficeFluidTelemetryLogger = (
  userContext: UserContext,
  hostScenarioLifecycle?: HostScenarioLifecycle,
  hostScenarioEntryPoint?: string,
  hostScenarioName?: string,
  hostScenarioStartTime?: number
) => {
  const hostCorrelationId = HostAppSettings.getCorrelationId();
  const hostSessionId = HostAppSettings.getSessionId();

  // Default values for host scenario
  const defaultHostScenarioLifecycle = 'Load';
  const defaultHostScenarioName = 'Notebook';
  const defaultHostScenarioEntryPoint = 'NotebooksModuleHome';
  const defaultHostScenarioStartTime = Date.now();

  return new OfficeFluidLogger({
    hostTelemetryContext: {
      hostName: 'OneNote',
      hostAppPlatform: HostAppSettings.getPlatform(),
      hostAppName: 'OneNote',
      hostCorrelationId,
      hostScenarioLifecycle:
        hostScenarioLifecycle ?? defaultHostScenarioLifecycle,
      hostScenarioName: hostScenarioName ?? defaultHostScenarioName,
      hostScenarioEntryPoint:
        hostScenarioEntryPoint ?? defaultHostScenarioEntryPoint,
      hostScenarioStartTime:
        hostScenarioStartTime ?? defaultHostScenarioStartTime,
      hostSessionId,
      hostAppVersion: Office.context.diagnostics.version,
      userContext
    },
    hostTelemetrySink: OfficeTelemetrySinkWrapper.Instance,
    audience: getAudience(),
  });
};
