import { EventEmitter } from 'events';
import type { ExistingFileInfo } from '@fluidx/1p-loop-types';
import type {
  LoopWorkspaceData, NavigatedRouteParams, NavigationParams, WorkspaceAndPageManager, WorkspaceAndPageManagerEvents, WorkspaceNavigationHandler,
} from '@fluidx/loop-workspace-types';
import type {
  InteropWorkspaceDataModelCollection,
} from '../../data/Models';
import {
  TranslateNotebookNavigationData, TranslatePageNavigationData, TranslateWorkspaceData,
} from '../../data/Models';
import type { NativeInteropError } from '../../interop';
import { DataAction, NotifyClient } from '../../interop';
import { TelemetryLogger } from '../../telemetry/TelemetryLogger';
import { changeGates } from '../../utils/FeatureGates';

export const WorkspaceManagerEvents = {
  navigate: 'navigateTo',
};

type ActivePageParams = {
  docUrl: string;
  podId: string;
};

export class WorkspaceManager extends EventEmitter {
  private workspaceNavigationHandler: WorkspaceNavigationHandler | undefined;
  private workspaceAndPageManager: WorkspaceAndPageManager | undefined;
  private workspaceMap = new Map<string, LoopWorkspaceData>();
  private forceSelectNextAdd = false;
  private activePageParams: ActivePageParams | undefined;
  private pendingNavigation:
    | {
        params: NavigationParams;
        firstBufferedAtMs: number;
        latestBufferedAtMs: number;
        supersededCount: number;
      }
    | undefined;

  private requireWorkspaceAndPageManager(): WorkspaceAndPageManager {
    if (!this.workspaceAndPageManager) {
      throw new Error('workspaceAndPageManager not set -- Loop component not yet loaded');
    }
    return this.workspaceAndPageManager;
  }

  private clearActivePageParams() {
    this.activePageParams = undefined;
  }

  // Bypass navigation if the active page params match the requested navigation params.
  // This is useful for preventing unnecessary navigation events when the user is already on the page they want to navigate to.
  // There is a bug in Loop where navigating to the same page with the same parameters causes the page component to go missing.
  private canNavigate(params: NavigationParams): boolean {
    if (params.route !== 'page') {
      return true;
    }
    const activePageParams = this.getActivePageParams();
    if (!activePageParams) {
      return true;
    }
    if (
      params.docUrl === activePageParams.docUrl &&
      params.mfsPodId === activePageParams.podId
    ) {
      // If the active page params match the requested params, do not navigate again
      return false;
    }
    return true;
  }

  public setActivePageParams(docUrl: string, podId: string) {
    this.activePageParams = {
      docUrl,
      podId,
    };
  }

  public getActivePageParams(): ActivePageParams | undefined {
    return this.activePageParams;
  }

  public async Reset(): Promise<void> {
    this.workspaceMap.clear();
    return Promise.resolve();
  }

  public async DeleteNotebook(
    podId: string,
  )
  {
    const startTime = Date.now();
    try {
      const mgr = this.requireWorkspaceAndPageManager();
      await mgr.deleteWorkspace(podId);
    }
    catch (error) {
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'DeleteNotebook',
        ErrorDetails: 'Error Deleting Notebook',
        Duration: durationMS,
      });
      throw error;
    }
  }

  public async RenameNotebook(
    podId: string,
    name: string,
  )
  {
    const startTime = Date.now();
    try {
      const mgr = this.requireWorkspaceAndPageManager();
      await mgr.renameWorkspace(podId, name);
    }
    catch (error) {
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'RenameNotebook',
        ErrorDetails: 'Error Renaming Notebook',
        Duration: durationMS,
      });
      throw error;
    }
  }

  public async ToggleFavoriteNotebook(
    podId: string,
  )
  {
    const startTime = Date.now();
    try {
      const mgr = this.requireWorkspaceAndPageManager();
      await mgr.toggleFavoriteWorkspace(podId);
    }
    catch (error) {
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'ToggleFavoriteNotebook',
        ErrorDetails: 'Error toggling favorite on Notebook',
        Duration: durationMS,
      });
      throw error;
    }
  }

  public async NavigateTo(params: NavigationParams) {
    // Notify subscribers of the navigation request first. This is what renders the UI when the
    // SDX initially loaded UI-less, and it must fire even when canNavigate dedupes the request
    // below (e.g. a buffered same-page replay) so the deferred view still paints.
    this.emit(WorkspaceManagerEvents.navigate);

    if (!this.canNavigate(params)) {
      return;
    }

    // Clear the active page params on navigation
    this.clearActivePageParams();

    if (!this.workspaceNavigationHandler) {
      if (changeGates.getBooleanChangeGate('useNavigationBuffering')) {
        // Handler not attached yet (Loop component still loading). Buffer the most recent
        // request (last-write-wins) and replay it once FlushPendingNavigation runs.
        const existing = this.pendingNavigation;
        const bufferedAtMs = Date.now();
        this.pendingNavigation = {
          params,
          // Preserve the first timestamp (total time a navigation was pending); refresh the
          // latest one (age of the request that will actually be replayed).
          firstBufferedAtMs: existing ? existing.firstBufferedAtMs : bufferedAtMs,
          latestBufferedAtMs: bufferedAtMs,
          supersededCount: existing ? existing.supersededCount + 1 : 0,
        };
        TelemetryLogger.Instance.logEvent('NavigationBuffered', {
          NavRoute: params.route,
          SupersededCount: this.pendingNavigation.supersededCount,
        });
        return;
      }
      TelemetryLogger.Instance.logError('WorkspaceManagerError', new Error('workspaceNavigationHandler is not set'), {
        ErrorMethod: 'NavigateTo',
        ErrorDetails: 'Navigation handler not available',
      });
      return;
    }

    const startTime = Date.now();
    try {
      await this.workspaceNavigationHandler.navigateTo(params);
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logEvent('NavigateTo', {
        NavRoute: params.route,
        Duration: durationMS,
      });
      if (params.route === 'page' && params.mfsPodId) {
        this.setActivePageParams(params.docUrl, params.mfsPodId);
      }
    } catch (error) {
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'NavigateTo',
        ErrorDetails: 'navigateTo API failed',
        Duration: durationMS,
      });
      throw error;
    }
  }

  public async AddReferenceTo(
    podId: string,
    refUrls: string[],
    refTitles: string[],
  ) {
    try {
      const mgr = this.requireWorkspaceAndPageManager();

      if (refUrls.length !== refTitles.length) {
        throw new Error(
          'Reference URLs and titles arrays must have the same length',
        );
      }

      const addPageToWorkspacePromises: Promise<void>[] = [];
      for (let i = 0; i < refUrls.length; i++) {
        addPageToWorkspacePromises.push(
          mgr.addPageToWorkspace(
            refUrls[i],
            refTitles[i],
            podId,
          ),
        );
      }

      await Promise.all(addPageToWorkspacePromises);
      void NotifyClient.addReferenceToNotebookResultStatus({ success: true });
    } catch (error) {
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'AddReferenceTo',
        ErrorDetails:
          'Error while adding ' + refUrls.length + ' references to notebook',
      });

      void NotifyClient.addReferenceToNotebookResultStatus({ success: false });
      throw error;
    }
  }

  public async ProcessWorkspaces(): Promise<void> {
    try {
      const mgr = this.requireWorkspaceAndPageManager();

      const startTime = Date.now();
      // getWorkspaces returns a list sorted by interaction time; more recently interacted are earlier in the list.
      // According to Loop, we only should call this once and then let the data events keep us up-to-date.
      const workspaces = await mgr.getWorkspaces();
      const validWorkspaces: LoopWorkspaceData[] = [];
      this.workspaceMap.clear();
      workspaces.forEach(item => {
        if (item.mfsPodId === undefined || item.spoId === undefined) {
          return;
        }

        validWorkspaces.push(item);
        this.workspaceMap.set(item.mfsPodId, item);
      });
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logEvent('GetWorkspaces', {
        TotalWorkspaceCount: workspaces.length,
        ViableWorkspaceCount: validWorkspaces.length,
        Duration: durationMS,
      });
      const nativeInteropWorkspaces = validWorkspaces.map(item => {
        return TranslateWorkspaceData(item, false);
      });

      const workspaceCollection: InteropWorkspaceDataModelCollection = {
        workspaces: nativeInteropWorkspaces,
      };

      void DataAction.setWorkspaces(workspaceCollection).catch(
        (error: NativeInteropError) => {
          TelemetryLogger.Instance.logError('DataActionError', error, {
            ErrorMethod: 'ProcessWorkspaces',
            ErrorDetails: 'Failed to notify client of data action event',
            ErrorEvent: 'setWorkspaces',
          });
        },
      );
    } catch (error) {
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'ProcessWorkspaces',
        ErrorDetails: 'Error processing workspaces',
      });

      // Try notifying the client we failed to process workspaces.
      void DataAction.failedToProcessWorkspaces().catch(
        (error: NativeInteropError) => {
          // We failed to notify the client of the error, so log that the notification failed.
          TelemetryLogger.Instance.logError('DataActionError', error, {
            ErrorMethod: 'failedToProcessWorkspaces',
            ErrorDetails: 'Failed to notify client of data action failure',
          });
        },
      );

      throw error;
    }
  }

  public async GetWorkspaceForPage(fileInfo: ExistingFileInfo) {
    const startTime = Date.now();
    try {
      const mgr = this.requireWorkspaceAndPageManager();

      const workspace = await mgr.getWorkspaceForPage(
        fileInfo,
      );
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logEvent('GetWorkspaceForPage', {
        FoundWorkspace: workspace !== undefined,
        Duration: durationMS,
      });
      return workspace;
    } catch (error) {
      const durationMS = Date.now() - startTime;
      TelemetryLogger.Instance.logError('WorkspaceManagerError', error, {
        ErrorMethod: 'GetWorkspaceForPage',
        ErrorDetails: 'Error getting workspace for page',
        Duration: durationMS,
      });
      throw error;
    }
  }

  public SetWorkspaceAndPageManager(
    manager: WorkspaceAndPageManager,
  ) {
    this.workspaceAndPageManager = manager;
  }

  public SetWorkspaceNavigationHandler(
    handler: WorkspaceNavigationHandler,
  ) {
    this.workspaceNavigationHandler = handler;
  }

  // Replays a navigation request buffered by NavigateTo while the handler was unavailable.
  // Call this only after the handler is set and the component 'navigation' subscription is wired,
  // so a replayed request behaves identically to a normal host navigation.
  public FlushPendingNavigation(): void {
    const pending = this.pendingNavigation;
    // Clear before replay so the replayed NavigateTo can't re-buffer or loop.
    this.pendingNavigation = undefined;
    if (!pending) {
      return;
    }
    const now = Date.now();
    TelemetryLogger.Instance.logEvent('NavigationBufferFlushed', {
      NavRoute: pending.params.route,
      BufferedAgeMs: now - pending.latestBufferedAtMs,
      TotalPendingAgeMs: now - pending.firstBufferedAtMs,
      SupersededCount: pending.supersededCount,
    });
    // NavigateTo logs its own failures; swallow here to satisfy no-floating-promises.
    void this.NavigateTo(pending.params).catch(() => undefined);
  }

  public async onWorkspaceListChangedEvent(
    event: WorkspaceAndPageManagerEvents['workspaceListChanged'],
  ) {
    try {
      let workspace: LoopWorkspaceData | undefined;
      const type = event.type;
      const forceSetAsSelected = this.forceSelectNextAdd;
      switch (type) {
        case 'add':
          workspace = event.workspace;
          if (workspace === undefined) {
            throw new Error(
              `Undefined workspace for workspaceListChanged event type: ${event.type}`,
            );
          }
          if (workspace.mfsPodId === undefined) {
            throw new Error(
              `Malformed workspace podId for event type: ${event.type}`,
            );
          }
          if (workspace.spoId === undefined) {
            throw new Error(
              `Malformed workspace spoId for event type: ${event.type}`,
            );
          }
          this.forceSelectNextAdd = false;
          this.workspaceMap.set(workspace.mfsPodId, workspace);
          void DataAction.updateWorkspace(
            TranslateWorkspaceData(workspace, forceSetAsSelected),
          ).catch((error: NativeInteropError) => {
            TelemetryLogger.Instance.logError('DataActionError', error, {
              ErrorMethod: 'onWorkspaceListChangedEvent',
              ErrorDetails: 'Failed to notify client of data action event',
              ErrorEvent: event.type,
            });
          });
          break;

        case 'update':
          workspace = event.workspace;
          if (workspace === undefined) {
            throw new Error(
              `Undefined workspace for workspaceListChanged event type: ${event.type}`,
            );
          }
          if (workspace.mfsPodId === undefined) {
            throw new Error(
              `Malformed workspace podId for event type: ${event.type}`,
            );
          }
          if (workspace.spoId === undefined) {
            throw new Error(
              `Malformed workspace spoId for event type: ${event.type}`,
            );
          }
          this.workspaceMap.set(workspace.mfsPodId, workspace);
          void DataAction.updateWorkspace(
            TranslateWorkspaceData(workspace, false),
          ).catch((error: NativeInteropError) => {
            TelemetryLogger.Instance.logError('DataActionError', error, {
              ErrorMethod: 'onWorkspaceListChangedEvent',
              ErrorDetails: 'Failed to notify client of data action event',
              ErrorEvent: event.type,
            });
          });
          // We don't have a separate rename event yet, so just apply this update again as a rename.
          // On newer clients, we're separating applying rename out from update in preparation
          // for getting a dedicated rename event from Loop.
          void DataAction.renameWorkspace(
            TranslateWorkspaceData(workspace, false),
          ).catch((error: NativeInteropError) => {
            TelemetryLogger.Instance.logError('DataActionError', error, {
              ErrorMethod: 'onWorkspaceListChangedEvent',
              ErrorDetails: 'Failed to notify client of data action event',
              ErrorEvent: 'rename',
            });
          });
          break;

        case 'remove':
          if (event.mfsPodId === undefined) {
            throw new Error(
              `Malformed workspace podId for event type: ${event.type}`,
            );
          }
          this.workspaceMap.delete(event.mfsPodId);
          void DataAction.removeWorkspace(
            TranslateWorkspaceData(
              event as unknown as LoopWorkspaceData,
              false,
            ),
          ).catch((error: NativeInteropError) => {
            TelemetryLogger.Instance.logError('DataActionError', error, {
              ErrorMethod: 'onWorkspaceListChangedEvent',
              ErrorDetails: 'Failed to notify client of data action event',
              ErrorEvent: event.type,
            });
          });
          break;

        default:
          throw new Error(`Unhandled workspaceListChanged event type: ${type}`);
      }
    } catch (error) {
      TelemetryLogger.Instance.logError(
        'ComponentDataWorkspaceListChangedEventError',
        error,
        {
          ErrorMethod: 'onWorkspaceListChangedEvent',
          ErrorDetails: `Error handling workspaceListChanged event type: ${event.type}`,
        },
      );
      throw error;
    }
  }

  public async onComponentNavigationEvent(data: NavigatedRouteParams) {
    // Clear the active page params on navigation event
    this.clearActivePageParams();
    if (this.forceSelectNextAdd) {
      this.forceSelectNextAdd = false;
    }
    try {
      if (data.route === 'notebooks') {
        void NotifyClient.navigateToHomeEvent().catch(
          (error: NativeInteropError) => {
            TelemetryLogger.Instance.logError('NotifyClientError', error, {
              ErrorMethod: 'onComponentNavigationEvent',
              ErrorDetails: 'Failed to notify client of navigation event',
              NavigationRoute: data.route,
            });
          },
        );
      } else if (data.route === 'notebook') {
        if ('createId' in data) {
          // CreateNotebookParams; this means the LWC navigated to a newly created unattached workspace.
          this.forceSelectNextAdd = true;
          return;
        }
        void NotifyClient.navigateToNotebookEvent(
          TranslateNotebookNavigationData(data),
        ).catch((error: NativeInteropError) => {
          TelemetryLogger.Instance.logError('NotifyClientError', error, {
            ErrorMethod: 'onComponentNavigationEvent',
            ErrorDetails: 'Failed to notify client of navigation event',
            NavigationRoute: data.route,
          });
        });
      } else if (data.route === 'createNotebook') {
        // This means the LWC is showing the create notebook UX.
        // We don't need to notify the client of this event.
        return;
      } else if (data.route === 'page') {
        if (data.mfsPodId !== undefined) {
          this.setActivePageParams(data.docUrl, data.mfsPodId);
        }
        void NotifyClient.navigateToPageEvent(
          TranslatePageNavigationData(data),
        ).catch((error: NativeInteropError) => {
          TelemetryLogger.Instance.logError('NotifyClientError', error, {
            ErrorMethod: 'onComponentNavigationEvent',
            ErrorDetails: 'Failed to notify client of navigation event',
            NavigationRoute: data.route,
          });
        });
      } else {
        throw new Error(`Unhandled component navigation event: ${data.route}`);
      }
    } catch (error) {
      TelemetryLogger.Instance.logError(
        'ComponentNavigationEventError',
        error,
        {
          ErrorMethod: 'onComponentNavigationEvent',
          ErrorDetails: `Error handling navigation event for route: ${data.route}`,
        },
      );
      throw error;
    }
  }
}
