import type { CloudType } from '../utils/Cloud';
import { featureGates } from '../utils/FeatureGates';
import type { Identity } from './HostAuthServiceUtils';
import {
  AUTH_ATTEMPT_LIMIT_DEFAULT,
  AUTH_ATTEMPT_LIMIT_MAX,
  AUTH_ATTEMPT_LIMIT_MIN,
  AUTH_BACKOFF_BASE_MS_DEFAULT,
  AUTH_BACKOFF_BASE_MS_MAX,
  AUTH_BACKOFF_BASE_MS_MIN,
  AUTH_BACKOFF_MAX_MS_DEFAULT,
  AUTH_BACKOFF_MAX_MS_MAX,
  AUTH_BACKOFF_MAX_MS_MIN,
  SHAREPOINT_CONSUMER_APPID,
} from './constants';

// Re-export error utilities
export {
  MappedError,
  NAAError,
  SSOError,
  toError,
  unwrapAuthTokenRejectedPromiseIfNeeded,
  getMappedErrorStringMessage,
  isRetryableNestedAppAuthError,
  isRetryableSSOAuthError,
} from '../utils/ErrorUtils';

// This enum maps to the AccountType enum in the Identity CoreAPI Library
// identity/coreapi/public/IdentityProvider.h
enum AccountType {
  Unknown = 0,
  LiveId = 1,
  OrgId = 2,
  ActiveDirectory = 3,
  ADAL = 4,
  SSPI = 5,
}

/**
 * Resolves the current value of `authAttemptLimit`, clamped to
 * [{@link AUTH_ATTEMPT_LIMIT_MIN}, {@link AUTH_ATTEMPT_LIMIT_MAX}], falling
 * back to {@link AUTH_ATTEMPT_LIMIT_DEFAULT} when the gate is unset.
 *
 * Read at retry-loop entry — not per-attempt — so a single retry chain
 * always uses a consistent attempt budget.
 */
export const getAuthAttemptLimit = (): number =>
  featureGates.getIntFeatureGate('authAttemptLimit', AUTH_ATTEMPT_LIMIT_DEFAULT, {
    min: AUTH_ATTEMPT_LIMIT_MIN,
    max: AUTH_ATTEMPT_LIMIT_MAX,
  });

/**
 * Resolves the current value of `authBackoffBaseMs`, clamped to
 * [{@link AUTH_BACKOFF_BASE_MS_MIN}, {@link AUTH_BACKOFF_BASE_MS_MAX}].
 * Internal to this module; consumers should call
 * {@link exponentialBackoffDelay} which reads this on each invocation.
 */
const getAuthBackoffBaseMs = (): number =>
  featureGates.getIntFeatureGate('authBackoffBaseMs', AUTH_BACKOFF_BASE_MS_DEFAULT, {
    min: AUTH_BACKOFF_BASE_MS_MIN,
    max: AUTH_BACKOFF_BASE_MS_MAX,
  });

/**
 * Resolves the current value of `authBackoffMaxMs`, clamped to
 * [{@link AUTH_BACKOFF_MAX_MS_MIN}, {@link AUTH_BACKOFF_MAX_MS_MAX}].
 * Internal to this module; consumers should call
 * {@link exponentialBackoffDelay} which reads this on each invocation.
 */
const getAuthBackoffMaxMs = (): number =>
  featureGates.getIntFeatureGate('authBackoffMaxMs', AUTH_BACKOFF_MAX_MS_DEFAULT, {
    min: AUTH_BACKOFF_MAX_MS_MIN,
    max: AUTH_BACKOFF_MAX_MS_MAX,
  });

/**
 * Waits an exponentially-growing, jittered backoff before the next retry
 * attempt. Gate values are re-read on every call so host-side gate flips
 * apply mid-session without requiring an SDX restart.
 *
 * Schedule (unjittered): `delay = min(base × 2^(attempt - 1), max)`.
 * Jitter is ±25% of the computed delay (uniform), applied to avoid
 * lock-step retries across many SDX instances hitting the same
 * downstream rate limit.
 */
export async function exponentialBackoffDelay(attemptCount: number): Promise<void> {
  const base = getAuthBackoffBaseMs();
  const max = getAuthBackoffMaxMs();
  const exponent = Math.max(1, attemptCount) - 1;
  const baseDelay = Math.min(base * Math.pow(2, exponent), max);
  // Jitter: uniform ±25% to avoid lock-step retry storms.
  const jitter = baseDelay * (0.75 + Math.random() * 0.5);
  await new Promise(resolve => setTimeout(resolve, jitter));
}

export const isOrgId = (accountType: number | undefined): boolean => {
  return accountType === AccountType.OrgId || accountType === AccountType.ADAL;
};

export const isMSA = (accountType: number | undefined): boolean => {
  return accountType === AccountType.LiveId;
};

