export const isOneDriveConsumer = (identity: Identity | undefined, resource: string): boolean => {
  if (!identity) {
    return false;
  }
  const oneDriveDomains = ['api.onedrive.com', 'onedrive.live.com', SHAREPOINT_CONSUMER_APPID];
  return isMSA(identity.identityType) && oneDriveDomains.some(domain => resource.includes(domain));
};

/**
 * Returns true when `value` ends with the AAD default scope suffix `/.default`
 * (case-insensitive). Used to avoid appending `/.default` twice when a caller
 * may pass either a bare resource or a pre-scoped value.
 */
export const hasDefaultScopeSuffix = (value: string): boolean => {
  return value.toLowerCase().endsWith('/.default');
};

/**
 * Strips a trailing `/.default` suffix (case-insensitive) if present, else
 * returns the input unchanged. Preserves casing of the remaining string —
 * pair with {@link hasDefaultScopeSuffix} when the detection itself matters.
 */
export const stripScopeSuffix = (value: string): string => {
  return hasDefaultScopeSuffix(value) ? value.substring(0, value.length - '/.default'.length) : value;
};

/**
 * Extracts the common resource URI from an MSAL-style scopes array by
 * taking everything before the last `/` of each scope.
 *
 * - Returns `''` when no scope contains a `/` separator.
 * - Throws when scopes resolve to different resources (caller programmer
 *   error). Callers are expected to wrap with their own telemetry tag.
 */
export const getResourceForScopes = (scopes: string[]): string => {
  let resource: string | undefined;
  scopes.forEach((scope) => {
    const separator = scope.lastIndexOf('/');
    const candidate = separator > 0 ? scope.substring(0, separator).toLowerCase() : '';
    if (resource === undefined) {
      resource = candidate;
    } else if (resource !== candidate) {
      throw new Error('All scopes must have the same resource');
    }
  });

  return resource ?? '';
};

const GUID_SCOPE_PATTERN = /^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\/.+$/;

/**
 * Returns the bare resource for a preauth `.default` token request, mirroring
 * HostAuthService's contract: any caller-supplied scope segment is stripped,
 * and the cache always holds a `.default` token per resource regardless of
 * the specific permission the caller originally requested.
 *
 * Trailing slashes on the input are trimmed so `<x>/.default/` is treated
 * the same as `<x>/.default`.
 *
 * Rules (after trailing-slash trim):
 *   - `<x>/.default`        → `<x>`         (case-insensitive)
 *   - `<guid>/<permission>` → `<guid>`      (GUID lower-cased)
 *   - bare GUID or URL      → unchanged
 *   - `<url>/<permission>`  → unchanged     (ambiguous with site paths like
 *                                            `/sites/x`; URL callers must use
 *                                            `/.default` or send a bare URL)
 */
export const extractResourceForPreauth = (input: string): string => {
  const normalized = input.replace(/\/+$/, '');
  if (hasDefaultScopeSuffix(normalized)) {
    return stripScopeSuffix(normalized);
  }
  const guidMatch = normalized.toLowerCase().match(GUID_SCOPE_PATTERN);
  return guidMatch ? guidMatch[1] : normalized;
};
