import type { Disposable, ProvideTelemetryConfig } from '@fluidx/loop-types';
import { HostAppSettings } from '../utils/HostAppSettings';

class TelemetryConfigProvider implements ProvideTelemetryConfig, Disposable {
  Disposable = this;

  dispose(): void {
    return;
  }

  get TelemetryConfig() {
    return this;
  }

  get disallowServiceTelemetry() {
    return false;
  }

  get hostCorrelationId() {
    return HostAppSettings.getCorrelationId();
  }

  get hostSessionId() {
    return HostAppSettings.getSessionId();
  }
}

export const createTelemetryConfigProvider = () => {
  return new TelemetryConfigProvider();
};
