import type { DataField } from '@microsoft/oteljs';
import * as OTel from '@microsoft/oteljs';
import { HostAppSettings } from '../utils/HostAppSettings';
import { MappedError, toError } from '../utils/ErrorUtils';
import type { EventName } from './Events';
import { eventFlags } from './Events';
import type {
  ITelemetryLogger,
  TelemetryEventData,
} from './ITelemetryLogger';
import { TelemetryEventType } from './ITelemetryLogger';
import { OfficeTelemetrySinkWrapper, PriorityTelemetrySink } from './OfficeTelemetrySinkWrapper';

const isDev = __IS_DEV__ !== undefined && __IS_DEV__ === true;
export class TelemetryLogger implements ITelemetryLogger {
  // this token is for the Office OneNote tenant
  // already used in /sdx/start/packages/onenotebackend/src/Telemetry/utils.ts & /sdx/meetingdetails/packages/onenotebackend/src/logging/constants.ts
  private static readonly AriaTenantToken = '3de38b41008a4da5a5381ef307f91597-636c040a-3c10-4912-9e28-de026a94600f-6848';
  private static readonly NexusTenantToken = 1718;
  private static readonly Namespace = 'Office.OneNote.SDX.Integrations.HostedWorkspaces';

  private readonly oTelLogger: OTel.TelemetryLogger;
  private readonly priorityOTelLogger: OTel.TelemetryLogger;
  private readonly namespace: string;
  private static telemetryLogger: TelemetryLogger;

  // Last successfully-resolved host correlation context, reused as a fallback when reading Office
  // settings throws (e.g., during teardown) so the HostCorrelationId join key survives on late events.
  private baseContextCache: TelemetryEventData = {};

  // Guards against emitting the TelemetryQueueOverflow summary more than once per page — shutdown()
  // can run twice (error-recovery, then the reload-triggered beforeunload) on the same instance.
  private overflowEmitted = false;

  constructor() {
    const ariaTenantToken = TelemetryLogger.AriaTenantToken;
    const nexusTenantToken = TelemetryLogger.NexusTenantToken;
    const namespace = TelemetryLogger.Namespace;

    this.oTelLogger = new OTel.TelemetryLogger();
    this.namespace = namespace;

    this.oTelLogger.setTenantToken(
      `${namespace}`,
      ariaTenantToken,
      nexusTenantToken
    );

    this.oTelLogger.addSink(OfficeTelemetrySinkWrapper.Instance);

    // Separate OTel logger that fans out to the PriorityTelemetrySink.
    // Used by logPriorityEvent to bypass the batched queue on the standard
    // wrapper sink — critical for events that must escape before the page
    // is torn down (e.g., page unload diagnostics).
    this.priorityOTelLogger = new OTel.TelemetryLogger();
    this.priorityOTelLogger.setTenantToken(
      `${namespace}`,
      ariaTenantToken,
      nexusTenantToken
    );
    this.priorityOTelLogger.addSink(PriorityTelemetrySink.Instance);
  }

  public static get Instance(): TelemetryLogger {
    if (!TelemetryLogger.telemetryLogger) {
      TelemetryLogger.telemetryLogger = new TelemetryLogger();
    }

    return TelemetryLogger.telemetryLogger;
  }

  public logEvent(
    eventName: EventName,
    data?: TelemetryEventData
  ): void {
    this.sendEvent(this.oTelLogger, eventName, data);
  }

  /**
   * Logs an event via the priority path: bypasses the {@link OfficeTelemetrySinkWrapper}
   * batched queue and goes directly to `Office.telemetrySink`. Intended for events
   * that must escape before the page is torn down (e.g., page unload diagnostics).
   *
   * Internal-use API. Do not use for general telemetry — it bypasses our batching,
   * back-pressure handling, and dropped-event accounting.
   */
  public logPriorityEvent(
    eventName: EventName,
    data?: TelemetryEventData
  ): void {
    this.sendEvent(this.priorityOTelLogger, eventName, data);
  }

  private sendEvent(
    logger: OTel.TelemetryLogger,
    eventName: EventName,
    data?: TelemetryEventData,
  ): void {
    // do not log on dev environment
    if (isDev) {
      return;
    }
    logger.sendTelemetryEvent({
      eventName: `${this.namespace}.${eventName}`,
      eventFlags: eventFlags[eventName],
      dataFields: TelemetryLogger.getDataFields({ ...data, ...this.getBaseContext() }),
    });
  }

  public logError(
    eventName: EventName,
    error: Error | unknown,
    data?: TelemetryEventData
  ): void {
    // do not log on dev environment
    if (isDev) {
      return;
    }

    // Sanitize error to ensure no PII leaks into telemetry.
    // Skip re-classification if already a MappedError (e.g., pre-sanitized by caller).
    const normalizedError = error instanceof MappedError ? error : toError(error);

    const flags = eventFlags[eventName];
    const dataFields = [
      ...TelemetryLogger.getErrorDataFields(normalizedError),
      ...TelemetryLogger.getDataFields({ ...data, ...this.getBaseContext() }),
    ];

    const telemetryErrorEvent: OTel.ErrorEvent = {
      eventName: `${this.namespace}.${eventName}`,
      error: {
        errorGroup: TelemetryEventType.Error,
        tag: 0,
      },
      eventFlags: flags,
      dataFields: dataFields,
    };

    this.oTelLogger.sendError(telemetryErrorEvent);
  }

  /**
   * Host correlation context stamped on every SDX event so Kusto can join SDX telemetry to the
   * Fluid/OWH load markers (same host correlation id). Reads live from {@link HostAppSettings}; on
   * failure (e.g., Office torn down during unload) falls back to the last resolved values.
   */
  private getBaseContext(): TelemetryEventData {
    try {
      const context: TelemetryEventData = {
        HostCorrelationId: HostAppSettings.getCorrelationId(),
        HostSessionId: HostAppSettings.getSessionId(),
      };
      this.baseContextCache = context;
      return context;
    } catch {
      return this.baseContextCache;
    }
  }

  private static getDataFields(data: TelemetryEventData | undefined): DataField[] {
    if (!data) {
      return [];
    }
    return Object.keys(data ?? {}).map<DataField>(key => {
      const value = data[key];
      switch (typeof value) {
        case 'number':
          return OTel.makeDoubleDataField(key, value);
        case 'string':
          return OTel.makeStringDataField(key, value);
        case 'boolean':
          return OTel.makeBooleanDataField(key, value);
        default:
          return OTel.makeStringDataField(key, value);
      }
    });
  }

  private static getErrorDataFields(error: Error | unknown): DataField[] {
    if (typeof error !== 'object' || !error) {
      return [];
    }

    const dataFields: DataField[] = [];
    if (
      'code' in error &&
      (typeof error.code === 'string' || typeof error.code === 'number')
    ) {
      dataFields.push(OTel.makeStringDataField('ErrorCode', `${error.code}`));
    }

    if ('message' in error && typeof error.message === 'string') {
      dataFields.push(OTel.makeStringDataField('ErrorMessage', error.message));
    }

    return dataFields;
  }

  /**
   * Shuts down the logger: stops accepting new events and flushes
   * all queued telemetry to the sink. Call before page reload or
   * in beforeunload handlers to ensure telemetry is not lost.
   *
   * If any events were lost during the session (queue overflow or send failures), a single
   * summary event is emitted. Drains first so the count includes failures that occur during the
   * drain, and is emitted at most once per page (shutdown may run twice on the same instance).
   */
  public shutdown(): void {
    const sink = OfficeTelemetrySinkWrapper.Instance;
    // Capture the pre-drain queue depth (informative) before draining empties it.
    const queueLengthAtShutdown = sink.queueLength;
    sink.shutdown();
    // Priority path is independent of the (now shut-down) batched sink, so emitting after the
    // drain is safe and lets the dropped count reflect any drain-time send failures.
    if (sink.droppedEventCount > 0 && !this.overflowEmitted) {
      this.overflowEmitted = true;
      this.logPriorityEvent('TelemetryQueueOverflow', {
        DroppedEventCount: sink.droppedEventCount,
        QueueLength: queueLengthAtShutdown,
        MaxQueueSize: sink.maxQueueSize,
      });
    }
  }
}
