import type {
  Disposable,
  IdentityType,
  ProvideDisposable,
  TokenProvider,
  TokenRequestOptions,
  TokenResponse,
  UserContext,
} from '@fluidx/loop-types';
import { DataAction } from '../interop';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { getCloudType } from '../utils/Cloud';
import { changeGates, featureGates } from '../utils/FeatureGates';
import { retryWithBackoff } from '../utils/retry';
import { BizChatAuthServiceV1 } from './BizChatAuthService';
import type {
  Identity,
} from './HostAuthServiceUtils';
import {
  getConsumerScope,
  getOfficeAuthContext,
  getResourceForTokenType,
  getTokenDefinitionFromResourceStrings,
  getUserAccountType,
} from './HostAuthServiceUtils';
import { LwcAuthService } from './LwcAuthService';
import {
  BIZCHAT_CORE_APPID,
  ONENOTE_DESKTOP_APPID,
} from './constants';
import type { TokenType } from './endpoints';
import {
  MappedError,
  exponentialBackoffDelay,
  getAuthAttemptLimit,
  getResourceForScopes,
  isMSA,
  isOrgId,
  isRetryableSSOAuthError,
  toError,
} from './utils';

type AuthResult = Partial<OfficeFirstPartyAuth.AuthResult> & Pick<OfficeFirstPartyAuth.AuthResult, 'accessToken'>;

export class HostAuthService implements TokenProvider, ProvideDisposable, Disposable {
  // This is to prevent calling getAccessToken multiple times for the same token type.
  private tokenPromiseCache = new Map<string, Promise<AuthResult>>();
  private identity: Identity | undefined = undefined;
  private isDisposed = false;
  public bizChatAuthService: BizChatAuthServiceV1 | undefined = undefined;
  public lwcAuthService: LwcAuthService | undefined = undefined;

  public async initialize(): Promise<void> {
    try {
      await this.populateIdentity();
    } catch (error) {
      const lastError = toError(error);
      TelemetryLogger.Instance.logError('AuthError', lastError, { ErrorMethod: 'initialize.populateIdentity' });
      throw new Error('Identity initialization failed');
    }

    if (!this.identity) {
      const lastError = new MappedError('NoIdentity', 'NoIdentity', false);
      TelemetryLogger.Instance.logError('AuthError', lastError, { ErrorMethod: 'initialize.populateIdentity' });
      throw lastError;
    }

    try {
      console.log('Loading SSO auth module');
      await OfficeFirstPartyAuth.load();
    } catch (error) {
      const lastError = toError(error);
      TelemetryLogger.Instance.logError('AuthError', lastError, { ErrorMethod: 'initialize.loadSSO' });
      throw new Error('SSO auth module loading failed');
    }

    this.bizChatAuthService = new BizChatAuthServiceV1(this.identity);
    if (featureGates.getBooleanFeatureGate('deprecateSSO', false)) {
      const lwcClientId = featureGates.getBooleanFeatureGate('useBizChatForLWC', false) ? BIZCHAT_CORE_APPID : ONENOTE_DESKTOP_APPID;
      this.lwcAuthService = new LwcAuthService(this.identity, lwcClientId);
    }

    // Warm up auth tokens (non-blocking)
    this.warmupAuthTokens(this.bizChatAuthService, this.lwcAuthService);
  }

  private warmupAuthTokens(bizChatAuthService: BizChatAuthServiceV1, lwcAuthService?: LwcAuthService): void {
    console.log('Warming up auth tokens');
    const startTime = Date.now();

    const fetchTokens = async (): Promise<void> => {
      const tokenPromises: Array<{ promise: Promise<unknown>; tokenType: string }> = [
        { promise: bizChatAuthService.sydney(), tokenType: 'SYDNEY' },
      ];

      if (lwcAuthService) {
        tokenPromises.push(
          { promise: lwcAuthService.getTokenForTokenType('SUBSTRATE'), tokenType: 'SUBSTRATE' }
        );
      } else {
        tokenPromises.push(
          { promise: this.getOfficeFirstPartyAuthResultByTokenType('SUBSTRATE'), tokenType: 'SUBSTRATE' }
        );
      }

      if (!isMSA(this.identity?.identityType)) {
        if (lwcAuthService) {
          tokenPromises.push(
            { promise: lwcAuthService.getTokenForTokenType('OCPS'), tokenType: 'OCPS' }
          );
        } else {
          tokenPromises.push(
            { promise: this.getOfficeFirstPartyAuthResultByTokenType('OCPS'), tokenType: 'OCPS' }
          );
        }
      }

      const results = await Promise.allSettled(tokenPromises.map(tp => tp.promise));
      const rejectedCount = results.filter(r => r.status === 'rejected').length;

      const durationMS = Date.now() - startTime;
      results.forEach((result, index) => {
        if (result.status === 'rejected') {
          const tokenType = tokenPromises[index].tokenType;
          const lastError = toError(result);

          TelemetryLogger.Instance.logError('AuthError', lastError, {
            ErrorMethod: 'warmupAuthTokens.fetch',
            TokenType: tokenType,
            Duration: durationMS
          });
        }
      });

      TelemetryLogger.Instance.logEvent('AuthTokenWarmup', {
        Duration: durationMS,
        TokenCount: results.length,
        Success: rejectedCount === 0,
        FailedCount: rejectedCount
      });
    };

    void fetchTokens()
      .catch((error) => {
        const lastError = toError(error);
        TelemetryLogger.Instance.logError('AuthError', lastError, {
          ErrorMethod: 'warmupAuthTokens.fetchTokens'
        });
      });
  }

  public get Disposable() {
    return this;
  }

  public dispose() {
    this.isDisposed = true;
  }

  public get TokenProvider(): TokenProvider {
    return this.lwcAuthService ?? this;
  }

  public getIdentity(): Identity | undefined {
    if (this.isDisposed) {
      return undefined;
    }

    return this.identity;
  }

  public get identityType(): IdentityType | undefined {
    if (this.isDisposed || !this.identity) {
      return 'UnauthenticatedGuest';
    }

    if (isMSA(this.identity.identityType)) {
      return 'Consumer';
    }

    if (isOrgId(this.identity.identityType)) {
      return 'Enterprise';
    }

    return undefined;
  }

  public async getOfficeFirstPartyAuthResultByTokenType(
    type: TokenType
  ): Promise<AuthResult> {
    if (this.isDisposed) {
      throw new Error('Provider has been disposed');
    }

    const resourceUrl = getResourceForTokenType(type, getUserAccountType(this.identity), getCloudType()) ?? '';
    return this.getOfficeFirstPartyAuthResultByResource(resourceUrl, type);
  }

  public async getOfficeFirstPartyAuthResultByResource(
    resource: string,
    tokenType: TokenType,
    options?: TokenRequestOptions
  ): Promise<AuthResult> {
    if (this.isDisposed) {
      throw new Error('Provider has been disposed');
    }

    if (!resource || resource.trim() === '') {
      const error = new Error('Unsupported token request: empty resource URL');
      TelemetryLogger.Instance.logError('AuthError', error, {
        ErrorMethod: 'getOfficeFirstPartyAuthResultByResource',
        TokenType: tokenType
      });
      throw error;
    }

    const cachedPromise = this.tokenPromiseCache.get(resource);
    if (cachedPromise) {
      return cachedPromise;
    }

    const authResultPromise = this.acquireTokenWithRetry(resource, tokenType, options);
    this.tokenPromiseCache.set(resource, authResultPromise);

    return authResultPromise.finally(() => {
      this.tokenPromiseCache.delete(resource);
    });
  }

  private async acquireTokenWithRetry(
    resource: string,
    tokenType: TokenType,
    options?: TokenRequestOptions
  ): Promise<AuthResult> {
    const startTime = Date.now();
    const isMSAAccount = isMSA(this.identity?.identityType);
    // Resolve the gate-driven attempt limit once at retry-loop entry so the
    // budget is consistent across all attempts in a single chain even if the
    // gate flips mid-chain.
    const attemptLimit = getAuthAttemptLimit();

    try {
      await OfficeFirstPartyAuth.load();
    } catch (error) {
      const lastError = toError(error);
      TelemetryLogger.Instance.logError('AuthError', lastError, {
        ErrorMethod: 'acquireTokenWithRetry.load',
        TokenType: tokenType,
      });
      throw new Error('Failed to load OfficeFirstPartyAuth');
    }

    return retryWithBackoff<AuthResult, MappedError>(
      async (attemptCount) => {
        const forceRefresh = (options?.forceRefresh ?? false) || attemptCount > 1;
        const useForceRefreshClaims = changeGates.getBooleanChangeGate('useForceRefreshClaims');
        const authChallenge = options?.claims
          ?? (useForceRefreshClaims && forceRefresh ? '{"access_token":{"nbf":{"essential":true}}}' : undefined);

        const isInteractive = false;
        const authResult = await OfficeFirstPartyAuth.getAccessToken(
          {
            resource,
            policy: isMSAAccount ? 'DELEGATED' : undefined,
            scope: isMSAAccount ? getConsumerScope(resource, tokenType) : undefined,
            identityId: this.identity?.id,
            authChallenge,
            silentLogin: !isInteractive,
          },
          {
            popup: isInteractive,
            forceRefresh,
          }
        );

        const duration = Date.now() - startTime;
        TelemetryLogger.Instance.logEvent('SSOTokenAcquired', {
          TokenType: tokenType,
          Duration: duration,
          TokenHasClaims: options?.claims !== undefined,
          TokenForceRefresh: forceRefresh,
          FetchAttemptCount: attemptCount,
          FetchAttemptLimit: attemptLimit,
        });

        return authResult;
      },
      {
        maxAttempts: attemptLimit,
        isRetryable: isRetryableSSOAuthError,
        isRetryEnabled: () => changeGates.getBooleanChangeGate('useAuthRetry'),
        backoffDelay: exponentialBackoffDelay,
        mapError: toError,
        exhaustedError: 'Token acquisition retry limit exceeded',
        nonRetryableError: 'Failed to acquire SSO token',
        onAttemptError: (lastError, attemptCount) => {
          const forceRefresh = (options?.forceRefresh ?? false) || attemptCount > 1;
          TelemetryLogger.Instance.logError('AuthError', lastError, {
            ErrorMethod: 'SSO.getAccessToken',
            ErrorCode: lastError.code,
            ErrorMessage: lastError.message,
            TokenType: tokenType,
            TokenHasClaims: options?.claims !== undefined,
            TokenForceRefresh: forceRefresh,
            FetchAttemptCount: attemptCount,
            FetchAttemptLimit: attemptLimit,
          });
        },
      },
    );
  }

  public async getToken(scopes: string[], options: TokenRequestOptions): Promise<TokenResponse> {
    if (this.isDisposed) {
      throw new Error('Provider has been disposed');
    }

    let requestedResource = '';
    try {
      requestedResource = getResourceForScopes(scopes);
    } catch (error) {
      const authError = new Error('Failed to get resource from scopes');
      TelemetryLogger.Instance.logError('AuthError', authError, { ErrorMethod: 'getToken.getResourceForScopes' });
      throw authError;
    }

    let resourceLowerCase = requestedResource.toLowerCase();

    if (resourceLowerCase === '') {
      try {
        const urlValue = options.request?.url ?? '';
        const url = new URL(urlValue);
        requestedResource = url.origin;
        resourceLowerCase = url.origin.toLowerCase();
      } catch (error) {
        const authError = new Error('Unsupported token request: invalid request URL');
        TelemetryLogger.Instance.logError('AuthError', authError, { ErrorMethod: 'getToken.parseRequestURL' });
        throw authError;
      }
    }

    // Check resource URL origin as fallback
    let resourceURL: URL | undefined;
    try {
      resourceURL = new URL(resourceLowerCase);
    } catch (error) {
      console.warn('Could not parse resource as URL');
    }

    const tokenDefinition = getTokenDefinitionFromResourceStrings(
      [resourceLowerCase, resourceURL?.origin.toLowerCase() ?? ''],
      getUserAccountType(this.identity),
      getCloudType()
    );
    const resourceUrl = tokenDefinition?.resource ?? resourceLowerCase;
    let tokenType = tokenDefinition?.tokenType ?? 'UNKNOWN';

    if (tokenType === 'UNKNOWN') {
      if (resourceLowerCase.includes('.sharepoint')) {
        tokenType = 'SHAREPOINT';
      } else if (resourceLowerCase.includes('.onmicrosoft.com')) {
        tokenType = 'ONMICROSOFT';
      } else {
        TelemetryLogger.Instance.logError('AuthError', new Error('Unknown token resource'), { ErrorMethod: 'getToken.resolveTokenType', TokenType: 'UNKNOWN' });
      }
    }

    try {
      const authResult = await this.getOfficeFirstPartyAuthResultByResource(resourceUrl, tokenType, options);
      return { token: authResult.accessToken };
    } catch (error) {
      const lastError = toError(error);
      TelemetryLogger.Instance.logError('AuthError', lastError, {
        ErrorMethod: 'getToken',
        TokenType: tokenType,
      });
      throw new Error(`Token acquisition failed for: ${tokenType}`);
    }
  }

  public getUserContext(): UserContext & Disposable & { signInState: string[] } {
    let identity = this.getIdentity();
    if (!identity) {
      identity = {
        id: '',
        name: '',
        tenantId: '',
        identityType: 0,
      };
    }
    return {
      get UserContext() {
        return this;
      },
      user: {
        id: identity.id,
        tenantId: identity.tenantId,
        userIdSpace: 'UserObjectId',
        oid: identity.oid,
        upn: identity.upn,
      },
      signInState: ['kmsi'],
      get Disposable() {
        return this;
      },
      dispose() {
        return;
      },
    };
  }

  private async populateIdentity(): Promise<void> {
    console.log('Populating identity for HostAuthService');

    let clientIdentity;
    try {
      clientIdentity = await DataAction.getActiveUserIdentity();
    } catch (error) {
      const lastError = toError(error);
      TelemetryLogger.Instance.logError('AuthError', lastError, { ErrorMethod: 'populateIdentity.getActiveUserIdentity' });
      throw new Error('Failed to get primary identity info from client');
    }

    // If the user is signed in with an MSA account, we need to get the tenantId and userObjectId from the auth context
    if (isMSA(clientIdentity.accountType)) {
      const authContext = await getOfficeAuthContext();
      if (authContext) {
        clientIdentity.tenantId = authContext.value.tenantId;
        const userObjectId = authContext.value.userObjectId ?? clientIdentity.userId;
        clientIdentity.userId = userObjectId;
      }
    }

    const identity: Identity = {
      id: clientIdentity.userId,
      name: clientIdentity.userName,
      tenantId: clientIdentity.tenantId,
      identityType: clientIdentity.accountType,
      upn: clientIdentity.email,
    };

    const identityChanged = identity.tenantId !== this.identity?.tenantId || identity.id !== this.identity?.id;

    if (identityChanged) {
      this.tokenPromiseCache.clear();
      this.identity = identity;
      // Must set BizChatAuthService identity after HostAuthService identity is set for MSA to work
      if (this.bizChatAuthService) {
        this.bizChatAuthService.clearCache();
        this.bizChatAuthService.setIdentity(identity);
      }
      if (this.lwcAuthService) {
        this.lwcAuthService.clearCache();
        this.lwcAuthService.setIdentity(identity);
      }
      console.log('Identity configured for session');
    }
  }
}
