import EventEmitter from 'events';
import type {
  ProvideDisposable, ThemeName, Theming,
} from '@fluidx/loop-types';
import { OneNoteBrandTheme } from '../utils/ThemingConstants';
export class ThemeProvider extends EventEmitter implements Theming, ProvideDisposable {
  themeName?: ThemeName;
  themeProperties?: ReadonlyMap<string, string>;
  constructor() {
    super();
    this.setThemeName();
    this.setThemeProperties(true /* shouldSkipThemePropertiesEventEmit */);
    void this.registerThemeChangeHandler();
  }

  public get Theming(): Theming {
    return this;
  }

  public get Disposable() {
    return this;
  }

  private setThemeName(data?: Office.OfficeThemeChangedEventArgs) {
    const isHighContrast = window.matchMedia('(forced-colors: active)').matches;
    // If high contrast mode is enabled, use the high-contrast theme
    if (isHighContrast) {
      this.themeName = 'high-contrast';
      return;
    }
    const officeTheme = data ? data.officeTheme : Office.context.officeTheme;
    // Otherwise, use the default or dark theme based on the Office context
    const isDarkMode = officeTheme.isDarkTheme;
    this.themeName = isDarkMode ? 'dark' : 'default';
  }

  private themeChangeHandler = (data: Office.OfficeThemeChangedEventArgs) => {
    this.setThemeName(data);
    this.emit('themeNameChanged');
  };

  private registerThemeChangeHandler = async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const officeContext = Office.context as any;
    if (officeContext?.themeManager) {
      await officeContext.themeManager.addHandlerAsync(Office.EventType.OfficeThemeChanged, this.themeChangeHandler);
    }
  };

  private unRegisterThemeChangeHandler = async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const officeContext = Office.context as any;
    if (officeContext?.themeManager) {
      await officeContext.themeManager.removeHandlerAsync(Office.EventType.OfficeThemeChanged, this.themeChangeHandler);
    }
  };

  private setThemeProperties(shouldSkipThemePropertiesEventEmit: boolean) {
    this.themeProperties = new Map<string, string>(
      Object.entries(OneNoteBrandTheme).map(([key, value]) => [key, String(value)])
    );
    if (!shouldSkipThemePropertiesEventEmit) {
      this.emit('themePropertiesChanged');
    }
  }

  dispose(): void {
    void this.unRegisterThemeChangeHandler();
  }
}
