import type {
  Environment
} from '@fluidx/loop-types';
import type { EcsResponse } from '@fluidx/settings-provider';
import { EcsSettingsProvider } from '@fluidx/settings-provider';
import type { HostAuthService } from '../auth/HostAuthService';
import { getResourceForTokenType, getUserAccountType } from '../auth/HostAuthServiceUtils';
import { isMSA, toError } from '../auth/utils';
import { TelemetryActivityTracker } from '../telemetry/TelemetryActivityTracker';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { getCloudType } from '../utils/Cloud';
import { changeGates } from '../utils/FeatureGates';
import {
  getM365ChatDeploymentRingFromAudience, getM365ChatEnvironmentFromAudience, transformEcsTeamSettings
} from './m365ChatEcsUtils';

/**
 * Represents all cached ECS responses keyed by cache key
 */
export interface CachedEcsResponses {
  [cacheKey: string]: EcsResponse;
}

/**
 * Represents the settings provider constants for M365 Chat
 */
export const M365CHAT_APP_VERSION_SETTING_NAME = 'appVersion';
const M365_CHAT_ECS_CLIENT_NAME = 'M365ChatClient';
export const M365CHAT_ECS_FILTER_HOST_NAME_ONENOTE = 'OneNote';
export type M365ChatHostName = typeof M365CHAT_ECS_FILTER_HOST_NAME_ONENOTE;

export type OneNoteSettings = Record<string, string | boolean> & { readonly __brand: 'OneNote' };
const M365CHAT_ECS_RESPONSES_CACHE_KEY = 'M365ChatEcsResponseCache';
const M365CHAT_ECS_CLIENT_VERSION = '1.0.0.0';
export const M365CHAT_APP_ECS_PROJECT_TEAM_NAME = 'M365ChatClient';
const M365CHAT_VERSIONING_ECS_PROJECT_TEAM_NAME = 'AppVersion';
const M365CHAT_ECS_PROJECT_TEAMS = [
  M365CHAT_APP_ECS_PROJECT_TEAM_NAME,
  M365CHAT_VERSIONING_ECS_PROJECT_TEAM_NAME
];
const FETCHSETTINGS_TIMEOUT_MS = 10000;
const ECS_CLIENT_INIT_POLL_INTERVAL_MS = 50;

export class M365ChatSettingsProvider extends EcsSettingsProvider {
  private cacheKey: string;
  protected readonly hostName: M365ChatHostName;
  constructor(
    hostName: M365ChatHostName,
    environment: Environment,
    authService: HostAuthService,
    locale: string,
  ) {
    const cacheKey = `${authService.getIdentity()?.id}${hostName}${environment.audience}`;
    super({
      // ECS is defined for all supported clouds; throws for strict sovereign clouds if missing
      host: getResourceForTokenType('ECS', getUserAccountType(authService.getIdentity()), getCloudType())!,
      clientName: M365_CHAT_ECS_CLIENT_NAME,
      clientVersion: M365CHAT_ECS_CLIENT_VERSION,
      teamNames: M365CHAT_ECS_PROJECT_TEAMS,
      cacheKey,
      responsesCacheKey: M365CHAT_ECS_RESPONSES_CACHE_KEY,
      alwaysFetchNewSettings: true,
      enableLogSettingsWithSource: true,
      filters: {
        audience: environment.audience,
        HostName: hostName,
        AccountType: isMSA(authService.getIdentity()?.identityType)
          ? 'MSA'
          : 'AAD',
        TenantId: authService.getIdentity()?.tenantId,
        UserID: authService.getIdentity()?.id,
        Locale: locale,
        Environment: getM365ChatEnvironmentFromAudience(environment.audience),
        DeploymentRing: getM365ChatDeploymentRingFromAudience(environment.audience),
      },
    });
    this.hostName = hostName;
    this.cacheKey = cacheKey;
  }

  /**
   * Polls the base class's public {@link settingsFetchedFromEcs} flag until the initial
   * ECS fetch has completed, or rejects on timeout. The base class persists the fetched
   * response to localStorage before flipping this flag, so once it is true the cached
   * responses are guaranteed readable.
   */
  private waitForEcsSettings(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const deadline = Date.now() + FETCHSETTINGS_TIMEOUT_MS;
      const poll = () => {
        if (this.settingsFetchedFromEcs) {
          resolve();
          return;
        }
        if (Date.now() >= deadline) {
          reject(new Error('ECS settings fetch timeout'));
          return;
        }
        setTimeout(poll, ECS_CLIENT_INIT_POLL_INTERVAL_MS);
      };
      poll();
    });
  }

  /**
   * Reads the cached ECS responses directly from localStorage, where the base class's
   * EcsClient persists them under {@link M365CHAT_ECS_RESPONSES_CACHE_KEY}.
   *
   * This reads the cache rather than calling the EcsClient because the client and its bulk
   * accessor are ECMAScript hard-private (`#ecsClient` / `#getAllCachedEcsResponses`) and
   * unreachable from this subclass — a structural cast to them resolves to `undefined` at
   * runtime. The durable fix is a public accessor on EcsSettingsProvider (tracked
   * separately); until then this couples to the client's localStorage cache format, which
   * is stable and uses only the package's public types.
   * @returns All cached ECS responses keyed by cacheKey, or undefined if none / parse error.
   */
  private readCachedEcsResponses(): CachedEcsResponses | undefined {
    try {
      const raw = globalThis.localStorage?.getItem(M365CHAT_ECS_RESPONSES_CACHE_KEY);
      return raw ? (JSON.parse(raw) as CachedEcsResponses) : undefined;
    } catch (error) {
      TelemetryLogger.Instance.logError(
        'M365ChatSettingsProviderError',
        toError(error),
        { ErrorMethod: 'readCachedEcsResponses', HostName: this.hostName },
      );
      return undefined;
    }
  }

  /**
   * Returns all cached ECS responses, waiting for the initial ECS fetch to complete (up to
   * {@link FETCHSETTINGS_TIMEOUT_MS}) when it has not yet finished so the freshest settings
   * are read.
   * @returns All cached ECS responses or undefined if none exist / the fetch timed out.
   */
  private async getAllCachedEcsResponses(): Promise<CachedEcsResponses | undefined> {
    if (!changeGates.getBooleanChangeGate('useM365ChatLocalStorageCache')) {
      // Kill switch: fall back to the original behavior of not delivering ECS settings
      // (consumers use their own defaults).
      return undefined;
    }
    try {
      return await TelemetryActivityTracker.runActivity('GetAllCachedEcsResponses', async () => {
        if (!this.settingsFetchedFromEcs) {
          await this.waitForEcsSettings();
        }
        return this.readCachedEcsResponses();
      });
    } catch (error) {
      const lastError = toError(error);
      const errorMessage = lastError.message ?? '';
      const timeoutPhase = errorMessage.includes('initialization') ? 'EcsClientInit' :
        errorMessage.includes('fetch') ? 'EcsSettingsFetch' : 'Unknown';
      TelemetryLogger.Instance.logError(
        'M365ChatSettingsProviderError',
        lastError,
        { ErrorMethod: 'getAllCachedEcsResponses', HostName: this.hostName, TimeoutPhase: timeoutPhase },
      );
      return undefined;
    }
  }

  public async getAllM365ChatFeatureSettings(): Promise<Record<string, string | boolean> | undefined> {
    const cachedResponses = await this.getAllCachedEcsResponses();
    const cacheEntry = cachedResponses?.[this.cacheKey];
    const m365ChatClientFeatureSettings =
      cacheEntry?.ecsTeamsSettings?.[M365CHAT_APP_ECS_PROJECT_TEAM_NAME];
    if (!m365ChatClientFeatureSettings) {
      TelemetryLogger.Instance.logError(
        'M365ChatSettingsProviderError',
        new Error('ECS settings cache miss'),
        {
          ErrorMethod: 'getAllM365ChatFeatureSettings',
          HostName: this.hostName,
          HasCachedResponses: cachedResponses != null,
          HasCacheEntry: cacheEntry != null,
          HasEcsTeamsSettings: cacheEntry?.ecsTeamsSettings != null,
        },
      );
      return undefined;
    }
    return transformEcsTeamSettings(m365ChatClientFeatureSettings);
  }
}

// Specialized provider for OneNote that returns branded OneNote settings
export class OneNoteSettingsProvider extends M365ChatSettingsProvider {
  constructor(
    environment: Environment,
    authService: HostAuthService,
    locale: string,
  ) {
    super(M365CHAT_ECS_FILTER_HOST_NAME_ONENOTE, environment, authService, locale);
  }

  public async getAllM365ChatFeatureSettings(): Promise<OneNoteSettings | undefined> {
    return super.getAllM365ChatFeatureSettings() as Promise<OneNoteSettings | undefined>;
  }
}
