import type { NavigationParams } from '@fluidx/loop-workspace-types';
import {
  emptyDocUrl,
  emptyId,
  zeroId,
  zeroUrl,
} from '../service/workspaceManager/constants';

/**
 * Builds the initial NavigationParams from host launch settings.
 * Returns 'notebooks' (home) when no valid workspace ID is provided.
 */
export function buildInitialNavParams(
  podId: string,
  spoId: string,
  docUrl: string,
  docUrlRequiresRedeem: boolean,
): NavigationParams {
  const hasPodId = podId !== emptyId && podId !== zeroId;
  if (!hasPodId) {
    return { route: 'notebooks' };
  }

  const hasDocUrl = docUrl !== emptyDocUrl && docUrl !== zeroUrl;
  if (hasDocUrl) {
    return {
      route: 'page',
      mfsPodId: podId,
      docUrl,
      requiresRedeem: docUrlRequiresRedeem,
    };
  }

  return {
    route: 'notebook',
    mfsPodId: podId,
    spoId: (spoId !== emptyId && spoId !== zeroId) ? spoId : undefined,
  };
}
