import type {
  NavigationParams,
  WorkspaceAndPageManager,
  WorkspaceNavigationHandler,
} from '@fluidx/loop-workspace-types';
import type { NativeInteropError } from '../../interop';
import {
  NotifyClient,
} from '../../interop';
import type {
  NativeEvent_AddReferenceToNotebookArgs,
  NativeEvent_AppRequestDeleteNotebookArgs,
  NativeEvent_NavigateToCreateNotebookArgs,
  NativeEvent_NavigateToLinkArgs,
  NativeEvent_NavigateToNotebookArgs,
  NativeEvent_NavigateToNotebookPageArgs,
  NativeEvent_NavigateToSearchResultArgs,
  NativeEvent_RenameNotebookArgs,
  NativeEvent_ToggleFavoriteNotebookArgs,
} from '../../interop/nativeEvents';
import { TelemetryLogger } from '../../telemetry/TelemetryLogger';
import { OdspNavigationHandler } from './OdspNavigationHandler';
import { WorkspaceManager, WorkspaceManagerEvents } from './WorkspaceManager';
import {
  emptyDocUrl,
  emptyId,
  zeroId,
  zeroUrl,
} from './constants';

export class AppWorkspaceManager {
  private workspaceManager: WorkspaceManager;
  private odspNavigationHandler: OdspNavigationHandler;
  private onNavigationEvent: (() => void) | undefined;

  public constructor() {
    this.workspaceManager = new WorkspaceManager();
    this.odspNavigationHandler = new OdspNavigationHandler(this.workspaceManager, this);
    this.workspaceManager.on(WorkspaceManagerEvents.navigate, () => {
      this.onNavigationEvent?.();
    });
  }

  public getWorkspaceManager() {
    return this.workspaceManager;
  }

  public setWorkspaceAndPageManager(manager: WorkspaceAndPageManager) {
    this.workspaceManager.SetWorkspaceAndPageManager(manager);
  }

  public setWorkspaceNavigationHandler(handler: WorkspaceNavigationHandler) {
    this.workspaceManager.SetWorkspaceNavigationHandler(handler);
  }

  public flushPendingNavigation() {
    this.workspaceManager.FlushPendingNavigation();
  }

  public setOnNavigationEvent(onNavigationEvent: () => void) {
    this.onNavigationEvent = onNavigationEvent;
  }

  public async appLoadDataModels() {
    await this.workspaceManager.ProcessWorkspaces();
  }

  public async appAddReferenceToNotebook(params: NativeEvent_AddReferenceToNotebookArgs) {
    await this.workspaceManager.AddReferenceTo(params.podId, params.refUrls, params.refTitles);
  }

  public async appNavigateToCreateNotebook(params: NativeEvent_NavigateToCreateNotebookArgs) {
    const navParams: NavigationParams = {
      route: 'createNotebook',
      linkedChats: params.chatConversationIds?.map((conversationId) => ({ conversationId })) ?? [],
      linkedPages: params.pageDocUrls?.map((docUrl) => ({ docUrl })) ?? [],
      workspaceCreateType: params.workspaceCreateType,
      notebookName: params.notebookName
    };

    await this.workspaceManager.NavigateTo(navParams);
  }

  public async appRequestDeleteNotebook(params: NativeEvent_AppRequestDeleteNotebookArgs) {
    await this.workspaceManager.DeleteNotebook(params.podId);
  }

  public appNavigateToHome() {
    return this.workspaceManager.NavigateTo({ route: 'notebooks' });
  }

  public appNavigateToNotebook(params: NativeEvent_NavigateToNotebookArgs) {
    if (params.podId === emptyId || params.podId === zeroId) {
      return this.appNavigateToHome();
    }

    return this.workspaceManager.NavigateTo({
      route: 'notebook',
      mfsPodId: params.podId,
      spoId: (params.spoId !== emptyId && params.spoId !== zeroId) ? params.spoId : undefined,
    });
  }

  public appNavigateToPage(params: NativeEvent_NavigateToNotebookPageArgs) {
    const podId = params.podId ?? emptyId;

    if (podId === emptyId || podId === zeroId) {
      return this.appNavigateToHome();
    }

    if (params.docUrl === emptyDocUrl || params.docUrl === zeroUrl) {
      return this.appNavigateToNotebook({ podId });
    }

    return this.workspaceManager.NavigateTo({
      route: 'page',
      mfsPodId: podId,
      requiresRedeem: params.requiresRedeem,
      docUrl: params.docUrl,
    });
  }

  public async appNavigateToSearchResult(params: NativeEvent_NavigateToSearchResultArgs) {
    return this.odspNavigationHandler.navigateToSearchResult(params);
  }

  public async appNavigateToLink(params: NativeEvent_NavigateToLinkArgs) {
    return this.odspNavigationHandler.navigateToLink(params);
  }

  public async appNavigateToResourceLinkInClient(params: NativeEvent_NavigateToLinkArgs) {
    if (!params.linkUrl) {
      const error = new Error('linkUrl not provided');
      TelemetryLogger.Instance.logError('NotifyClientError', error, {
        ErrorMethod: 'navigateToResourceLinkInClientEvent',
        NavigationSuccess: false,
      });
      throw error;
    }

    try {
      return await NotifyClient.navigateToResourceLinkInClientEvent({ originalUrl: params.linkUrl });
    } catch (error) {
      TelemetryLogger.Instance.logError('NotifyClientError', error as NativeInteropError, {
        ErrorMethod: 'navigateToResourceLinkInClientEvent',
        ErrorDetails: 'Failed to navigate to resource in client',
        NavigationSuccess: false,
      });
      throw new Error('Failed to navigate to link in client');
    }
  }

  public renameNotebook(params: NativeEvent_RenameNotebookArgs) {
    return this.workspaceManager.RenameNotebook(params.podId, params.name);
  }

  public toggleFavoriteNotebook(params: NativeEvent_ToggleFavoriteNotebookArgs) {
    return this.workspaceManager.ToggleFavoriteNotebook(params.podId);
  }
}
