import React from 'react';
import type {
  Environment, HTMLView, Provider
} from '@fluidx/loop-types';
import type { NavigationParams, WorkspaceAndPageManagerEvents } from '@fluidx/loop-workspace-types';
import type { OfficeFluidLogger } from '@fluidx/telemetry';
import type { Locale } from '@fluidx/utilities';
import { type HostAuthService } from '../auth/HostAuthService';
import type { M365ChatSettingsProvider } from '../providers/M365ChatSettingsProvider';
import type { DependencySynthesizerService } from '../service/dependencySynthesizer/DependencySynthesizerService';
import type { UserEligibilityService } from '../service/userEligibilityService/UserEligibilityService';
import type { AppWorkspaceManager } from '../service/workspaceManager/AppWorkspaceManager';
import { HostAppSettings } from '../utils/HostAppSettings';
import type { ActionProviderTypes } from '../utils/loopComponent';
import { renderView } from '../utils/loopComponent';
import { useStyles } from './HostedWorkspaceUI.styles';
import { loadAndWireLoopComponent } from './loadAndWireLoopComponent';

export interface IHostedWorkspaceUIProps {
  appWorkspaceManager: AppWorkspaceManager;
  authService: HostAuthService;
  dependencySynthesizerService: DependencySynthesizerService;
  environment: Environment;
  locale: Locale;
  loadNavParams: NavigationParams;
  m365ChatSettingsProvider: M365ChatSettingsProvider;
  userEligibilityService: UserEligibilityService;
}

export const HostedWorkspaceUI = (props: IHostedWorkspaceUIProps) => {
  console.log('HostedWorkspaceUI invoked');
  const {
    appWorkspaceManager,
    authService,
    dependencySynthesizerService,
    environment,
    locale,
    loadNavParams,
    m365ChatSettingsProvider,
    userEligibilityService,
  } = props;
  const styles = useStyles();
  const renderTargetRef = React.useRef<HTMLDivElement>(null);
  const loopComponentRef = React.useRef<Provider<ActionProviderTypes>>();
  const fluidLoggerRef = React.useRef<OfficeFluidLogger>();
  const viewRef = React.useRef<HTMLView | undefined>();
  const isComponentRendered = React.useRef<boolean>(false);
  const hasInitiatedLoad = React.useRef<boolean>(false);

  const renderOnNavigation = React.useCallback(async () => {
    if (isComponentRendered.current) {
      return;
    }
    if (!loopComponentRef.current || !renderTargetRef.current || !fluidLoggerRef.current) {
      return;
    }
    // Set the in-flight guard BEFORE awaiting renderView (which resolves before paint), so a second
    // navigation during the render can't double-invoke renderView (duplicate RenderEndToEnd +
    // renderComplete). Roll back on failure so a transient error doesn't block a later re-render.
    isComponentRendered.current = true;
    try {
      await renderView(
        viewRef.current,
        renderTargetRef.current,
        fluidLoggerRef.current
      );
    } catch (error) {
      isComponentRendered.current = false;
      throw error;
    }
    HostAppSettings.clearOnRenderSettings();
  }, []);

  const postLoadCheck = React.useCallback((isUILessLoad: boolean) => {
    // View already rendered, no need to render again
    if (!isUILessLoad) {
      HostAppSettings.clearOnRenderSettings();
      isComponentRendered.current = true;
      return;
    }
    // Render on navigation
    appWorkspaceManager.setOnNavigationEvent(renderOnNavigation);
  }, [appWorkspaceManager, renderOnNavigation]);

  const workspaceListChangedHandler = React.useCallback(
    (data: WorkspaceAndPageManagerEvents['workspaceListChanged']) => {
      void appWorkspaceManager
        .getWorkspaceManager()
        .onWorkspaceListChangedEvent(data);
    },
    [appWorkspaceManager],
  );

  const renderLoopComponent = React.useCallback(async () => {
    if (!renderTargetRef.current) {
      return;
    }
    await loadAndWireLoopComponent({
      appWorkspaceManager,
      authService,
      dependencySynthesizerService,
      environment,
      locale,
      loadNavParams,
      m365ChatSettingsProvider,
      userEligibilityService,
      renderTarget: renderTargetRef.current,
      hasInitiatedLoadRef: hasInitiatedLoad,
      loopComponentRef,
      fluidLoggerRef,
      viewRef,
      postLoadCheck,
      workspaceListChangedHandler,
    });
  }, [
    appWorkspaceManager,
    authService,
    dependencySynthesizerService,
    environment,
    locale,
    loadNavParams,
    m365ChatSettingsProvider,
    userEligibilityService,
    postLoadCheck,
    workspaceListChangedHandler,
  ]);

  // TODO: Will be used for cleanup for error scenarios
  // const cleanupLoopComponent = React.useCallback(async () => {
  //   // Unsubscribe from manager events
  //   loopComponentRef.current?.WorkspaceAndPageManager?.off('workspaceListChanged', workspaceListChangedHandler);
  //
  //   dependencySynthesizerService.unregisterProviders();
  //   if (viewRef.current) {
  //     await viewRef.current.dispose();
  //     viewRef.current = undefined;
  //   }
  //   if (loopComponentRef.current) {
  //     loopComponentRef.current.Disposable?.dispose();
  //     loopComponentRef.current = undefined;
  //   }
  //   if (fluidLoggerRef.current) {
  //     fluidLoggerRef.current.dispose();
  //     fluidLoggerRef.current = undefined;
  //   }
  // }, [dependencySynthesizerService, workspaceListChangedHandler]);

  React.useEffect(() => {
    if (renderTargetRef.current) {
      void renderLoopComponent();
    }
  }, [renderLoopComponent]);

  return <div className={styles.contentContainer} ref={renderTargetRef} />;
};
