import type {
  EventType,
  FilledCustomerContentEvent,
  FilledTelemetryEvent,
  TelemetrySink,
} from '@microsoft/oteljs';

/**
 * A telemetry sink that bypasses queueing and forwards events directly to
 * `Office.telemetrySink`. Used for events that must escape before the page
 * dies (e.g., page unload diagnostics) where the standard batched queue in
 * {@link OfficeTelemetrySinkWrapper} could lose data if `shutdown()` is
 * interrupted.
 *
 * Do not use this for normal events — direct sends bypass our batching,
 * back-pressure handling, and dropped-event accounting.
 */
export class PriorityTelemetrySink implements TelemetrySink {
  private static _instance: PriorityTelemetrySink;

  private constructor() { /* singleton — use PriorityTelemetrySink.Instance */ }

  public static get Instance(): PriorityTelemetrySink {
    if (!PriorityTelemetrySink._instance) {
      PriorityTelemetrySink._instance = new PriorityTelemetrySink();
    }
    return PriorityTelemetrySink._instance;
  }

  sendTelemetryEvent(
    telemetryEvent: FilledTelemetryEvent,
    timestamp?: number,
  ): void {
    Office.telemetrySink.sendTelemetryEvent(telemetryEvent, timestamp);
  }
}

export class OfficeTelemetrySinkWrapper implements TelemetrySink {
  public static readonly MAX_QUEUE_SIZE = 25000;

  // Warning threshold - percentage of queue
  public static readonly QUEUE_WARNING_THRESHOLD_PERCENT = 0.85; // 85%
  // Load thresholds - percentage of queue
  public static readonly VERY_HIGH_LOAD_THRESHOLD_PERCENT = 0.60; // 60%
  public static readonly HIGH_LOAD_THRESHOLD_PERCENT = 0.30; // 30%
  public static readonly MEDIUM_LOAD_THRESHOLD_PERCENT = 0.05; // 5%

  // Calculated thresholds based on max queue size
  public static readonly QUEUE_WARNING_THRESHOLD = Math.floor(
    OfficeTelemetrySinkWrapper.MAX_QUEUE_SIZE * OfficeTelemetrySinkWrapper.QUEUE_WARNING_THRESHOLD_PERCENT
  );
  public static readonly VERY_HIGH_LOAD_THRESHOLD = Math.floor(
    OfficeTelemetrySinkWrapper.MAX_QUEUE_SIZE * OfficeTelemetrySinkWrapper.VERY_HIGH_LOAD_THRESHOLD_PERCENT
  );
  public static readonly HIGH_LOAD_THRESHOLD = Math.floor(
    OfficeTelemetrySinkWrapper.MAX_QUEUE_SIZE * OfficeTelemetrySinkWrapper.HIGH_LOAD_THRESHOLD_PERCENT
  );
  public static readonly MEDIUM_LOAD_THRESHOLD = Math.floor(
    OfficeTelemetrySinkWrapper.MAX_QUEUE_SIZE * OfficeTelemetrySinkWrapper.MEDIUM_LOAD_THRESHOLD_PERCENT
  );

  // Batch size configuration
  public static readonly BATCH_SIZE_PERCENT = 0.1; // 10% of queue
  public static readonly MIN_BATCH_SIZE = 35; // Hard lower limit
  public static readonly MAX_BATCH_SIZE = 175; // Hard upper limit

  // Base interval and multipliers for each load level
  public static readonly BASE_INTERVAL = 25; // 25ms base
  public static readonly VERY_HIGH_LOAD_INTERVAL_MULTIPLIER = 20; // 500ms
  public static readonly HIGH_LOAD_INTERVAL_MULTIPLIER = 22; // 550ms
  public static readonly MEDIUM_LOAD_INTERVAL_MULTIPLIER = 24; // 600ms
  public static readonly LOW_LOAD_INTERVAL_MULTIPLIER = 26; // 650ms
  // Calculated intervals
  public static readonly VERY_HIGH_LOAD_INTERVAL =
    OfficeTelemetrySinkWrapper.BASE_INTERVAL * OfficeTelemetrySinkWrapper.VERY_HIGH_LOAD_INTERVAL_MULTIPLIER;
  public static readonly HIGH_LOAD_INTERVAL =
    OfficeTelemetrySinkWrapper.BASE_INTERVAL * OfficeTelemetrySinkWrapper.HIGH_LOAD_INTERVAL_MULTIPLIER;
  public static readonly MEDIUM_LOAD_INTERVAL =
    OfficeTelemetrySinkWrapper.BASE_INTERVAL * OfficeTelemetrySinkWrapper.MEDIUM_LOAD_INTERVAL_MULTIPLIER;
  public static readonly LOW_LOAD_INTERVAL =
    OfficeTelemetrySinkWrapper.BASE_INTERVAL * OfficeTelemetrySinkWrapper.LOW_LOAD_INTERVAL_MULTIPLIER;

  private static _instance: OfficeTelemetrySinkWrapper;
  private _telemetryQueue: {
    FilledTelemetryEvent: FilledTelemetryEvent;
    timestamp?: number;
  }[] = [];
  private _processingQueue = false;
  private _isShutdown = false;
  private _droppedEventCount = 0;
  private _startProcessingQueueTimer: NodeJS.Timeout | undefined;
  private _hasWarned = false;
  private _drainAttempted = false;
  private _drainCompleted = false;

  public static get Instance(): OfficeTelemetrySinkWrapper {
    if (!OfficeTelemetrySinkWrapper._instance) {
      OfficeTelemetrySinkWrapper._instance = new OfficeTelemetrySinkWrapper();
    }
    return OfficeTelemetrySinkWrapper._instance;
  }

  /**
   * Send a telemetry event to the telemetry sink
   * Add the event to the queue and process the queue with adaptive intervals based on queue size
   * @param telemetryEvent The telemetry event to send
   * @param timestamp The timestamp of the event
   */
  sendTelemetryEvent(
    telemetryEvent: FilledTelemetryEvent,
    timestamp?: number,
  ): void {
    // Warn when entering warning threshold
    if (
      !this._hasWarned &&
      this._telemetryQueue.length >= OfficeTelemetrySinkWrapper.QUEUE_WARNING_THRESHOLD
    ) {
      this._hasWarned = true;
      console.warn(
        `Telemetry queue size (${this._telemetryQueue.length}) exceeded warning threshold (${OfficeTelemetrySinkWrapper.QUEUE_WARNING_THRESHOLD}).`,
      );
    }

    // Enforce max queue size - drop event if at capacity
    if (this._isShutdown || this._telemetryQueue.length >= OfficeTelemetrySinkWrapper.MAX_QUEUE_SIZE) {
      this._droppedEventCount++;
      return;
    }

    this._telemetryQueue.push({
      FilledTelemetryEvent: telemetryEvent,
      timestamp: timestamp,
    });

    if (this._processingQueue) {
      return;
    }

    if (!this._startProcessingQueueTimer) {
      this._startProcessingQueueTimer = setTimeout(() => {
        this._processingQueue = true;
        this._startProcessingQueueTimer = undefined;
        void this.processQueue();
      }, OfficeTelemetrySinkWrapper.LOW_LOAD_INTERVAL);
    }
  }

  sendCustomerContent?(customerContentEvent: FilledCustomerContentEvent): void {
    Office.telemetrySink.sendCustomerContent(customerContentEvent);
  }
  sendNonStandardEvent?(
    telemetryEvent: FilledTelemetryEvent,
    eventType: EventType,
  ): void {
    Office.telemetrySink.sendNonStandardEvent(telemetryEvent, eventType);
  }

  /**
   * Process the telemetry queue with adaptive batch sizes and intervals
   * Adjusts processing rate based on queue length.
   */
  private async processQueue(): Promise<void> {
    while (this._telemetryQueue.length > 0) {
      const queueLength = this._telemetryQueue.length;

      // Calculate batch size as percentage of queue, enforced minimum and maximum hard limits
      const batchSize = Math.max(
        OfficeTelemetrySinkWrapper.MIN_BATCH_SIZE,
        Math.min(
          OfficeTelemetrySinkWrapper.MAX_BATCH_SIZE,
          Math.floor(queueLength * OfficeTelemetrySinkWrapper.BATCH_SIZE_PERCENT)
        )
      );

      // Process batch
      for (let count = 0; count < batchSize; count++) {
        const telemetryEvent = this._telemetryQueue.shift();
        if (telemetryEvent) {
          try {
            Office.telemetrySink.sendTelemetryEvent(
              telemetryEvent.FilledTelemetryEvent,
              telemetryEvent.timestamp,
            );
          } catch {
            // The native sink threw: the event is lost. Count it (so DroppedEventCount doesn't
            // under-report loss) and keep draining rather than stranding the rest of the queue.
            this._droppedEventCount++;
          }
        } else {
          break; // Queue empty
        }
      }

      // Log when queue drops below warning threshold
      if (this._hasWarned && this._telemetryQueue.length < OfficeTelemetrySinkWrapper.QUEUE_WARNING_THRESHOLD) {
        this._hasWarned = false;
        console.log(
          `Telemetry queue size (${this._telemetryQueue.length}) dropped below warning threshold (${OfficeTelemetrySinkWrapper.QUEUE_WARNING_THRESHOLD}).`,
        );
      }

      if (this._telemetryQueue.length > 0) {
      // Determine next interval based on queue length - default to low load interval
        let interval: number = OfficeTelemetrySinkWrapper.LOW_LOAD_INTERVAL;
        const queueLength = this._telemetryQueue.length;
        if (queueLength >= OfficeTelemetrySinkWrapper.VERY_HIGH_LOAD_THRESHOLD) {
          interval = OfficeTelemetrySinkWrapper.VERY_HIGH_LOAD_INTERVAL;
        } else if (queueLength >= OfficeTelemetrySinkWrapper.HIGH_LOAD_THRESHOLD) {
          interval = OfficeTelemetrySinkWrapper.HIGH_LOAD_INTERVAL;
        } else if (queueLength >= OfficeTelemetrySinkWrapper.MEDIUM_LOAD_THRESHOLD) {
          interval = OfficeTelemetrySinkWrapper.MEDIUM_LOAD_INTERVAL;
        }

        // Wait before processing the next batch
        await new Promise(resolve => setTimeout(resolve, interval));
      }
    }
    this._processingQueue = false;
  }

  /**
   * Number of telemetry events lost: dropped because the queue was at capacity or the sink was
   * shut down, plus events whose send to `Office.telemetrySink` threw during processing/drain.
   */
  public get droppedEventCount(): number {
    return this._droppedEventCount;
  }

  /**
   * Current number of events waiting in the batched queue. Read on teardown to
   * record how much telemetry was still pending (and at risk) when the page unloaded.
   */
  public get queueLength(): number {
    return this._telemetryQueue.length;
  }

  /** The maximum queue capacity, exposed for diagnostics relative to the cap. */
  public get maxQueueSize(): number {
    return OfficeTelemetrySinkWrapper.MAX_QUEUE_SIZE;
  }

  /** Whether a synchronous drain (via {@link drain} or {@link shutdown}) has been attempted. */
  public get drainAttempted(): boolean {
    return this._drainAttempted;
  }

  /** Whether the most recent drain emptied the queue completely. */
  public get drainCompleted(): boolean {
    return this._drainCompleted;
  }

  /**
   * Shuts down the telemetry sink: stops accepting new events and
   * immediately flushes all remaining queued events to the host.
   *
   * Safe to call from both sync contexts (e.g., `beforeunload`) and
   * async contexts (e.g., before `window.location.reload()`).
   */
  public shutdown(): void {
    this._isShutdown = true;
    this.drainInternal();
  }

  /**
   * Proactively drains the current queue to `Office.telemetrySink` WITHOUT shutting
   * down — the sink stays alive and any telemetry enqueued afterward batches normally.
   * Used to egress at-risk telemetry immediately (e.g., a UI-less load completing in the
   * background, where the timed batch drain is throttled/suspended). No-op once shut down.
   */
  public drain(): void {
    if (this._isShutdown) {
      return;
    }
    this.drainInternal();
  }

  /**
   * Immediately drains the queued events to Office.telemetrySink synchronously,
   * cancelling any pending batch timer. Synchronous, so no new event can interleave;
   * events enqueued after this returns batch normally. Per-item try/catch so one bad
   * send doesn't strand the rest.
   */
  private drainInternal(): void {
    this._drainAttempted = true;
    if (this._startProcessingQueueTimer) {
      clearTimeout(this._startProcessingQueueTimer);
      this._startProcessingQueueTimer = undefined;
    }
    while (this._telemetryQueue.length > 0) {
      const telemetryEvent = this._telemetryQueue.shift();
      if (telemetryEvent) {
        try {
          Office.telemetrySink.sendTelemetryEvent(
            telemetryEvent.FilledTelemetryEvent,
            telemetryEvent.timestamp,
          );
        } catch {
          // The native sink threw: the event is already off the queue and lost. Count it so
          // teardown diagnostics (DroppedEventCount) don't under-report, and keep draining.
          this._droppedEventCount++;
        }
      }
    }
    this._drainCompleted = this._telemetryQueue.length === 0;
    this._processingQueue = false;
  }
}
