
import type { Audience, Environment } from '@fluidx/loop-types';
import { AudienceGroup as OfficeAudienceGroup } from '@microsoft/oteljs';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import {
  type SovereignCloudType, getCloudType, isSovereignCloud,
} from './Cloud';
import { featureGates } from './FeatureGates';
import { HostAppSettingName, HostAppSettings } from './HostAppSettings';

let cachedAudience: Audience | undefined;
/**
 * Returns the detected Loop audience, using a cached value for efficiency.
 */
export function getAudience(): Audience {
  if (!cachedAudience) {
    cachedAudience = getAudienceInternal();
    console.log('Using Loop Audience:', cachedAudience);
  }
  return cachedAudience;
}

export type ChannelType =
  | 'CC'
  | 'DevMain'
  | 'MEC';

export type OfficeAudienceGroupChannel =
  | 'Dogfood_CC'
  | 'Dogfood_DevMain'
  | 'Microsoft_CC'
  | 'Insiders_CC'
  | 'Insiders_DevMain'
  | 'Production_CC'
  | 'Production_MEC';

/**
 * Maps OfficeAudienceGroup to Loop Audience.
 * NOTE: Loop rollouts go as follows: staging -> dogfood -> preview -> microsoft -> production.
 * See https://eng.ms/docs/experiences-devices/opg/office-shared/loop-experiences/loop-experiences/loop-experiences-ffx-docs/docs/oce-playbook/oce-teams/triage-and-im-rotations/partners/hosts/audiencemapping
 */
const AUDIENCE_GROUP_TO_AUDIENCE: Record<OfficeAudienceGroup, Audience> = {
  Automation: 'Development',
  Insiders: 'Production',
  Dogfood: 'Dogfood',
  Microsoft: 'Microsoft',
  Production: 'Production',
};

const AUDIENCE_GROUP_CHANNEL_TO_AUDIENCE: Record<OfficeAudienceGroupChannel, Audience> = {
  Dogfood_CC: 'Dogfood',
  Dogfood_DevMain: 'Dogfood',
  Microsoft_CC: 'Microsoft',
  Insiders_CC: 'Production',
  Insiders_DevMain: 'Preview',
  Production_CC: 'Production',
  Production_MEC: 'Production',
};

/**
 * Maps cloud types for sovereign clouds to sovereign Loop audiences.
 */
const SOVEREIGN_CLOUD_TYPE_TO_AUDIENCE: Record<SovereignCloudType, Audience> = {
  GCCM: 'GCC',
  GCCH: 'GCC-High',
  DoD: 'DoD',
};

function getAudienceInternal(): Audience {
  // Check if the Loop Audience is set via feature gate override
  const useLoopAudienceOverrideValue = featureGates.getBooleanFeatureGate('useLoopAudienceOverride', false);
  const loopAudienceOverrideValue = featureGates.getStringFeatureGate('loopAudienceOverride', '');
  if (useLoopAudienceOverrideValue && loopAudienceOverrideValue) {
    const settingAudience = getAudienceFromSetting(loopAudienceOverrideValue);
    console.log(`Mapped Loop audience: ${settingAudience} from setting override value: ${loopAudienceOverrideValue}`);
    return settingAudience;
  }

  // Check if this is a sovereign cloud
  if (isSovereignCloud()) {
    const cloudType = getCloudType() as SovereignCloudType;
    const sovereignAudience = SOVEREIGN_CLOUD_TYPE_TO_AUDIENCE[cloudType];
    if (!sovereignAudience) {
      const error = new Error(`Unhandled sovereign cloud type to audience mapping: '${cloudType}'`);
      TelemetryLogger.Instance.logError('UnhandledConfigError', error, {
        ErrorMethod: 'getAudienceInternal',
        ConfigDataValue: cloudType,
        ConfigDataExpectedType: 'SovereignCloudType',
      });
      throw error;
    }
    return sovereignAudience;
  }

  const audienceGroupValue = HostAppSettings.getSetting<string>(HostAppSettingName.HostAudienceGroup, 'Production');
  const audienceGroup = getAudienceGroupFromSetting(audienceGroupValue);
  const hostChannelValue = HostAppSettings.getSetting<string>(HostAppSettingName.HostChannel, 'CC');
  const hostChannel = getChannelFromSetting(hostChannelValue);
  console.log('Using Host Channel:', hostChannel);

  // Try channel-specific mapping first
  const channelKey = `${audienceGroup}_${hostChannel}` as OfficeAudienceGroupChannel;
  const mappedFromChannel = AUDIENCE_GROUP_CHANNEL_TO_AUDIENCE[channelKey];
  if (mappedFromChannel) {
    return mappedFromChannel;
  }

  // Fallback to audience group mapping
  const mappedFromAudience = AUDIENCE_GROUP_TO_AUDIENCE[audienceGroup];
  if (mappedFromAudience) {
    return mappedFromAudience;
  }

  // Handle unrecognized audience group
  const error = new Error('Unhandled Office audience group to Loop audience mapping');
  TelemetryLogger.Instance.logError('UnhandledConfigError', error, {
    ErrorMethod: 'getAudienceInternal',
    ConfigDataValue: audienceGroup,
    ConfigDataExpectedType: 'OfficeAudienceGroup'
  });
  return 'Production';
}

let cachedEnvironment: Environment | undefined;
/**
 * Returns the detected Loop environment, using a cached value for efficiency.
 */
export function getEnvironment(): Environment {
  if (!cachedEnvironment) {
    cachedEnvironment = getEnvironmentInternal();
  }
  return cachedEnvironment;
}

function getEnvironmentInternal(): Environment {
  const audience = getAudience();
  if (audience === 'Local') {
    return { audience: 'Local', ring: 'Staging' };
  }
  // For all other audiences, provide a default ring if required by Environment type
  // If Environment type requires 'ring', you may need to map audience to ring here
  // For now, fallback to 'Production' ring if not Local
  return { audience } as Environment;
}

/**
 * Maps setting string values to Loop Audience.
 */
const AUDIENCE_SETTING_MAP: Record<string, Audience> = {
  automation: 'Automation',
  development: 'Development',
  dod: 'DoD',
  dogfood: 'Dogfood',
  gcc: 'GCC',
  'gcc-high': 'GCC-High',
  local: 'Local',
  microsoft: 'Microsoft',
  preview: 'Preview',
  production: 'Production',
  staging: 'Staging',
};

function getAudienceFromSetting(value: string): Audience {
  const audienceValue = value.toLowerCase();
  const mapped = AUDIENCE_SETTING_MAP[audienceValue];
  if (!mapped) {
    const error = new Error('Unhandled Loop audience value');
    TelemetryLogger.Instance.logError('UnhandledConfigError', error, {
      ErrorMethod: 'getAudienceFromSetting',
      ConfigDataValue: audienceValue,
      ConfigDataExpectedType: 'LoopAudience'
    });
    return 'Production';
  }
  return mapped;
}

/**
 * Maps setting string values to OfficeAudienceGroup..
 */
const AUDIENCE_GROUP_SETTING_MAP: Record<string, OfficeAudienceGroup> = {
  automation: OfficeAudienceGroup.Automation,
  dogfood: OfficeAudienceGroup.Dogfood,
  insiders: OfficeAudienceGroup.Insiders,
  microsoft: OfficeAudienceGroup.Microsoft,
  production: OfficeAudienceGroup.Production,
};

function getAudienceGroupFromSetting(value: string): OfficeAudienceGroup {
  const groupValue = value.toLowerCase();
  const mapped = AUDIENCE_GROUP_SETTING_MAP[groupValue];
  if (!mapped) {
    const error = new Error('Unhandled Office audience group value');
    TelemetryLogger.Instance.logError('UnhandledConfigError', error, {
      ErrorMethod: 'getAudienceGroupFromSetting',
      ConfigDataValue: groupValue,
      ConfigDataExpectedType: 'OfficeAudienceGroup'
    });
    return OfficeAudienceGroup.Production;
  }
  return mapped;
}

// Maps setting string values to ChannelType.
const CLIENT_CHANNEL_SETTING_MAP: Record<string, ChannelType> = {
  cc: 'CC',
  devmain: 'DevMain',
  mec: 'MEC',
};

export function getChannelFromSetting(value: string): ChannelType {
  const channelValue = value.toLowerCase();
  const mapped = CLIENT_CHANNEL_SETTING_MAP[channelValue];
  if (!mapped) {
    const error = new Error('Unhandled Client channel value');
    TelemetryLogger.Instance.logError('UnhandledConfigError', error, {
      ErrorMethod: 'getChannelFromSetting',
      ConfigDataValue: channelValue,
      ConfigDataExpectedType: 'ClientChannel'
    });
    return 'CC';
  }
  return mapped;
}

export const resetEnvironmentCache = () => {
  cachedAudience = undefined;
  cachedEnvironment = undefined;
};
