import type { EventFlags } from '@microsoft/oteljs';
import { EnumObjects } from '@microsoft/oteljs';

const {
  DataCategories,
  DiagnosticLevel
} = EnumObjects;

const optionalDiagnosticsEventFlags = {
  dataCategories: DataCategories.ProductServiceUsage,
  diagnosticLevel: DiagnosticLevel.Optional,
};
const AuthEventFlags = {
  AuthTokenWarmup: optionalDiagnosticsEventFlags,
  GetBizChatToken: optionalDiagnosticsEventFlags,
  NAATokenAcquired: optionalDiagnosticsEventFlags,
  SSOTokenAcquired: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

// Sort flags alphabetically

const ErrorEventFlags = {
  ApiBridgeError: optionalDiagnosticsEventFlags,
  AuthError: optionalDiagnosticsEventFlags,
  AppInitError: optionalDiagnosticsEventFlags,
  BizChatAuthError: optionalDiagnosticsEventFlags,
  CdnCodeLoaderPreCacheError: optionalDiagnosticsEventFlags,
  ComponentDataWorkspaceListChangedEventError: optionalDiagnosticsEventFlags,
  ComponentNavigationEventError: optionalDiagnosticsEventFlags,
  DataActionError: optionalDiagnosticsEventFlags,
  DependencyHardTimeout: optionalDiagnosticsEventFlags,
  LoadErrorRecovery: optionalDiagnosticsEventFlags,
  M365ChatSettingsProviderError: optionalDiagnosticsEventFlags,
  FeatureGatesError: optionalDiagnosticsEventFlags,
  NativeEventHandlerError: optionalDiagnosticsEventFlags,
  NavigateToLinkError: optionalDiagnosticsEventFlags,
  NavigateToSearchResultError: optionalDiagnosticsEventFlags,
  NotifyClientError: optionalDiagnosticsEventFlags,
  RenderStallDetected: optionalDiagnosticsEventFlags,
  UnhandledConfigError: optionalDiagnosticsEventFlags,
  UserEligibilityServiceError: optionalDiagnosticsEventFlags,
  WorkspaceManagerError: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const LoopEventFlags = {
  GetLoopView: optionalDiagnosticsEventFlags,
  LoadLoopComponent: optionalDiagnosticsEventFlags,
  LoadLoopWorkspaceComponent: optionalDiagnosticsEventFlags,
  LoadLoopWorkspaceEndToEnd: optionalDiagnosticsEventFlags,
  PreCacheCodeLoader: optionalDiagnosticsEventFlags,
  RenderLoopComponent: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const M365ChatSettingsProviderEventFlags = {
  GetAllCachedEcsResponses: optionalDiagnosticsEventFlags,
  M365ECSChatVersion: optionalDiagnosticsEventFlags,
  PopulateUserEligibilityInformation: optionalDiagnosticsEventFlags,
  UserEligibilityServiceAPICall: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const NavigationEventFlags = {
  NavigateTo: optionalDiagnosticsEventFlags,
  NavigateToLink: optionalDiagnosticsEventFlags,
  NavigateToSearchResult: optionalDiagnosticsEventFlags,
  NavigationBuffered: optionalDiagnosticsEventFlags,
  NavigationBufferFlushed: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const InteropEventFlags = {
  NativeEventReceived: optionalDiagnosticsEventFlags,
  NotifyClientEvent: optionalDiagnosticsEventFlags,
  DataActionEvent: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const WorkSpaceManagerEventFlags = {
  GetRecentPages: optionalDiagnosticsEventFlags,
  GetWorkspaceForPage: optionalDiagnosticsEventFlags,
  GetWorkspaces: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const InfraEventFlags = {
  PageUnload: optionalDiagnosticsEventFlags,
  TelemetryQueueOverflow: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

const LoadStateEventFlags = {
  LoadStateScenarioForceClosed: optionalDiagnosticsEventFlags,
  LoadStateScenarioRegistered: optionalDiagnosticsEventFlags,
  LoadStateScenarioUnregistered: optionalDiagnosticsEventFlags,
  RenderEndToEnd: optionalDiagnosticsEventFlags,
} as const satisfies Record<string, EventFlags>;

export const eventFlags = {
  ...AuthEventFlags,
  ...ErrorEventFlags,
  ...InteropEventFlags,
  ...InfraEventFlags,
  ...LoadStateEventFlags,
  ...LoopEventFlags,
  ...M365ChatSettingsProviderEventFlags,
  ...NavigationEventFlags,
  ...WorkSpaceManagerEventFlags,
} as const satisfies Record<string, EventFlags>;

export declare type EventName = keyof typeof eventFlags;
