import type {
  Disposable,
  ProvideDisposable,
  TokenProvider,
  TokenRequestOptions,
  TokenResponse,
} from '@fluidx/loop-types';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { getCloudType } from '../utils/Cloud';
import {
  getTokenDefinitionFromResourceStrings,
  getUserAccountType,
} from './HostAuthServiceUtils';
import type { Identity } from './HostAuthServiceUtils';
import { NestedAppAuthService } from './NestedAppAuthService';
import { type TokenType } from './endpoints';
import {
  CLOUD_TYPE_TO_REDIRECT,
  getResourceForScopes,
} from './utils';

export class LwcAuthService implements TokenProvider, ProvideDisposable, Disposable {
  private isDisposed = false;
  private appId: string;
  private redirectUri = CLOUD_TYPE_TO_REDIRECT[getCloudType()];
  private identity: Identity;
  private nestedAppAuthService: NestedAppAuthService;

  constructor(identity: Identity, appId: string) {
    this.identity = identity;
    this.appId = appId;
    this.nestedAppAuthService = new NestedAppAuthService(this.appId, this.redirectUri, identity);
  }

  public get TokenProvider(): TokenProvider {
    return this;
  }

  public get Disposable(): Disposable {
    return this;
  }

  public dispose(): void {
    this.isDisposed = true;
    this.clearCache();
  }

  public clearCache(): void {
    this.nestedAppAuthService.clearCache();
  }

  public setIdentity(identity: Identity): void {
    this.identity = identity;
    this.nestedAppAuthService.setIdentity(identity);
  }

  public getIdentity(): Identity | undefined {
    if (this.isDisposed) {
      return undefined;
    }
    return this.identity;
  }

  public async getToken(scopes: string[], options: TokenRequestOptions): Promise<TokenResponse> {
    if (this.isDisposed) {
      throw new Error('Provider has been disposed');
    }

    let requestedResource = '';
    try {
      requestedResource = getResourceForScopes(scopes);
    } catch (error) {
      const authError = new Error('Failed to get resource from scopes');
      TelemetryLogger.Instance.logError('AuthError', authError, { ErrorMethod: 'LwcAuthService.getToken.getResourceForScopes' });
      throw authError;
    }

    let resourceLowerCase = requestedResource.toLowerCase();

    if (resourceLowerCase === '') {
      const urlValue = options.request?.url ?? '';
      if (urlValue === '') {
        const authError = new Error('Unsupported token request: empty request URL');
        TelemetryLogger.Instance.logError('AuthError', authError, { ErrorMethod: 'LwcAuthService.getToken.parseRequestURL' });
        throw authError;
      }

      try {
        const url = new URL(urlValue);
        requestedResource = url.origin;
        resourceLowerCase = url.origin.toLowerCase();
      } catch (error) {
        const authError = new Error('Unsupported token request: invalid request URL');
        TelemetryLogger.Instance.logError('AuthError', authError, { ErrorMethod: 'LwcAuthService.getToken.parseRequestURL' });
        throw authError;
      }
    }

    // Check resource URL origin as fallback
    let resourceURL: URL | undefined;
    try {
      resourceURL = new URL(resourceLowerCase);
    } catch (error) {
      console.warn('Could not parse resource as URL');
    }

    const tokenDefinition = getTokenDefinitionFromResourceStrings(
      [resourceLowerCase, resourceURL?.origin.toLowerCase() ?? ''],
      getUserAccountType(this.identity),
      getCloudType()
    );
    const resourceUri = tokenDefinition?.resource ?? resourceLowerCase;
    const appendDefaultScope = tokenDefinition?.appendDefaultScope ?? true;
    let tokenType: TokenType = tokenDefinition?.tokenType ?? 'UNKNOWN';

    if (tokenType === 'UNKNOWN') {
      const sharepointDomains = ['.sharepoint.com', '.sharepoint-df.com', '.sharepoint.us', '.sharepoint-mil.us'];
      if (sharepointDomains.some(domain => resourceURL?.hostname.endsWith(domain))) {
        tokenType = 'SHAREPOINT';
      } else {
        TelemetryLogger.Instance.logError('AuthError', new Error('Unknown token resource'), { ErrorMethod: 'LwcAuthService.getToken.resolveTokenType', TokenType: 'UNKNOWN' });
      }
    }

    try {
      const tokenString = await this.nestedAppAuthService.getToken({
        resourceUri,
        tokenType,
        appendDefaultScope,
        forceRefresh: options?.forceRefresh,
        claims: options?.claims,
      });
      return { token: tokenString };
    } catch (error) {
      TelemetryLogger.Instance.logError('AuthError', error instanceof Error ? error : new Error(String(error)), {
        ErrorMethod: 'LwcAuthService.getToken',
        TokenType: tokenType,
      });
      throw new Error(`Token acquisition failed for: ${tokenType}`);
    }
  }

  public async getTokenForTokenType(tokenType: TokenType): Promise<string> {
    if (this.isDisposed) {
      throw new Error('Provider has been disposed');
    }

    return this.nestedAppAuthService.getToken({ tokenType });
  }

  public async getTokenForResourceUri(resourceUri: string, tokenType: TokenType, appendDefaultScope: boolean, forceRefresh?: boolean): Promise<string> {
    if (this.isDisposed) {
      throw new Error('Provider has been disposed');
    }

    return this.nestedAppAuthService.getToken({
      resourceUri,
      tokenType,
      appendDefaultScope,
      forceRefresh,
    });
  }
}

