import type { Disposable, InternationalizationContext } from '@fluidx/loop-types';
import type { Locale, LocaleDirection } from '@fluidx/utilities';
import { getUIDirection } from '@fluidx/utilities';

export function getInternationalizationContext(
  locale: Locale
): InternationalizationContext & Disposable {
  // Get localization properties
  const localeDirection: LocaleDirection = getUIDirection(locale);
  const internationalizationContext: InternationalizationContext & Disposable = {
    get InternationalizationContext() {
      return this;
    },
    uiLocale: locale,
    defaultContentDirection: localeDirection,
    get Disposable() {
      return this;
    },
    dispose() {
      return;
    },
  };

  return internationalizationContext;
}
