export class NativeInteropError extends Error {
  static readonly E_FAIL = 0x80004005;

  private readonly hresult: number;

  constructor(hresult: number, message?: string) {
    super(message);
    this.hresult = hresult;
    this.name = new.target.prototype.constructor.name;
    Object.setPrototypeOf(this, new.target.prototype);
  }

  get errorCode() {
    return this.hresult;
  }
}

export class NotImplementedError extends NativeInteropError {
  static readonly E_NOTIMPL = 0x80004001;

  constructor(message?: string) {
    super(NotImplementedError.E_NOTIMPL, message);
  }
}

export class InvalidArgumentsError extends NativeInteropError {
  static readonly E_INVALIDARG = 0x80070057;

  constructor(message?: string) {
    super(InvalidArgumentsError.E_INVALIDARG, message);
  }
}
