import type { EventName } from './Events';

export enum TelemetryEventType {
  Error = 'Error',
  Latency = 'Latency',
  Warning = 'Warning',
  Info = 'Info'
}

export declare type TelemetryEventDataTypes = boolean | number | string;
export declare type TelemetryEventData = {
  [key: string]: TelemetryEventDataTypes;
};

/**
 * Interface to log events and errors to Telemetry.
 */
export interface ITelemetryLogger {
  logEvent: (
    eventName: EventName,
    data?: TelemetryEventData
  ) => void;

  logError: (
    eventName: EventName,
    error: Error | unknown,
    data?: TelemetryEventData
  ) => void;

  /**
   * Logs an event via a priority path that bypasses queueing and goes
   * directly to the host telemetry sink. Use only for events that must
   * escape before the page may be torn down (e.g., unload diagnostics).
   */
  logPriorityEvent: (
    eventName: EventName,
    data?: TelemetryEventData
  ) => void;
}
