import type {
  Environment,
  HTMLView,
  ProvideDisposable,
  ProvideHTMLViewable,
  Provider,
  SymbolProvider,
} from '@fluidx/loop-types';
import {
  CdnCodeLoaderFactory,
  LoopRegistrationId,
  createWorkspaceComponentRouterInput,
} from '@fluidx/loop-workspace-component';
import type {
  NavigationParams,
  ProvideWorkspaceAndPageManager,
  ProvideWorkspaceNavigationHandler,
} from '@fluidx/loop-workspace-types';
import type { OfficeFluidLogger } from '@fluidx/telemetry';
import type { Locale } from '@fluidx/utilities';
import type { GetLoopComponentProps } from '@ms/office-web-host';
import {
  HostActivity,
  HostActivityTracker,
  getLoopComponent,
} from '@ms/office-web-host';
import type { HostAuthService } from '../auth/HostAuthService';
import { NotifyClient } from '../interop';
import type { M365ChatSettingsProvider } from '../providers/M365ChatSettingsProvider';
import type { DependencySynthesizerService } from '../service/dependencySynthesizer/DependencySynthesizerService';
import type { UserEligibilityService } from '../service/userEligibilityService/UserEligibilityService';
import type { AppWorkspaceManager } from '../service/workspaceManager/AppWorkspaceManager';
import { createOfficeFluidTelemetryLogger } from '../telemetry/FluidTelemetryLogger';
import { TelemetryActivityTracker } from '../telemetry/TelemetryActivityTracker';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { toError } from './ErrorUtils';
import { changeGates, featureGates } from './FeatureGates';
import type { RegisteredScenario } from './loadStateTracker';
import { LoadStateTracker } from './loadStateTracker';
import { OfficeTelemetrySinkWrapper } from '../telemetry/OfficeTelemetrySinkWrapper';
import { TIMEOUT_ERROR_SENTINEL, executeWithTimeout } from './promise';

export type ActionProviderTypes =
  & ProvideHTMLViewable
  & ProvideDisposable
  & ProvideWorkspaceAndPageManager
  & ProvideWorkspaceNavigationHandler;
const requiredProviderTypes: SymbolProvider<ActionProviderTypes> = {
  HTMLViewable: 'HTMLViewable',
  Disposable: 'Disposable',
  WorkspaceAndPageManager: 'WorkspaceAndPageManager',
  WorkspaceNavigationHandler: 'WorkspaceNavigationHandler',
};

export type LoadLoopWorkspaceComponentResult = {
  loopComponent: Provider<ActionProviderTypes>;
  fluidLogger: OfficeFluidLogger;
  view: HTMLView | undefined;
};

export const loadLoopWorkspaceComponent = async (
  appWorkspaceManager: AppWorkspaceManager,
  authService: HostAuthService,
  dependencySynthesizerService: DependencySynthesizerService,
  environment: Environment,
  locale: Locale,
  loadNavParams: NavigationParams,
  shouldRender: boolean,
  m365ChatSettingsProvider: M365ChatSettingsProvider,
  userEligibilityService: UserEligibilityService,
  renderTarget?: HTMLElement,
): Promise<LoadLoopWorkspaceComponentResult> => {
  return TelemetryActivityTracker.runActivity(
    'LoadLoopWorkspaceEndToEnd',
    async (activity) => {
      activity.addData('InViewPort', shouldRender);
      const preloadStartTime = Date.now();
      const fluidLogger = createOfficeFluidTelemetryLogger(
        authService.getUserContext(),
      );
      activity.addData('HostScenarioStartTime', preloadStartTime);
      const dependencyStallMs = featureGates.getIntFeatureGate('dependencyStallTimeoutMs', DEFAULT_DEPENDENCY_STALL_TIMEOUT_MS, { min: MIN_DEPENDENCY_STALL_TIMEOUT_MS });
      const dependencyHardTimeoutMs = featureGates.getIntFeatureGate('dependencyHardTimeoutMs', DEFAULT_DEPENDENCY_HARD_TIMEOUT_MS, { min: MIN_DEPENDENCY_HARD_TIMEOUT_MS });
      // Mark the dependency-synthesis window. registerProviders can hang up to ~60s;
      // previously that whole window was hidden under PreLoad.
      LoadStateTracker.setPhase('SynthesizingDependencies');
      const dependencySynthesizer = await withDependencyTimeout(
        'registerProviders',
        dependencySynthesizerService.registerProviders(
          appWorkspaceManager,
          authService,
          environment,
          fluidLogger,
          locale,
          m365ChatSettingsProvider,
          userEligibilityService,
        ),
        dependencyHardTimeoutMs,
      );

      // Pre-caching LWC
      void preCacheCodeLoader(environment, locale);

      const loadProps: GetLoopComponentProps<ActionProviderTypes> = {
        dependencySynthesizer,
        loopComponentRouterInput:
      createWorkspaceComponentRouterInput(loadNavParams),
        config: {
          environment: environment,
          logger: fluidLogger,
        },
        requiredProviderTypes,
      };
      const preloadEndTime = Date.now();
      activity.addData('PreloadDuration', preloadEndTime - preloadStartTime);
      // Load and render the component if render is enabled
      const scenarioTracker = HostActivityTracker.startScenario(
        fluidLogger,
        'Load',
      );
      // Register the scenario so the unload handler can force-close it if the page is torn down
      // mid-load (common on the background UILess path), which would otherwise leave a
      // Start-without-End. Pass the load activity ids explicitly: the global activity stack is
      // unreliable here (the fire-and-forget `void preCacheCodeLoader()` sits on it).
      const scenarioHandle = LoadStateTracker.registerScenario(
        scenarioTracker,
        shouldRender,
        activity.activityId,
        activity.parentActivityId,
      );
      try {
        console.log('HostedWorkspaceUI loadAndRender: awaiting component');
        LoadStateTracker.setPhase('LoadingComponent');
        const component = await loadLoopComponent(loadProps, dependencyStallMs, dependencyHardTimeoutMs);
        LoadStateTracker.setPhase('GettingView');
        const view = (await getView(component, fluidLogger, dependencyStallMs, dependencyHardTimeoutMs))?.HTMLView;

        if (shouldRender && renderTarget) {
          // renderView drives the Rendering -> Idle phase transitions and closes the scenario.
          await renderView(view, renderTarget, fluidLogger, scenarioHandle, activity.activityId);
        } else {
          // UI-less completion: the idempotent helper routes the inViewport=false proof through
          // the priority path + queue snapshot so it survives an unclean background teardown.
          LoadStateTracker.setScenarioSuccess(scenarioHandle, { inViewport: false });
          LoadStateTracker.setPhase('Idle');
          scheduleUILessCompletionDrain();
        }

        return {
          loopComponent: component,
          fluidLogger,
          view,
        };
      } catch (error) {
        const safeError = toError(error);
        // Idempotent: if renderView already closed the scenario (e.g., missing-view), this no-ops.
        LoadStateTracker.setScenarioFailure(scenarioHandle, safeError, { inViewport: shouldRender });
        LoadStateTracker.setPhase('Idle');
        TelemetryLogger.Instance.logError('LoadLoopWorkspaceComponent', safeError, {
          ErrorMethod: 'loadLoopWorkspaceComponent',
        });
        throw error;
      }
    }
  );
};

export const renderView = async (
  view: HTMLView | undefined,
  renderTarget: HTMLElement,
  fluidLogger: OfficeFluidLogger,
  loadScenario?: RegisteredScenario,
  parentActivityId?: number,
): Promise<void> => {
  // Drive the load phase from inside renderView on ALL exit paths (success / missing-view /
  // render-error) so the UILess->navigation render (no load scenario) still reports phase and no
  // path leaves it stuck in 'Rendering'.
  LoadStateTracker.setPhase('Rendering');

  // Dedicated SDX render-to-paint tracker (OWH has no render scenario type). Stall threshold is
  // derived to exceed render()'s own budget (stall + recovery + paint margin) so the Stall warning
  // only fires for a render that truly never paints; the gate may only RAISE it (clamped to floor).
  const renderStallTimeoutMs = featureGates.getIntFeatureGate('renderStallTimeoutMs', DEFAULT_RENDER_STALL_TIMEOUT_MS, { min: MIN_RENDER_STALL_TIMEOUT_MS });
  const renderEndToEndFloorMs = renderStallTimeoutMs + RENDER_STALL_RECOVERY_TIMEOUT_MS + RENDER_END_TO_END_PAINT_MARGIN_MS;
  const renderEndToEndStallMs = Math.max(
    renderEndToEndFloorMs,
    featureGates.getIntFeatureGate('renderEndToEndStallTimeoutMs', renderEndToEndFloorMs, { min: MIN_RENDER_STALL_TIMEOUT_MS }),
  );
  const renderTracker = TelemetryActivityTracker.startTracked('RenderEndToEnd', {
    parentActivityId,
    stallThresholdMs: renderEndToEndStallMs,
  });
  renderTracker.addData('InViewPort', true);
  LoadStateTracker.registerRenderTracker(renderTracker);

  // Guard: a missing view means rendering was expected but the component provided no HTMLViewable.
  // Fail rather than silently report success with a blank screen.
  if (!view) {
    const error = new Error('View is undefined — HTMLViewable not provided by component');
    TelemetryLogger.Instance.logError('LoadLoopWorkspaceComponent', error, {
      ErrorMethod: 'renderView',
    });
    console.error('HostedWorkspaceUI renderView: view is undefined, cannot render');
    renderTracker.failure(error);
    LoadStateTracker.unregisterRenderTracker(renderTracker);
    if (loadScenario) {
      LoadStateTracker.setScenarioFailure(loadScenario, error, { inViewport: true });
    }
    LoadStateTracker.setPhase('Idle');
    throw error;
  }

  const renderActivity = HostActivityTracker.startActivity(fluidLogger, HostActivity.RenderComponent);
  let postRenderActivity: typeof renderActivity | undefined;

  // Paint-completion state hoisted to function scope so the catch can cancel a partially-scheduled
  // completion (e.g. rAF scheduled, then setTimeout throws) and poison a later finishPaint — without
  // this, a pending callback would success-close trackers the catch already failed (double-close).
  let paintFinished = false;
  let rafId: number | undefined;
  let fallbackTimer: ReturnType<typeof setTimeout> | undefined;
  const cancelPendingPaintCompletion = (): void => {
    paintFinished = true;
    if (rafId !== undefined) {
      cancelAnimationFrame(rafId);
      rafId = undefined;
    }
    if (fallbackTimer !== undefined) {
      clearTimeout(fallbackTimer);
      fallbackTimer = undefined;
    }
  };

  try {
    console.log('HostedWorkspaceUI loadAndRender: rendering view');
    await render(view, renderTarget);
    postRenderActivity = HostActivityTracker.startActivity(fluidLogger, HostActivity.PostRender);

    // Paint-completion race: schedule BOTH a requestAnimationFrame AND a fallback setTimeout, and
    // run an IDEMPOTENT completion on whichever fires first. rAF is suspended while the webview is
    // hidden/reparented, so the fallback guarantees closure. Cleanup-first: close trackers + reset
    // phase before the best-effort host-notify, wrapped so a throw there can't strand cleanup.
    const finishPaint = (): void => {
      if (paintFinished) {
        return;
      }
      cancelPendingPaintCompletion();

      if (loadScenario) {
        LoadStateTracker.setScenarioSuccess(loadScenario, { inViewport: true });
      }
      renderTracker.success();
      LoadStateTracker.unregisterRenderTracker(renderTracker);
      LoadStateTracker.setPhase('Idle');

      try {
        postRenderActivity?.setSuccess();
        renderActivity.setSuccess();
        // Notify the host that the component has been rendered. This is async and can reject after
        // teardown (e.g., once the apiBridge is cleaned up), so guard the rejection explicitly —
        // the surrounding try only catches synchronous throws.
        void NotifyClient.renderCompleteEvent().catch((notifyError) => {
          TelemetryLogger.Instance.logError('LoadLoopWorkspaceComponent', toError(notifyError), {
            ErrorMethod: 'renderCompleteEvent',
          });
        });
      } catch (notifyError) {
        TelemetryLogger.Instance.logError('LoadLoopWorkspaceComponent', toError(notifyError), {
          ErrorMethod: 'renderViewFinishPaint',
        });
      }
    };
    rafId = requestAnimationFrame(finishPaint);
    fallbackTimer = setTimeout(finishPaint, PAINT_COMPLETION_FALLBACK_MS);
    console.log('HostedWorkspaceUI loadAndRender: view rendered');
  } catch (error) {
    const safeError = toError(error);
    // Poison any partially-scheduled paint completion BEFORE failing the trackers, so a pending
    // rAF/fallback callback can't later success-close what we're about to fail.
    cancelPendingPaintCompletion();
    renderActivity.setFailure(safeError);
    // Close postRenderActivity if it was created (no-ops when render() itself threw).
    postRenderActivity?.setFailure(safeError);
    renderTracker.failure(safeError);
    LoadStateTracker.unregisterRenderTracker(renderTracker);
    if (loadScenario) {
      LoadStateTracker.setScenarioFailure(loadScenario, safeError, { inViewport: true });
    }
    LoadStateTracker.setPhase('Idle');
    throw error;
  }
};

/**
 * On UI-less completion, proactively drain the batched sink so the Fluid END marker (enqueued via
 * the same sink) egresses before the background-loss window, instead of waiting for the throttled
 * setTimeout drain in the background webview. Runs in a microtask (not throttled when backgrounded)
 * so the Fluid setSuccess has enqueued first. Best-effort for the Fluid marker — the priority
 * Unregistered breadcrumb is the guaranteed proof. Gated by `useUILessCompletionDrain`.
 */
const scheduleUILessCompletionDrain = (): void => {
  if (!changeGates.getBooleanChangeGate('useUILessCompletionDrain')) {
    return;
  }
  queueMicrotask(() => {
    try {
      OfficeTelemetrySinkWrapper.Instance.drain();
    } catch (e) {
      TelemetryLogger.Instance.logError('LoadLoopWorkspaceComponent', toError(e), {
        ErrorMethod: 'uiLessCompletionDrain',
      });
    }
  });
};

const preCacheCodeLoader = async (environment: Environment, locale: Locale) => {
  return TelemetryActivityTracker.runActivity('PreCacheCodeLoader', async () => {
    try {
      const codeLoader = await CdnCodeLoaderFactory.instantiateLoopCodeLoader({
        windowContext: window,
        trustedTypesPolicy: undefined,
        audience: environment.audience,
        localeHint: locale,
      });

      await codeLoader.preCache?.(LoopRegistrationId);
      console.log('HostedWorkspaceUI loadAndRender: pre-caching complete');
    } catch (error) {
      TelemetryLogger.Instance.logError('CdnCodeLoaderPreCacheError', toError(error), {
        ErrorMethod: 'LoadLoopWorkspaceComponent',
      });
    }
  });
};

const loadLoopComponent = async (
  loadProps: GetLoopComponentProps<ActionProviderTypes>,
  stallThresholdMs: number,
  hardTimeoutMs: number,
) => {
  return TelemetryActivityTracker.runActivity('LoadLoopComponent', async () => {
    return await withDependencyTimeout(
      'loadLoopComponent',
      getLoopComponent<ActionProviderTypes>(loadProps),
      hardTimeoutMs,
    );
  }, { stallThresholdMs });
};

const getView = async (component: Provider<ActionProviderTypes>, fluidLogger: OfficeFluidLogger, stallThresholdMs: number, hardTimeoutMs: number) => {
  return TelemetryActivityTracker.runActivity('GetLoopView', async () => {
    return withDependencyTimeout(
      'getView',
      HostActivityTracker.startActivity(fluidLogger, 'GetView' as HostActivity, async () => {
        return component.HTMLViewable?.getView();
      }),
      hardTimeoutMs,
    );
  }, { stallThresholdMs });
};

const DEFAULT_DEPENDENCY_HARD_TIMEOUT_MS = 60000;
const MIN_DEPENDENCY_HARD_TIMEOUT_MS = 5000;
const DEFAULT_DEPENDENCY_STALL_TIMEOUT_MS = 30000;
const MIN_DEPENDENCY_STALL_TIMEOUT_MS = 5000;
const DEFAULT_RENDER_STALL_TIMEOUT_MS = 10000;
const MIN_RENDER_STALL_TIMEOUT_MS = 1000;
const RENDER_STALL_RECOVERY_TIMEOUT_MS = 5000;
// Margin added to render stall+recovery to derive the RenderEndToEnd stall floor, so its Stall
// warning only fires for a render that truly never paints.
const RENDER_END_TO_END_PAINT_MARGIN_MS = 2000;
// Paint-race fallback: long enough for a foreground rAF (~16ms) to win, bounded so a
// hidden/reparented webview (rAF suspended) still closes the load.
const PAINT_COMPLETION_FALLBACK_MS = 1000;

/**
 * Wraps executeWithTimeout with DependencyHardTimeout telemetry logging.
 * Used for upstream dependency calls where a timeout should be reported.
 */
const withDependencyTimeout = <T>(
  operationName: string,
  promise: Promise<T>,
  timeoutMs: number,
): Promise<T> => {
  return executeWithTimeout(operationName, promise, timeoutMs).catch((error: unknown) => {
    if (error instanceof Error && error.message.startsWith(TIMEOUT_ERROR_SENTINEL)) {
      TelemetryLogger.Instance.logError('DependencyHardTimeout', error, {
        ErrorMethod: operationName,
        TimeoutMs: timeoutMs.toString(),
      });
    }
    throw error;
  });
};

const render = async (
  view: HTMLView | undefined,
  renderTarget: HTMLElement,
) => {
  const stallTimeoutMs = featureGates.getIntFeatureGate('renderStallTimeoutMs', DEFAULT_RENDER_STALL_TIMEOUT_MS, { min: MIN_RENDER_STALL_TIMEOUT_MS });

  return TelemetryActivityTracker.runActivity(
    'RenderLoopComponent',
    async () => {
      // If view is undefined, nothing to render
      if (!view) {
        return;
      }

      const renderPromise = view.render(renderTarget);

      // Race the render against a timeout to detect stalls (e.g., stuck IntersectionObserver/ResizeObserver)
      let resolved = false;
      await Promise.race([
        renderPromise.then(() => { resolved = true; }),
        new Promise<void>(r => setTimeout(r, stallTimeoutMs)),
      ]);

      if (!resolved) {
        // Log render-specific diagnostic data for upstream investigation
        TelemetryLogger.Instance.logError('RenderStallDetected', new Error('RenderStallDetected'), {
          ErrorMethod: 'render',
          OffsetWidth: renderTarget.offsetWidth.toString(),
          OffsetHeight: renderTarget.offsetHeight.toString(),
          IsConnected: renderTarget.isConnected.toString(),
        });
        console.warn('HostedWorkspaceUI render: stall detected, attempting layout nudge recovery');

        // Force a synchronous reflow to kick any stuck layout observers.
        // This runs within a single JS frame so the browser does not paint the hidden state.
        const previousDisplay = renderTarget.style.display;
        renderTarget.style.display = 'none';
        void renderTarget.offsetHeight;
        renderTarget.style.display = previousDisplay;

        // Give the original render promise a grace period after the nudge
        await Promise.race([
          renderPromise,
          new Promise<void>((_, reject) => setTimeout(() => reject(new Error('RenderStallUnrecoverable')), RENDER_STALL_RECOVERY_TIMEOUT_MS)),
        ]);
      }
    },
    { stallThresholdMs: stallTimeoutMs },
  );
};
