import React from 'react';
import { useState } from 'react';

import { Locale } from '@fluidx/utilities';
import { HostAuthService } from '../auth/HostAuthService';
import { apiBridge } from '../interop';
import { GetNativeEventHandler } from '../interop/nativeEvents';
import {
  OneNoteSettingsProvider,
} from '../providers/M365ChatSettingsProvider';
import { DependencySynthesizerService } from '../service/dependencySynthesizer/DependencySynthesizerService';
import { UserEligibilityService } from '../service/userEligibilityService/UserEligibilityService';
import { AppWorkspaceManager } from '../service/workspaceManager/AppWorkspaceManager';
import { defaultRedeemStatus, emptyDocUrl, emptyId } from '../service/workspaceManager/constants';
import { buildInitialNavParams } from '../utils/navigation';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { getEnvironment } from '../utils/Environment';
import {
  HostAppSettingName,
  HostAppSettings,
} from '../utils/HostAppSettings';
import { LoadStateTracker } from '../utils/loadStateTracker';
import { installUnloadHandlers } from '../utils/unloadHandler';
import { HostedWorkspaceUI, type IHostedWorkspaceUIProps } from './HostedWorkspaceUI';

export const App = () => {
  // callback to handle window focus before app initialization
  const windowFocus = React.useRef(false);
  const forceRenderHandler = React.useCallback(() => {
    if (!windowFocus.current) {
      console.log('Window focused before app init');
      HostAppSettings.forceRender = true;
    }
    windowFocus.current = true;
  }, [windowFocus]);

  const [workspaceComponentProps, setWorkspaceComponentProps] = useState<IHostedWorkspaceUIProps | undefined>(undefined);

  // Install the unified page-teardown handler (beforeunload + pagehide).
  // See utils/unloadHandler.ts for details.
  // Registered as the first useEffect so it's installed before
  // appInitialize runs — if init fails partway, we still observe the
  // unload.
  React.useEffect(() => installUnloadHandlers(), []);

  // If the window focuses before app initialization, render the UI
  React.useEffect(() => {
    window.addEventListener('focus', forceRenderHandler);

    return () => {
      window.removeEventListener('focus', forceRenderHandler);
    };
  }, [forceRenderHandler]);

  const appInitialize = React.useCallback(async () => {
    console.log('Session ID:', HostAppSettings.getSessionId());
    try {
      const dependencySynthesizerService = new DependencySynthesizerService();
      const appWorkspaceManager = new AppWorkspaceManager();

      // Initialize the API bridge and register the event handler
      await apiBridge.initialize();
      apiBridge.registerEvent(GetNativeEventHandler(appWorkspaceManager));
      // API Bridge is initialized, remove window focus event listener
      window.removeEventListener('focus', forceRenderHandler);

      // Check if the SDX platform was ready when the app was initialized; we'll request a reload if it wasn't.
      // The SDX platform init is async in the host and our SDX can launch before it is ready - there are work items tracking this.
      // For now, we will request a reload if the SDX platform is not ready. We're not guaranteed to reload as the host may throttle requests.
      // This is just a best effort to try and reduce the number of issues we see with the SDX platform not being ready.
      // For backwards client host compat, we will assume the platform is ready if the setting is not present.
      const isSdxPlatformReady = HostAppSettings.getSetting(HostAppSettingName.IsSdxPlatformReady, true);
      if (!isSdxPlatformReady) {
        TelemetryLogger.Instance.logError('AppInitError', new Error('SDX Platform is not ready'), { ErrorMethod: 'appInitialize', ErrorDetails: 'Best effort continuation' });
      }
      console.log('API bridge initialized successfully');

      const environment = getEnvironment();
      const locale = HostAppSettings.getLocale(
        Locale.enUs // Default locale
      );

      // Initialize auth services and identity
      const authService = new HostAuthService();
      await authService.initialize();

      // Initialize the User Eligibility Service
      const userEligibilityService = new UserEligibilityService(authService);

      const m365ChatSettingsProvider = new OneNoteSettingsProvider(environment, authService, locale);

      // Populate user eligibility
      userEligibilityService.populateUserEligibilityInformation();

      // Construct the navigation parameters based on the host app settings
      const navParams = buildInitialNavParams(
        HostAppSettings.getSetting<string>(HostAppSettingName.LaunchPodId, emptyId),
        HostAppSettings.getSetting(HostAppSettingName.LaunchSpoId, emptyId),
        HostAppSettings.getSetting(HostAppSettingName.LaunchDocUrl, emptyDocUrl),
        HostAppSettings.getSetting(HostAppSettingName.LaunchDocUrlRequiresRedeem, defaultRedeemStatus),
      );

      const workspaceComponentProps = {
        appWorkspaceManager,
        authService,
        dependencySynthesizerService,
        environment,
        locale,
        loadNavParams: navParams,
        m365ChatSettingsProvider,
        userEligibilityService,
      };
      setWorkspaceComponentProps(workspaceComponentProps);
      LoadStateTracker.markAppInitialized();
    }
    catch (error) {
      TelemetryLogger.Instance.logError('AppInitError', error, { ErrorMethod: 'appInitialize', ErrorDetails: 'Error initializing app' });
    }
  }, [forceRenderHandler]);

  React.useEffect(() => {
    void Office.onReady(appInitialize);
  }, [appInitialize]);

  if (workspaceComponentProps) {
    return <HostedWorkspaceUI {...workspaceComponentProps} />;
  }

  return <></>;

};
