import type { AppPlatform, Locale } from '@fluidx/utilities';
import { v4 as uuidv4 } from 'uuid';

export enum HostAppSettingName {
  HostAudienceGroup = 'HostAudienceGroup',
  HostChannel = 'HostChannel',
  LaunchDocUrl = 'LaunchDocUrl',
  LaunchDocUrlRequiresRedeem = 'LaunchDocUrlRequiresRedeem',
  LaunchPodId = 'LaunchPodId',
  LaunchSpoId = 'LaunchSpoId',
  IsUILessLoad = 'IsUILessLoad',
  IsCopilotPremiumIdentity = 'IsCopilotPremiumIdentity',
  IsSdxPlatformReady = 'IsSdxPlatformReady'
}

const fallbackHostSessionId = uuidv4();
const fallbackCorrelationId = uuidv4();

export class HostAppSettings {
  public static forceRender = false;
  public static getSetting<T>(name: HostAppSettingName, defaultValue: T): T {
    return Office.context.document.settings.get(name) as T ?? defaultValue;
  }
  public static getLocale(defaultValue: Locale): Locale {
    return (Office.context.displayLanguage?.toLowerCase() ?? defaultValue) as Locale;
  }
  public static getPlatform(): AppPlatform {
    const hostPlatform = Office.context.platform;
    switch (hostPlatform) {
      case Office.PlatformType.PC:
        return 'Win32';
      case Office.PlatformType.OfficeOnline:
        return 'Web';
      case Office.PlatformType.Mac:
        return 'Mac';
      case Office.PlatformType.iOS:
        return 'iOS';
      case Office.PlatformType.Android:
        return 'Android';
      default:
        return 'Win32';
    }
  }
  public static getCorrelationId(): string {
    return Office.context.document.settings.get('HostCorrelationId') ?? fallbackCorrelationId;
  }
  public static getSessionId(): string {
    return (
      Office.context.document.settings.get('HostSessionId') ?? fallbackHostSessionId
    );
  }
  public static isUILessLoad(): boolean {
    return HostAppSettings.forceRender ? false : HostAppSettings.getSetting<boolean>(HostAppSettingName.IsUILessLoad, false);
  }

  /**
   * Clears settings that are no longer needed after rendering the UI
   */
  public static clearOnRenderSettings(): void {
    Office.context.document.settings.remove(HostAppSettingName.IsUILessLoad);
    Office.context.document.settings.remove(HostAppSettingName.LaunchDocUrl);
    Office.context.document.settings.remove(HostAppSettingName.LaunchDocUrlRequiresRedeem);
    Office.context.document.settings.remove(HostAppSettingName.LaunchPodId);
    Office.context.document.settings.remove(HostAppSettingName.LaunchSpoId);
  }
}
