import type {
  KeyboardEventInfo,
  LinkOptions,
  ProvideDisposable,
  UrlHandlerProvider,
} from '@fluidx/loop-types';
import type { AppWorkspaceManager } from '../service/workspaceManager/AppWorkspaceManager';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { changeGates } from '../utils/FeatureGates';

/**
 * Detects Office app hinted by the special token in some OneDrive/SharePoint links.
 * Looks for a path segment like `/:p:/`, `/:x:/`, `/:o:/`, `/:w:/`, or `/:fl:/` and maps
 * them to PowerPoint, Excel, OneNote, Word and Loop respectively.
 * @returns 'powerpoint' | 'excel' | 'onenote' | 'word' | 'loop' |'unknown'
 */
export function detectOfficeAppFromUrl(url: URL | string) {
  const u = typeof url === 'string' ? new URL(url) : url;
  // Look in the pathname for the token pattern: /:p:/, /:x:/, /:o:/, /:w:/, /:fl:/
  const match = u.pathname.match(/\/:([pxow]|fl):\//i);
  if (!match || match.length < 2) return 'unknown';
  switch (match[1].toLowerCase()) {
    case 'p':
      return 'powerpoint';
    case 'x':
      return 'excel';
    case 'o':
      return 'onenote';
    case 'w':
      return 'word';
    case 'fl':
      return 'loop';
    default:
      return 'unknown';
  }
}

export class OneNoteUrlHandlerProvider
implements UrlHandlerProvider, ProvideDisposable
{
  constructor(private readonly appWorkspaceManager: AppWorkspaceManager) {}

  onClick(
    url: URL,
    _linkOptions?: LinkOptions,
    _event?: MouseEvent | PointerEvent | KeyboardEventInfo,
  ): Promise<boolean> {
    // Check for a `file` query parameter and whether it contains Office extensions
    const useFileExtFilter = changeGates.getBooleanChangeGate('useFileExtFilter');
    if (useFileExtFilter) {
      try {
        const fileParam = url.searchParams.get('file');
        if (fileParam) {
          const lower = fileParam.toLowerCase();
          const hasOfficeExt =
            lower.endsWith('.docx') || lower.endsWith('.pptx') || lower.endsWith('.xlsx');
          if (hasOfficeExt) {
            TelemetryLogger.Instance.logEvent('NavigateToLink', {
              LinkHandler: 'OneNoteUrlHandlerProvider',
              NavigationSuccess: false,
              FilterReason: 'OfficeFileExtension',
            });
            return Promise.resolve(false);
          }
        }
      } catch {
        TelemetryLogger.Instance.logError('NavigateToLinkError', new Error('Error checking file parameter on URL'), { ErrorMethod: 'OneNoteUrlHandlerProvider.onClick' });
      }
    }

    const useAppHintFilter = changeGates.getBooleanChangeGate('useAppHintFilter');
    if (useAppHintFilter) {
      const appHint = detectOfficeAppFromUrl(url);
      if (appHint !== 'onenote' && appHint !== 'unknown') {
        TelemetryLogger.Instance.logEvent('NavigateToLink', {
          LinkHandler: 'OneNoteUrlHandlerProvider',
          NavigationSuccess: false,
          FilterReason: 'AppHintFilter',
        });
        return Promise.resolve(false);
      }
    }

    return this.appWorkspaceManager
      .appNavigateToResourceLinkInClient({ linkUrl: url.toString() })
      .then(() => {
        TelemetryLogger.Instance.logEvent('NavigateToLink', { LinkHandler: 'OneNoteUrlHandlerProvider', NavigationSuccess: true });
        return Promise.resolve(true);
      })
      .catch((_error) => {
        TelemetryLogger.Instance.logError('NavigateToLinkError', new Error('appNavigateToResourceLinkInClient failed'), { ErrorMethod: 'OneNoteUrlHandlerProvider.onClick' });
        return Promise.resolve(false);
      });
  }
  UrlHandlerProvider: UrlHandlerProvider = this;
  public get Disposable() {
    return this;
  }
  dispose() {
    // no-op
  }
}
