import type { Audience } from '@fluidx/loop-types';
import type { EcsTeamSettings } from '@fluidx/settings-provider/lib/interfaces/ecsClientInterfaces';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { featureGates } from '../utils/FeatureGates';

type M365ChatDeploymentRing = 'SDFV2' | 'MSIT' | 'WW' | 'ITAR';
type M365ChatEnvironment = 'SDF' | 'MSIT' | 'Prod' | 'GCCModerate' | 'GCCHigh' | 'DoD';

const M365_CHAT_DEPLOYMENT_RING_MAP: Record<string, M365ChatDeploymentRing> = {
  sdfv2: 'SDFV2',
  msit: 'MSIT',
  ww: 'WW',
  itar: 'ITAR',
};

export const getM365ChatDeploymentRingFromAudience = (audience: Audience): M365ChatDeploymentRing => {
  const useOverride = featureGates.getBooleanFeatureGate('useM365ChatDeploymentRingOverride', false);
  const overrideValue = featureGates.getStringFeatureGate('m365ChatDeploymentRingOverride', '');
  if (useOverride && overrideValue) {
    const mapped = M365_CHAT_DEPLOYMENT_RING_MAP[overrideValue.toLowerCase()];
    if (mapped) {
      return mapped;
    }
    TelemetryLogger.Instance.logError('M365ChatSettingsProviderError', new Error('Unhandled M365Chat deployment ring override value'), {
      ErrorMethod: 'getM365ChatDeploymentRingFromAudience',
      ConfigDataValue: overrideValue,
    });
  }

  switch (audience) {
    case 'Automation':
    case 'Development':
    case 'Dogfood':
    case 'Staging':
    case 'Local':
    case 'SyntheticTraffic':
      return 'SDFV2';
    case 'Preview':
    case 'Microsoft':
      return 'MSIT';
    case 'GCC':
      return 'WW';
    case 'GCC-High':
      return 'ITAR';
    case 'DoD':
      return 'ITAR';
    case 'Production':
      return 'WW';
    default: {
      const error = new Error(`Unhandled audience for M365Chat deployment ring: '${audience}'`);
      TelemetryLogger.Instance.logError('M365ChatSettingsProviderError', error, {
        ErrorMethod: 'getM365ChatDeploymentRingFromAudience',
        ConfigDataValue: audience,
      });
      throw error;
    }
  }
};

const M365_CHAT_ENVIRONMENT_MAP: Record<string, M365ChatEnvironment> = {
  sdf: 'SDF',
  msit: 'MSIT',
  prod: 'Prod',
  gccmoderate: 'GCCModerate',
  gcchigh: 'GCCHigh',
  dod: 'DoD',
};

export const getM365ChatEnvironmentFromAudience = (audience: Audience): M365ChatEnvironment => {
  const useOverride = featureGates.getBooleanFeatureGate('useM365ChatEnvironmentOverride', false);
  const overrideValue = featureGates.getStringFeatureGate('m365ChatEnvironmentOverride', '');
  if (useOverride && overrideValue) {
    const mapped = M365_CHAT_ENVIRONMENT_MAP[overrideValue.toLowerCase()];
    if (mapped) {
      return mapped;
    }
    TelemetryLogger.Instance.logError('M365ChatSettingsProviderError', new Error('Unhandled M365Chat environment override value'), {
      ErrorMethod: 'getM365ChatEnvironmentFromAudience',
      ConfigDataValue: overrideValue,
    });
  }

  switch (audience) {
    case 'Automation':
    case 'Development':
    case 'Dogfood':
    case 'Staging':
    case 'Local':
    case 'SyntheticTraffic':
      return 'SDF';
    case 'Preview':
    case 'Microsoft':
      return 'MSIT';
    case 'GCC':
      return 'GCCModerate';
    case 'GCC-High':
      return 'GCCHigh';
    case 'DoD':
      return 'DoD';
    case 'Production':
      return 'Prod';
    default: {
      const error = new Error(`Unhandled audience for M365Chat environment: '${audience}'`);
      TelemetryLogger.Instance.logError('M365ChatSettingsProviderError', error, {
        ErrorMethod: 'getM365ChatEnvironmentFromAudience',
        ConfigDataValue: audience,
      });
      throw error;
    }
  }
};

/**
 * Transforms EcsTeamSettings to a Record with string or boolean values
 * @param teamSettings The ECS team settings to transform
 * @returns A record with string or boolean values, or undefined if input is undefined
 */
export const transformEcsTeamSettings = (teamSettings: EcsTeamSettings | undefined): Record<string, string | boolean> | undefined => {
  if (!teamSettings) {
    return undefined;
  }

  const transformed: Record<string, string | boolean> = {};

  for (const [key, value] of Object.entries(teamSettings)) {
    if (typeof value === 'boolean') {
      transformed[key] = value;
    } else if (typeof value === 'string') {
      transformed[key] = value;
    } else if (typeof value === 'number') {
      transformed[key] = value.toString();
    } else if (value === null || value === undefined) {
      // skip null and undefined values
      continue;
    } else {
      // For any other type (objects, arrays, etc.), convert to string representation
      try {
        transformed[key] = JSON.stringify(value);
      } catch (error) {
        TelemetryLogger.Instance.logError('M365ChatSettingsProviderError', new Error('Error transforming ECS team setting to string'), { ErrorMethod: 'transformEcsTeamSettings', SettingKey: key });
      }
    }
  }

  return transformed;
};
