import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { changeGates } from './FeatureGates';
import { LoadStateTracker } from './loadStateTracker';

export interface TeardownCloseResult {
  scenariosClosed: number;
  rendersClosed: number;
}

/**
 * Force-close any open scenario + render trackers on teardown (page unload or error-recovery
 * reload), gated by `useUnloadScenarioForceClose`. MUST run before the sink shuts down so the
 * terminal Fluid/SDX markers are queued + flushed (a shut-down sink drops new events). Shared by
 * {@link installUnloadHandlers} and `errorRecovery`.
 */
export function closeOpenTrackersOnTeardown(reason: Error): TeardownCloseResult {
  const result: TeardownCloseResult = { scenariosClosed: 0, rendersClosed: 0 };
  if (!changeGates.getBooleanChangeGate('useUnloadScenarioForceClose')) {
    return result;
  }
  try {
    result.scenariosClosed = LoadStateTracker.forceCloseOpenScenarios(reason);
  } catch (e) {
    TelemetryLogger.Instance.logError('PageUnload', e, { ErrorMethod: 'forceCloseOpenScenarios' });
  }
  try {
    result.rendersClosed = LoadStateTracker.cancelOpenRenderTrackers(reason);
  } catch (e) {
    TelemetryLogger.Instance.logError('PageUnload', e, { ErrorMethod: 'cancelOpenRenderTrackers' });
  }
  return result;
}
