export declare type PromiseResolvers<T> = {
  promise: Promise<T>;
  resolve: (value: T | PromiseLike<T>) => void;
  reject: (error: unknown) => void;
};

export class PromiseCompat {
  static withResolvers<T>(): PromiseResolvers<T> {
    const PromiseClass = Promise as PromiseConstructor & {
      withResolvers?: <T>() => PromiseResolvers<T>;
    };
    if (typeof PromiseClass.withResolvers === 'function') {
      return PromiseClass.withResolvers<T>();
    } else {
      let resolve: PromiseResolvers<T>['resolve'] = () => void 0;
      let reject: PromiseResolvers<T>['reject'] = () => void 0;
      const promise = new Promise<T>((res, rej) => {
        resolve = res;
        reject = rej;
      });
      return {
        promise,
        resolve,
        reject,
      };
    }
  }
}

/**
 * Sentinel prefix used in timeout error messages from executeWithTimeout.
 * Used by callers to reliably identify timeout errors vs. other rejections.
 */
export const TIMEOUT_ERROR_SENTINEL = '[ExecuteWithTimeout]';

/**
 * Races a promise against a timeout. If the timeout fires first, rejects
 * with an error containing the operation name and timeout duration.
 *
 * The original promise is NOT cancelled — JavaScript does not support
 * promise cancellation. It may still resolve or reject after the timeout,
 * but the caller will have already moved on.
 *
 * @param operationName - Descriptive name for the operation (used in error messages and telemetry)
 * @param promise - The promise to race against the timeout
 * @param timeoutMs - Maximum time (ms) to wait before rejecting
 * @returns The resolved value of the original promise, or rejects with a timeout error
 *
 * @example
 * ```ts
 * const result = await executeWithTimeout(
 *   'loadComponent',
 *   fetchComponentFromCDN(),
 *   30000,
 * );
 * ```
 */
export const executeWithTimeout = <T>(
  operationName: string,
  promise: Promise<T>,
  timeoutMs: number,
): Promise<T> => {
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => setTimeout(() => {
      reject(new Error(`${TIMEOUT_ERROR_SENTINEL} ${operationName} timed out after ${timeoutMs}ms`));
    }, timeoutMs)),
  ]);
};
