import type { ProvideNamespaceLogger } from '@fluidx/1p-loop-types';
import { LoopDependencyContainer } from '@fluidx/injected-dependencies';
import type {
  Environment,
  ProvideInternationalizationContext,
  ProvideLoopCodeLoaderFactory,
  ProvideLoopTelemetrySink,
  ProvideSettingsProvider,
  ProvideTelemetryConfig,
  ProvideTheming,
  ProvideTokenProvider,
  ProvideUrlHandlerProvider,
  ProvideUserContext,
} from '@fluidx/loop-types';
import {
  CdnCodeLoaderFactory,
  LoopRegistrationId,
} from '@fluidx/loop-workspace-component';
import type {
  ProvideBizChatTokenProvider,
  ProvideCopilotConfigurationContext,
} from '@fluidx/loop-workspace-types';
import type { OfficeFluidLogger } from '@fluidx/telemetry';
import type { Locale } from '@fluidx/utilities';
import { LoopCodeLoaderBundlerFactoryProvider } from '@ms/office-web-host';
import type { HostAuthService } from '../../auth/HostAuthService';
import {
  ThemeProvider,
  createFrontendLoopSettingsProvider,
  createTelemetryConfigProvider,
  getInternationalizationContext,
  getOneNoteCopilotConfigurationContext,
} from '../../providers';
import {
  M365CHAT_APP_VERSION_SETTING_NAME,
  type M365ChatSettingsProvider,
} from '../../providers/M365ChatSettingsProvider';
import { OneNoteUrlHandlerProvider } from '../../providers/OneNoteUrlHandlerProvider';
import { HostLoopTelemetrySink } from '../../telemetry/HostLoopTelemetrySink';
import { TelemetryLogger } from '../../telemetry/TelemetryLogger';
import { featureGates } from '../../utils/FeatureGates';
import { HostAppSettingName, HostAppSettings } from '../../utils/HostAppSettings';
import type { UserEligibilityService } from '../userEligibilityService/UserEligibilityService';
import type { AppWorkspaceManager } from '../workspaceManager/AppWorkspaceManager';
import { getCopilotScenarioName } from './utils';
type WorkspaceComponentProviderTypes =
  & ProvideBizChatTokenProvider
  & ProvideCopilotConfigurationContext
  & ProvideInternationalizationContext
  & ProvideLoopCodeLoaderFactory
  & ProvideLoopTelemetrySink
  & ProvideNamespaceLogger
  & ProvideSettingsProvider
  & ProvideTelemetryConfig
  & ProvideTheming
  & ProvideTokenProvider
  & ProvideUrlHandlerProvider
  & ProvideUserContext;

export class DependencySynthesizerService {
  private dependencySynthesizer: LoopDependencyContainer<WorkspaceComponentProviderTypes> | undefined;

  public getDependencySynthesizer() {
    if (!this.dependencySynthesizer) {
      this.dependencySynthesizer =
        new LoopDependencyContainer<WorkspaceComponentProviderTypes>();
    }
    return this.dependencySynthesizer;
  }

  public async registerProviders(
    appWorkspaceManager: AppWorkspaceManager,
    authService: HostAuthService,
    environment: Environment,
    fluidLogger: OfficeFluidLogger,
    locale: Locale,
    m365ChatSettingsProvider: M365ChatSettingsProvider,
    userEligibilityService: UserEligibilityService,
  ) {
    const dependencySynthesizer = this.getDependencySynthesizer();
    dependencySynthesizer.register(
      'InternationalizationContext',
      getInternationalizationContext(locale),
    );
    dependencySynthesizer.register(
      'LoopCodeLoaderFactoryProvider',
      new LoopCodeLoaderBundlerFactoryProvider(
        new Map([[LoopRegistrationId, Promise.resolve(CdnCodeLoaderFactory)]]),
      ),
    );
    dependencySynthesizer.register(
      'LoopTelemetrySink',
      new HostLoopTelemetrySink(),
    );
    dependencySynthesizer.register('NamespaceLogger', fluidLogger);
    dependencySynthesizer.register(
      'SettingsProvider',
      createFrontendLoopSettingsProvider(
        environment,
        authService.getUserContext(),
      ),
    );
    dependencySynthesizer.register('Theming', new ThemeProvider());
    dependencySynthesizer.register('TokenProvider', authService);
    dependencySynthesizer.register('UserContext', authService.getUserContext());
    if (!authService.bizChatAuthService) {
      throw new Error('No BizChat token provider for dependency injection');
    }
    dependencySynthesizer.register('BizChatTokenProvider', authService.bizChatAuthService);
    dependencySynthesizer.register('TelemetryConfig', createTelemetryConfigProvider());

    const useOneNoteUrlHandlerProvider = featureGates.getBooleanFeatureGate('useOneNoteUrlHandlerProvider', false /* defaultValue */);
    if (useOneNoteUrlHandlerProvider) {
      dependencySynthesizer.register('UrlHandlerProvider', new OneNoteUrlHandlerProvider(appWorkspaceManager));
    }

    // Fetch M365 Chat settings
    const m365ChatFeatureSettings: Record<string, string | boolean> | undefined = await m365ChatSettingsProvider.getAllM365ChatFeatureSettings();
    const chatVersion = m365ChatFeatureSettings?.[M365CHAT_APP_VERSION_SETTING_NAME] ?? 'Unknown';
    TelemetryLogger.Instance.logEvent('M365ECSChatVersion', {
      ChatVersion: chatVersion
    });
    console.log('ECS Chat Version', chatVersion);
    const isMSA = authService.identityType === 'Consumer';
    const isCopilotProUser = HostAppSettings.getSetting(HostAppSettingName.IsCopilotPremiumIdentity, false);
    dependencySynthesizer.register(
      'CopilotConfigurationContext',
      getOneNoteCopilotConfigurationContext(
        getCopilotScenarioName(isMSA, isCopilotProUser),
        userEligibilityService,
        m365ChatFeatureSettings,
      ),
    );
    return dependencySynthesizer;
  }

  public unregisterProviders() {
    if (!this.dependencySynthesizer) {
      return;
    }
    this.dependencySynthesizer.unregister('CopilotConfigurationContext');
    this.dependencySynthesizer.unregister('InternationalizationContext');
    this.dependencySynthesizer.unregister('LoopCodeLoaderFactoryProvider');
    this.dependencySynthesizer.unregister('LoopTelemetrySink');
    this.dependencySynthesizer.unregister('NamespaceLogger');
    this.dependencySynthesizer.unregister('SettingsProvider');
    this.dependencySynthesizer.unregister('Theming');
    this.dependencySynthesizer.unregister('TokenProvider');
    this.dependencySynthesizer.unregister('UserContext');
    this.dependencySynthesizer.unregister('BizChatTokenProvider');
    this.dependencySynthesizer.unregister('TelemetryConfig');
    this.dependencySynthesizer.unregister('UrlHandlerProvider');

    this.dependencySynthesizer = undefined;
  }
}
