import type { AdditionalTrackerProps, HostActivityTracker } from '@ms/office-web-host';
import type { EventName } from '../telemetry/Events';
import type { TelemetryEventData } from '../telemetry/ITelemetryLogger';
import { OfficeTelemetrySinkWrapper } from '../telemetry/OfficeTelemetrySinkWrapper';
import type { TrackedActivity } from '../telemetry/TelemetryActivityTracker';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';

/**
 * Coarse state machine describing where the LWC load currently is.
 * Carried as the `LoadPhase` field on the `PageUnload` telemetry event and as `Phase`
 * on the LoadState scenario events so we can attribute incomplete loads to a stage.
 */
export type LoadPhase =
  | 'PreLoad'
  | 'SynthesizingDependencies'
  | 'LoadingComponent'
  | 'GettingView'
  | 'Rendering'
  | 'Idle';

/** How a registered scenario was closed, for the LoadState telemetry. */
export type ScenarioCloseReason = 'Success' | 'Failure';

/**
 * A scenarioTracker registered with the LoadStateTracker, paired with the `inViewport` flag the
 * load started with. `closed` makes closure idempotent: every closure path flips it, so the
 * underlying Fluid tracker is never double-closed (e.g., a deferred render-success callback firing
 * after the unload handler already force-closed it).
 *
 * `inViewport` is render-INTENT (= !IsUILessLoad, with the focus-driven forceRender override),
 * captured once at load start and emitted as the `InViewPort` field. In this single-window Win32
 * host it is a good proxy for "user is viewing the active window"; it is NOT a live visibility
 * measurement and does not track the window being minimized/occluded/reparented mid-load.
 */
export interface RegisteredScenario {
  readonly tracker: HostActivityTracker<AdditionalTrackerProps>;
  readonly inViewport: boolean;
  // ActivityId/ParentActivityId of the LoadLoopWorkspaceEndToEnd activity that owns THIS scenario,
  // captured at registration. Stored per-scenario (not module-level) so a later registration can't
  // overwrite an earlier scenario's correlation, and a deferred closure emits the right ids.
  readonly activityId?: number;
  readonly parentActivityId?: number;
  closed: boolean;
}

/**
 * Module-level state tracking the LWC load lifecycle so a teardown handler can attach diagnostic
 * context and force-close still-open scenario / render trackers. The scenarioTracker created inside
 * `loadLoopWorkspaceComponent` is closure-local; if that function never returns (webview killed
 * mid-`await`), the scenario stays Start-without-End. Registering trackers here lets the unload
 * handler close them.
 */
export class LoadStateTracker {
  private static readonly _scenarios = new Set<RegisteredScenario>();
  private static readonly _renderTrackers = new Set<TrackedActivity>();
  private static _phase: LoadPhase = 'PreLoad';
  private static readonly _pageStartMs = Date.now();
  private static _appInitialized = false;

  /**
   * Emit a LoadState event with the common diagnostic context (host ids are stamped centrally by
   * {@link TelemetryLogger}). Wrapped so telemetry never affects load-state correctness. Set
   * `priority` to escape the batched queue on teardown.
   */
  private static emit(eventName: EventName, data: TelemetryEventData, priority = false): void {
    try {
      const payload = { ...LoadStateTracker.commonFields(), ...data };
      if (priority) {
        TelemetryLogger.Instance.logPriorityEvent(eventName, payload);
      } else {
        TelemetryLogger.Instance.logEvent(eventName, payload);
      }
    } catch {
      // Telemetry must never break load-state tracking.
    }
  }

  private static commonFields(): TelemetryEventData {
    return {
      Phase: LoadStateTracker._phase,
      OpenScenarioCount: LoadStateTracker._scenarios.size,
      PageLifetimeMs: LoadStateTracker.getPageLifetimeMs(),
      IsAppInitialized: LoadStateTracker._appInitialized,
    };
  }

  /** Per-scenario correlation ids (ActivityId/ParentActivityId) for the owning load activity. */
  private static correlationFields(scenario: RegisteredScenario): TelemetryEventData {
    const fields: TelemetryEventData = {};
    if (scenario.activityId !== undefined) {
      fields.ActivityId = scenario.activityId;
    }
    if (scenario.parentActivityId !== undefined) {
      fields.ParentActivityId = scenario.parentActivityId;
    }
    return fields;
  }

  /**
   * Register a newly-started scenarioTracker so the unload handler can find it. Pass the owning
   * load activity ids (captured while synchronously inside the LoadLoopWorkspaceEndToEnd activity);
   * they are stored on the scenario so its later events correlate even if another load registers.
   */
  public static registerScenario(
    tracker: HostActivityTracker<AdditionalTrackerProps>,
    inViewport: boolean,
    activityId?: number,
    parentActivityId?: number,
  ): RegisteredScenario {
    const scenario: RegisteredScenario = { tracker, inViewport, activityId, parentActivityId, closed: false };
    LoadStateTracker._scenarios.add(scenario);
    LoadStateTracker.emit('LoadStateScenarioRegistered', {
      InViewPort: inViewport,
      ...LoadStateTracker.correlationFields(scenario),
    });
    return scenario;
  }

  /**
   * Remove a previously-registered scenario from the open set. Safe to call multiple times.
   * Prefer {@link setScenarioSuccess} / {@link setScenarioFailure} which also close the
   * underlying tracker and emit telemetry; this remains for bookkeeping-only callers.
   */
  public static unregisterScenario(scenario: RegisteredScenario): void {
    LoadStateTracker._scenarios.delete(scenario);
  }

  /**
   * Idempotently close a scenario as succeeded: `setSuccess` on the tracker, unregister, and
   * emit `LoadStateScenarioUnregistered`. No-ops if already closed.
   */
  public static setScenarioSuccess(
    scenario: RegisteredScenario,
    props: AdditionalTrackerProps,
  ): boolean {
    return LoadStateTracker.closeScenario(scenario, 'Success', () =>
      scenario.tracker.setSuccess(props),
    );
  }

  /**
   * Idempotently close a scenario as failed: `setFailure`, unregister, emit Unregistered. No-ops if
   * already closed — this prevents the missing-view path (closed inside `renderView`) from being
   * double-closed by the outer catch in `loadLoopWorkspaceComponent`.
   */
  public static setScenarioFailure(
    scenario: RegisteredScenario,
    error: Error,
    props: AdditionalTrackerProps,
  ): boolean {
    return LoadStateTracker.closeScenario(scenario, 'Failure', () =>
      scenario.tracker.setFailure(error, props),
    );
  }

  /**
   * Shared idempotent closure. Close-first: only mark closed / unregister / emit AFTER the terminal
   * tracker call succeeds; if it throws, log and leave the scenario open (retryable). The UI-less
   * (`inViewport=false`) success proof is emitted via the priority path with a queue snapshot so it
   * survives an unclean background teardown even when the batched Fluid end-marker does not.
   */
  private static closeScenario(
    scenario: RegisteredScenario,
    reason: ScenarioCloseReason,
    closeFn: () => void,
  ): boolean {
    if (scenario.closed) {
      return false;
    }
    try {
      closeFn();
    } catch (e) {
      try {
        TelemetryLogger.Instance.logError('LoadStateScenarioUnregistered', e, {
          ErrorMethod: 'closeScenario',
          Reason: reason,
          InViewPort: scenario.inViewport,
        });
      } catch {
        // Telemetry must never throw out of closure.
      }
      return false;
    }
    scenario.closed = true;
    LoadStateTracker._scenarios.delete(scenario);

    const data: TelemetryEventData = {
      Reason: reason,
      InViewPort: scenario.inViewport,
      ...LoadStateTracker.correlationFields(scenario),
    };
    const useCompletionPriority = reason === 'Success' && !scenario.inViewport;
    if (useCompletionPriority) {
      try {
        const sink = OfficeTelemetrySinkWrapper.Instance;
        data.QueueLength = sink.queueLength;
        data.DroppedEventCount = sink.droppedEventCount;
      } catch {
        // queue snapshot is best-effort
      }
    }
    LoadStateTracker.emit('LoadStateScenarioUnregistered', data, useCompletionPriority);
    return true;
  }

  public static setPhase(phase: LoadPhase): void {
    LoadStateTracker._phase = phase;
  }

  public static getPhase(): LoadPhase {
    return LoadStateTracker._phase;
  }

  public static getPageLifetimeMs(): number {
    return Date.now() - LoadStateTracker._pageStartMs;
  }

  public static getOpenScenarioCount(): number {
    return LoadStateTracker._scenarios.size;
  }

  public static markAppInitialized(): void {
    LoadStateTracker._appInitialized = true;
  }

  public static isAppInitialized(): boolean {
    return LoadStateTracker._appInitialized;
  }

  /** Register a render end-to-end tracker so the unload handler can cancel it if the page
   * is torn down before the render's deferred paint callback closes it. */
  public static registerRenderTracker(tracker: TrackedActivity): void {
    LoadStateTracker._renderTrackers.add(tracker);
  }

  /** Remove a render tracker once it has closed normally. Safe to call multiple times. */
  public static unregisterRenderTracker(tracker: TrackedActivity): void {
    LoadStateTracker._renderTrackers.delete(tracker);
  }

  /**
   * Cancel every still-open render tracker on tear-down (Cancelled, via the priority path so
   * the proof survives teardown). `TrackedActivity.cancel` is idempotent. Returns the count.
   */
  public static cancelOpenRenderTrackers(reason: Error): number {
    const snapshot = Array.from(LoadStateTracker._renderTrackers);
    LoadStateTracker._renderTrackers.clear();
    let closed = 0;
    for (const tracker of snapshot) {
      try {
        tracker.cancel({ Reason: reason.message }, /* priority */ true);
        closed++;
      } catch {
        // One bad tracker shouldn't break the rest.
      }
    }
    return closed;
  }

  /**
   * Force-close every still-open scenario on teardown as Cancelled (D2: an unload mid-load is an
   * expected abort, not a failure). `cancel()` still emits a terminal `Activity_LoadEndToEnd` so the
   * monitor stops seeing Start-without-End; emits `LoadStateScenarioForceClosed` via the priority
   * path. A tracker that throws is dropped from the registry so it can't inflate later reads.
   *
   * @returns the number of scenarios closed.
   */
  public static forceCloseOpenScenarios(reason: Error): number {
    const snapshot = Array.from(LoadStateTracker._scenarios);
    let closed = 0;
    for (const scenario of snapshot) {
      if (scenario.closed) {
        continue;
      }
      try {
        scenario.tracker.cancel();
      } catch (e) {
        // The terminal cancel threw. Mark the scenario closed (so a stale closure-local reference —
        // e.g. a deferred paint callback — can't later record a misleading success) and drop it from
        // the registry so it can't inflate later OpenScenarioCount reads.
        scenario.closed = true;
        LoadStateTracker._scenarios.delete(scenario);
        try {
          TelemetryLogger.Instance.logError('LoadStateScenarioForceClosed', e, {
            ErrorMethod: 'forceCloseOpenScenarios',
            InViewPort: scenario.inViewport,
          });
        } catch {
          // Telemetry must never throw out of teardown.
        }
        continue;
      }
      scenario.closed = true;
      LoadStateTracker._scenarios.delete(scenario);
      LoadStateTracker.emit(
        'LoadStateScenarioForceClosed',
        {
          Reason: reason.message,
          InViewPort: scenario.inViewport,
          ClosureMode: 'Cancelled',
          ...LoadStateTracker.correlationFields(scenario),
        },
        /* priority */ true,
      );
      closed++;
    }
    return closed;
  }

  /**
   * Test-only: reset all module-level state. Call sites are limited to test suites that need
   * a clean slate between cases.
   */
  public static __resetForTests(): void {
    LoadStateTracker._scenarios.clear();
    LoadStateTracker._renderTrackers.clear();
    LoadStateTracker._phase = 'PreLoad';
    LoadStateTracker._appInitialized = false;
  }
}
