import type { Environment, HTMLView, Provider } from '@fluidx/loop-types';
import type { NavigationParams, WorkspaceAndPageManagerEvents } from '@fluidx/loop-workspace-types';
import type { OfficeFluidLogger } from '@fluidx/telemetry';
import type { Locale } from '@fluidx/utilities';
import type { HostAuthService } from '../auth/HostAuthService';
import type { M365ChatSettingsProvider } from '../providers/M365ChatSettingsProvider';
import type { DependencySynthesizerService } from '../service/dependencySynthesizer/DependencySynthesizerService';
import type { UserEligibilityService } from '../service/userEligibilityService/UserEligibilityService';
import type { AppWorkspaceManager } from '../service/workspaceManager/AppWorkspaceManager';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { toError } from '../utils/ErrorUtils';
import { HostAppSettings } from '../utils/HostAppSettings';
import { attemptErrorRecoveryReload, clearErrorReloadCount } from '../utils/errorRecovery';
import type { ActionProviderTypes } from '../utils/loopComponent';
import { loadLoopWorkspaceComponent } from '../utils/loopComponent';

/** Structural ref so this module stays React-agnostic and unit-testable with plain objects. */
interface MutableRefLike<T> {
  current: T;
}

export interface LoadAndWireLoopComponentContext {
  appWorkspaceManager: AppWorkspaceManager;
  authService: HostAuthService;
  dependencySynthesizerService: DependencySynthesizerService;
  environment: Environment;
  locale: Locale;
  loadNavParams: NavigationParams;
  m365ChatSettingsProvider: M365ChatSettingsProvider;
  userEligibilityService: UserEligibilityService;
  /** The (non-null) render target element. */
  renderTarget: HTMLElement;
  /**
   * One-shot latch: set before the first await so a re-fired effect can't start a second,
   * overlapping load. Load is intentionally one-shot per page (no unload today; failure recovery
   * is a full page reload, which yields a fresh component and a fresh latch).
   */
  hasInitiatedLoadRef: MutableRefLike<boolean>;
  loopComponentRef: MutableRefLike<Provider<ActionProviderTypes> | undefined>;
  fluidLoggerRef: MutableRefLike<OfficeFluidLogger | undefined>;
  viewRef: MutableRefLike<HTMLView | undefined>;
  postLoadCheck: (isUILessLoad: boolean) => void;
  workspaceListChangedHandler: (
    data: WorkspaceAndPageManagerEvents['workspaceListChanged'],
  ) => void;
}

/**
 * Loads the Loop workspace component and wires it into the AppWorkspaceManager.
 *
 * One-shot: latches hasInitiatedLoadRef before any await and no-ops on re-entry, so an effect
 * re-fire can't start an overlapping load (which would duplicate telemetry/subscriptions and let
 * a concurrent success clear a concurrent failure's reload counter).
 *
 * The reload counter is cleared ONLY after the full load + wiring succeeds (end of try). Clearing
 * earlier lets a later-step failure reset it every attempt, so attemptErrorRecoveryReload never
 * reaches its bound — an unbounded reload loop. The success boundary is "load + wiring", not paint:
 * UI-less paint is deferred to postLoadCheck's nav handler, whose failures don't route through
 * attemptErrorRecoveryReload. If that changes, clear only after the deferred render succeeds.
 */
export const loadAndWireLoopComponent = async (
  ctx: LoadAndWireLoopComponentContext,
): Promise<void> => {
  const {
    appWorkspaceManager,
    authService,
    dependencySynthesizerService,
    environment,
    locale,
    loadNavParams,
    m365ChatSettingsProvider,
    userEligibilityService,
    renderTarget,
    hasInitiatedLoadRef,
    loopComponentRef,
    fluidLoggerRef,
    viewRef,
    postLoadCheck,
    workspaceListChangedHandler,
  } = ctx;

  // Latch the one-shot guard before the first await so a concurrent re-entry bails here.
  if (hasInitiatedLoadRef.current) {
    return;
  }
  hasInitiatedLoadRef.current = true;

  try {
    const isUILessLoad = HostAppSettings.isUILessLoad();
    const {
      loopComponent, fluidLogger, view
    } =
      await loadLoopWorkspaceComponent(
        appWorkspaceManager,
        authService,
        dependencySynthesizerService,
        environment,
        locale,
        loadNavParams,
        !isUILessLoad /* shouldRender */,
        m365ChatSettingsProvider,
        userEligibilityService,
        renderTarget,
      );
    // UI-less: registers the deferred-render handler. Safe before the ref assignments below —
    // setOnNavigationEvent only stores the handler (no synchronous/buffered invoke) and there is
    // no await before those assignments, so renderOnNavigation (which runs on a later navigate
    // emit) always sees the refs set. If that changes (buffered replay, or an await added before
    // the refs), move the assignments above this call.
    postLoadCheck(isUILessLoad);
    // Stash refs for later use and cleanup.
    loopComponentRef.current = loopComponent;
    fluidLoggerRef.current = fluidLogger;
    viewRef.current = view;
    const workspaceAndPageManager = loopComponent.WorkspaceAndPageManager;
    if (!workspaceAndPageManager) {
      throw new Error('WorkspaceAndPageManager not provided by Loop component');
    }
    appWorkspaceManager.setWorkspaceAndPageManager(workspaceAndPageManager);
    // One-time initial load; later changes arrive via the events subscribed below.
    await appWorkspaceManager.appLoadDataModels();

    // Subscribe to manager events individually (currently only workspaceListChanged).
    loopComponentRef.current.WorkspaceAndPageManager?.on(
      'workspaceListChanged',
      workspaceListChangedHandler,
    );

    const workspaceNavigationHandler = loopComponent.WorkspaceNavigationHandler;
    if (!workspaceNavigationHandler) {
      throw new Error('WorkspaceNavigationHandler not provided by Loop component');
    }
    appWorkspaceManager.setWorkspaceNavigationHandler(workspaceNavigationHandler);
    loopComponentRef.current.WorkspaceNavigationHandler?.on(
      'navigation',
      data => {
        void appWorkspaceManager
          .getWorkspaceManager()
          .onComponentNavigationEvent(data);
      },
    );
    // Seed the active-page identity from the launch route. The launch route is fed straight into
    // the LWC (it never flows through NavigateTo), so activePageParams is otherwise unset; seeding
    // it lets canNavigate dedupe a buffered same-page replay and avoid the Loop same-page bug.
    if (loadNavParams.route === 'page' && loadNavParams.mfsPodId) {
      appWorkspaceManager
        .getWorkspaceManager()
        .setActivePageParams(loadNavParams.docUrl, loadNavParams.mfsPodId);
    }
    // Replay any navigation the host requested before the handler was attached. Done AFTER the
    // 'navigation' subscription above so a replayed nav echoes back to the client like a normal one.
    appWorkspaceManager.flushPendingNavigation();
    // Load + wiring succeeded — clear the counter only now. Clearing earlier reintroduces the
    // unbounded reload loop (see doc comment).
    clearErrorReloadCount();
  } catch (error) {
    TelemetryLogger.Instance.logError('LoadLoopWorkspaceComponent', toError(error), {
      ErrorMethod: 'HostedWorkspaceUI.renderLoopComponent',
    });
    // Attempt recovery via page reload (bounded by max retries)
    attemptErrorRecoveryReload(error);
  }
};
