import { TelemetryLogger } from '../telemetry/TelemetryLogger';

export type CloudType =
  | 'UNKNOWN'
  | 'Public'
  | 'Public1CDN'
  | 'GCCM'
  | 'GCCH'
  | 'DoD';

export type SovereignCloudType = Exclude<CloudType, 'Public' | 'UNKNOWN' | 'Public1CDN'>;

/**
 * Mapping of known hostnames to their corresponding CloudType.
 * Add or update entries here to support new cloud environments.
 */
const DOMAIN_TO_CLOUD_TYPE: Record<string, CloudType> = {
  'fa000000174.resources.office.net': 'Public',
  'fa000000174.mro1cdnstorage.public.cdn.office.net': 'Public',
  'fa000000174.officeapps.live.com': 'Public',
  'fa000000174.mro1cdnstorage.public.onecdn.static.microsoft': 'Public1CDN',
  'fa000000174.mro1cdnstorage.gcc.cdn.office.net': 'GCCM',
  'fa000000174.mro1cdnstorage.gcch.cdn.office.net': 'GCCH',
  'fa000000174.mro1cdnstorage.dod.cdn.office.net': 'DoD',
};

export let cachedCloudType: CloudType | undefined;

/**
 * Returns the detected CloudType for the current window location.
 * Uses a cached value for efficiency.
 */
export function getCloudType(): CloudType {
  if (!cachedCloudType) {
    cachedCloudType = detectCloudType();
  }
  return cachedCloudType;
}

export function isSovereignCloud(): boolean {
  const cloudType = getCloudType();
  return cloudType !== 'Public' && cloudType !== 'Public1CDN' && cloudType !== 'UNKNOWN';
}

/**
 * Determines the CloudType based on the window's hostname.
 * Returns 'UNKNOWN' if the hostname is not recognized.
 */
function detectCloudType(): CloudType {
  try {
    const hostname = new URL(window.location.href).hostname.toLowerCase();
    const mapped = DOMAIN_TO_CLOUD_TYPE[hostname];
    if (!mapped) {
      throw new Error('Failed to map hostname to cloud type');
    }
    console.log('Detected mapped cloud type:', mapped);
    return mapped;
  } catch (error) {
    const lastError = new Error('Failed to map hostname to cloud type');
    TelemetryLogger.Instance.logError('UnhandledConfigError', lastError, {
      ErrorMethod: 'detectCloudType',
      ConfigDataValue: '',
      ConfigDataExpectedType: 'Hostname',
    });
    return 'UNKNOWN';
  }
}

export const resetCloudCache = () => {
  cachedCloudType = undefined;
};
