import type { EventName } from './Events';
import type { TelemetryEventData, TelemetryEventDataTypes } from './ITelemetryLogger';
import { TelemetryLogger } from './TelemetryLogger';

/**
 * Options for configuring activity tracking behavior.
 */
export interface ActivityTrackerOptions {
  /**
   * If set, a warning event is emitted when the activity exceeds this duration (ms)
   * without completing. The activity is NOT interrupted — it continues running.
   * Useful for detecting stalls in async operations (e.g., render hangs).
   */
  stallThresholdMs?: number;
}

// Simple auto-incrementing ID for activity correlation.
// Provides unique IDs within a session (resets on page reload, which is fine).
let nextActivityId = 1;

// Stack of currently executing activity IDs for parent-child correlation.
// Uses a simple array-based stack since JS is single-threaded for synchronous entry.
const activityStack: number[] = [];

export class TelemetryActivityTracker {
  private telemetryData: TelemetryEventData = {};
  private readonly activityName: EventName;
  public readonly activityId: number;
  public readonly parentActivityId: number | undefined;

  constructor(activityName: EventName) {
    this.activityName = activityName;
    this.activityId = nextActivityId++;
    this.parentActivityId = activityStack.length > 0
      ? activityStack[activityStack.length - 1]
      : undefined;
  }

  /**
   * Emits a completion event with Outcome: 'Success'.
   * Duration is always included (set by runActivity before calling this).
   */
  private finishWithSuccess() {
    TelemetryLogger.Instance.logEvent(
      this.activityName,
      {
        ...this.getCorrelationData(),
        Outcome: 'Success',
        Phase: 'End',
        ...this.telemetryData,
      }
    );
  }

  /**
   * Emits a completion event with Outcome: 'Failure'.
   * Duration is always included (set by runActivity before calling this).
   */
  private finishWithFailure(error?: Error | unknown) {
    TelemetryLogger.Instance.logError(
      this.activityName,
      error,
      {
        ...this.getCorrelationData(),
        Outcome: 'Failure',
        Phase: 'End',
        ...this.telemetryData,
      }
    );
  }

  /**
   * Returns correlation fields (ActivityId, ParentActivityId) for this activity.
   */
  private getCorrelationData(): TelemetryEventData {
    const data: TelemetryEventData = {
      ActivityId: this.activityId,
    };
    if (this.parentActivityId !== undefined) {
      data.ParentActivityId = this.parentActivityId;
    }
    return data;
  }

  /**
   * Attach custom data to this activity's telemetry event.
   * Data is included in both success and failure events.
   */
  public addData(key: string, value: TelemetryEventDataTypes) {
    this.telemetryData[key] = value;
  }

  /**
   * Wraps an async operation with full telemetry lifecycle:
   *
   * 1. **Start event** — emitted immediately (Phase: 'Start') so hangs are detectable
   *    as "started but never completed"
   * 2. **Stall warning** — if `options.stallThresholdMs` is set, a warning is emitted
   *    when the threshold is exceeded without completion (Phase: 'Stall')
   * 3. **End event** — emitted on completion with Outcome ('Success' | 'Failure'),
   *    Duration (ms), correlation IDs (ActivityId, ParentActivityId), and any custom data
   *
   * All events share the same ActivityId for correlation. Nested activities
   * automatically get a ParentActivityId linking them to the outer activity.
   */
  public static async runActivity<T>(
    activityName: EventName,
    activity: (tracker: TelemetryActivityTracker) => Promise<T>,
    options?: ActivityTrackerOptions,
  ): Promise<T> {
    const tracker = new TelemetryActivityTracker(activityName);
    const startTime = Date.now();

    // Emit start event so hangs are detectable via "Start with no matching End"
    TelemetryLogger.Instance.logEvent(activityName, {
      ...tracker.getCorrelationData(),
      Phase: 'Start',
    });

    // Optional stall detection — emits a warning without interrupting the activity
    let stallTimer: ReturnType<typeof setTimeout> | undefined;
    if (options?.stallThresholdMs) {
      stallTimer = setTimeout(() => {
        TelemetryLogger.Instance.logError(
          activityName,
          new Error(`Activity '${activityName}' stalled after ${options.stallThresholdMs}ms`),
          {
            ...tracker.getCorrelationData(),
            Phase: 'Stall',
            Duration: Date.now() - startTime,
            ...tracker.telemetryData,
          }
        );
      }, options.stallThresholdMs);
    }

    // Push onto activity stack for parent-child correlation in nested activities
    activityStack.push(tracker.activityId);

    try {
      const result = await activity(tracker);
      const duration = Date.now() - startTime;
      tracker.addData('Duration', duration);
      tracker.finishWithSuccess();
      return result;
    } catch (error) {
      const duration = Date.now() - startTime;
      tracker.addData('Duration', duration);
      tracker.finishWithFailure(error);
      throw error;
    } finally {
      activityStack.pop();
      if (stallTimer !== undefined) {
        clearTimeout(stallTimer);
      }
    }
  }

  /**
   * Start an activity with an EXPLICIT lifecycle (Start emitted now; caller later calls
   * success / failure / cancel). Use when completion happens in a deferred callback rather than an
   * awaited function (e.g., a render-to-paint tracker closing inside requestAnimationFrame). Unlike
   * {@link runActivity}, does NOT push the global activity stack — the parent is passed explicitly.
   */
  public static startTracked(
    activityName: EventName,
    options?: StartTrackedOptions,
  ): TrackedActivity {
    return new TrackedActivity(activityName, options);
  }
}

/**
 * Options for {@link TelemetryActivityTracker.startTracked}.
 */
export interface StartTrackedOptions {
  /** Explicit parent ActivityId (this tracker does not read the global activity stack). */
  parentActivityId?: number;
  /** If set, a Stall warning is emitted when this threshold elapses before completion. */
  stallThresholdMs?: number;
}

/**
 * An activity with an explicit, idempotent lifecycle. Emits a Start event on construction
 * and exactly one terminal event (Success / Failure / Cancelled) on the first finish call.
 */
export class TrackedActivity {
  private readonly activityName: EventName;
  public readonly activityId: number;
  public readonly parentActivityId: number | undefined;
  private readonly startTime: number;
  private telemetryData: TelemetryEventData = {};
  private stallTimer: ReturnType<typeof setTimeout> | undefined;
  private finished = false;

  constructor(activityName: EventName, options?: StartTrackedOptions) {
    this.activityName = activityName;
    this.activityId = nextActivityId++;
    this.parentActivityId = options?.parentActivityId;
    this.startTime = Date.now();

    TelemetryLogger.Instance.logEvent(activityName, {
      ...this.getCorrelationData(),
      Phase: 'Start',
    });

    if (options?.stallThresholdMs) {
      const stallThresholdMs = options.stallThresholdMs;
      this.stallTimer = setTimeout(() => {
        if (this.finished) {
          return;
        }
        TelemetryLogger.Instance.logError(
          activityName,
          new Error(`Activity '${activityName}' stalled after ${stallThresholdMs}ms`),
          {
            ...this.getCorrelationData(),
            Phase: 'Stall',
            Duration: Date.now() - this.startTime,
            ...this.telemetryData,
          },
        );
      }, stallThresholdMs);
    }
  }

  /** Attach custom data included in the terminal event. */
  public addData(key: string, value: TelemetryEventDataTypes): void {
    this.telemetryData[key] = value;
  }

  /** Emit End with Outcome 'Success' (idempotent — first finish wins). */
  public success(data?: TelemetryEventData): void {
    this.finish('Success', undefined, data);
  }

  /** Emit End with Outcome 'Failure' (idempotent). */
  public failure(error: Error | unknown, data?: TelemetryEventData): void {
    this.finish('Failure', error, data);
  }

  /** Emit End with Outcome 'Cancelled' (idempotent) — for expected aborts (e.g., unload).
   * Pass priority=true to emit via the priority telemetry path (escapes teardown). */
  public cancel(data?: TelemetryEventData, priority = false): void {
    this.finish('Cancelled', undefined, data, priority);
  }

  private finish(
    outcome: 'Success' | 'Failure' | 'Cancelled',
    error: Error | unknown | undefined,
    data?: TelemetryEventData,
    priority = false,
  ): void {
    if (this.finished) {
      return;
    }
    this.finished = true;
    this.clearStallTimer();

    const payload: TelemetryEventData = {
      ...this.getCorrelationData(),
      Outcome: outcome,
      Phase: 'End',
      Duration: Date.now() - this.startTime,
      ...this.telemetryData,
      ...data,
    };

    if (outcome === 'Failure') {
      TelemetryLogger.Instance.logError(this.activityName, error, payload);
    } else if (priority) {
      TelemetryLogger.Instance.logPriorityEvent(this.activityName, payload);
    } else {
      TelemetryLogger.Instance.logEvent(this.activityName, payload);
    }
  }

  private clearStallTimer(): void {
    if (this.stallTimer !== undefined) {
      clearTimeout(this.stallTimer);
      this.stallTimer = undefined;
    }
  }

  private getCorrelationData(): TelemetryEventData {
    const data: TelemetryEventData = { ActivityId: this.activityId };
    if (this.parentActivityId !== undefined) {
      data.ParentActivityId = this.parentActivityId;
    }
    return data;
  }
}
