import type { Disposable } from '@fluidx/loop-types';
import type {
  CopilotConfigurationContext,
  ScenarioNames,
} from '@fluidx/loop-workspace-types';
import type { UserEligibilityService } from '../service/userEligibilityService/UserEligibilityService';

export const getOneNoteCopilotConfigurationContext = (
  scenarioName: ScenarioNames,
  userEligibilityService: UserEligibilityService,
  m365ChatFeatureSettings?: Record<string, string | boolean>,
): CopilotConfigurationContext & Disposable => {
  return {
    get CopilotConfigurationContext(): CopilotConfigurationContext {
      return this;
    },
    get Disposable(): Disposable {
      return this;
    },
    dispose() {
      return;
    },
    scenarioName,
    sourceName: 'OneNoteCopilotNotebook',
    bizChatFeedbackClientName: 'NotebooksOneNoteWin32',
    m365ChatFeatureSettings,
    eligibilityInformation: userEligibilityService.getUserEligibilityInformation(),
  };
};
