import { v4 as uuidv4 } from 'uuid';
import { TelemetryLogger } from '../telemetry/TelemetryLogger';
import { getCloudType } from '../utils/Cloud';
import { changeGates } from '../utils/FeatureGates';
import { retryWithBackoff } from '../utils/retry';
import {
  getResourceForTokenType,
  getUserAccountType,
} from './HostAuthServiceUtils';
import type { Identity } from './HostAuthServiceUtils';
import { type TokenType } from './endpoints';
import type { MappedError } from './utils';
import {
  exponentialBackoffDelay,
  getAuthAttemptLimit,
  hasDefaultScopeSuffix,
  isRetryableNestedAppAuthError,
  toError,
} from './utils';

export interface NAATokenRequestOptions {
  resourceUri?: string;
  tokenType?: TokenType;
  appendDefaultScope?: boolean;
  forceRefresh?: boolean;
  claims?: string;
}

export class NestedAppAuthService {
  private tokenPromiseCache = new Map<string, Promise<string>>();
  private appId: string;
  private redirectUri: string;
  private identity: Identity;

  constructor(appId: string, redirectUri: string, identity: Identity) {
    this.appId = appId;
    this.redirectUri = redirectUri;
    this.identity = identity;
  }

  private async LoadNestedAppAuthModule(): Promise<void> {
    const attemptLimit = getAuthAttemptLimit();
    await retryWithBackoff<void, MappedError>(
      async () => {
        await OfficeFirstPartyAuth.NestedAppAuth.load(this.appId, this.redirectUri);
      },
      {
        maxAttempts: attemptLimit,
        isRetryable: isRetryableNestedAppAuthError,
        isRetryEnabled: () => changeGates.getBooleanChangeGate('useAuthRetry'),
        backoffDelay: exponentialBackoffDelay,
        mapError: toError,
        exhaustedError: 'Office FirstParty Nested App Auth load retry limit exceeded',
        nonRetryableError: 'Office FirstParty Nested App Auth load failed',
        onAttemptError: (lastError, attemptCount) => {
          TelemetryLogger.Instance.logError('AuthError', lastError, {
            ErrorMethod: 'NAA.load',
            ErrorCode: lastError.code,
            ErrorMessage: lastError.message,
            AuthAppId: this.appId,
            FetchAttemptCount: attemptCount,
            FetchAttemptLimit: attemptLimit,
          });
        },
      },
    );
  }

  public async getToken(options: NAATokenRequestOptions): Promise<string> {
    const {
      tokenType = 'UNKNOWN',
      appendDefaultScope = true,
      forceRefresh = false,
      claims: callerClaims,
    } = options;

    // Resolve resourceUri from tokenType if not provided
    let { resourceUri } = options;
    if (!resourceUri) {
      if (tokenType === 'UNKNOWN') {
        throw new Error('Either resourceUri or a known tokenType must be provided');
      }
      resourceUri = getResourceForTokenType(tokenType, getUserAccountType(this.identity), getCloudType());
      if (!resourceUri) {
        const error = new Error('Unsupported token type');
        TelemetryLogger.Instance.logError('AuthError', error, {
          AuthAppId: this.appId,
          ErrorMethod: 'getToken',
          TokenType: tokenType,
        });
        throw new Error(`Unsupported NAA token type: ${tokenType}`);
      }
    }

    // At this point resourceUri is guaranteed to be defined (resolved above or thrown)
    const resolvedResourceUri = resourceUri;

    const cacheKey = resolvedResourceUri;
    const cachedPromise = this.tokenPromiseCache.get(cacheKey);
    if (cachedPromise && !forceRefresh && !callerClaims) {
      return cachedPromise;
    }

    const startTime = Date.now();
    const attemptLimit = getAuthAttemptLimit();
    const tokenPromise = (async () => {
      return retryWithBackoff<string, MappedError>(
        async (attemptCount) => {
          await this.LoadNestedAppAuthModule();

          const correlationId = uuidv4();
          const scopes = this.getScopes(resolvedResourceUri, appendDefaultScope);

          const shouldForceRefresh = forceRefresh || attemptCount > 1;
          const useForceRefreshClaims = changeGates.getBooleanChangeGate('useForceRefreshClaims');
          const claims = callerClaims
            ?? (useForceRefreshClaims && shouldForceRefresh ? '{"access_token":{"nbf":{"essential":true}}}' : undefined);

          const authResult = await OfficeFirstPartyAuth.NestedAppAuth.getAccessToken({
            clientId: this.appId,
            scopes,
            claims,
            popup: OfficeFirstPartyAuth.NestedAppAuth.PopupOptions.None,
            correlationId,
            redirectUri: this.redirectUri,
          });

          const duration = Date.now() - startTime;
          TelemetryLogger.Instance.logEvent('NAATokenAcquired', {
            AuthAppId: this.appId,
            TokenType: tokenType,
            Duration: duration,
            TokenForceRefresh: shouldForceRefresh,
            FetchAttemptCount: attemptCount,
            FetchAttemptLimit: attemptLimit,
          });

          return authResult.accessToken;
        },
        {
          maxAttempts: attemptLimit,
          isRetryable: isRetryableNestedAppAuthError,
          isRetryEnabled: () => changeGates.getBooleanChangeGate('useAuthRetry'),
          backoffDelay: exponentialBackoffDelay,
          mapError: toError,
          exhaustedError: 'Token acquisition retry limit exceeded',
          onAttemptError: (lastError, attemptCount) => {
            TelemetryLogger.Instance.logError('AuthError', lastError, {
              ErrorMethod: 'NAA.getAccessToken',
              ErrorCode: lastError.code,
              ErrorMessage: lastError.message,
              AuthAppId: this.appId,
              TokenType: tokenType,
              FetchAttemptCount: attemptCount,
              FetchAttemptLimit: attemptLimit,
            });
          },
        },
      );
    })()
      .finally(() => {
        this.tokenPromiseCache.delete(cacheKey);
      });

    this.tokenPromiseCache.set(cacheKey, tokenPromise);
    return tokenPromise;
  }

  public clearCache(): void {
    this.tokenPromiseCache.clear();
  }

  public setIdentity(identity: Identity): void {
    this.identity = identity;
  }

  private getScopes(resourceUri: string, appendDefaultScope: boolean): string[] {
    if (!appendDefaultScope) {
      return [resourceUri];
    }
    const normalized = resourceUri.replace(/\/+$/, '');
    return [hasDefaultScopeSuffix(normalized) ? normalized : `${normalized}/.default`];
  }
}
