// check if error is an object and has a message property
export const hasMessageProperty = (
  error: unknown,
): error is { message: string } => {
  return (
    typeof error === 'object' &&
    error !== null &&
    'message' in error &&
    typeof (error as { message: unknown }).message === 'string'
  );
};

export class MappedError extends Error {
  public readonly code: number | string;

  constructor(message: string, code: number | string = '', mapErrorString = true) {
    super(mapErrorString ? getMappedErrorStringMessage(message) : message);
    this.name = 'MappedError';
    this.code = code;
    Object.setPrototypeOf(this, MappedError.prototype);
  }
}

export class NAAError extends MappedError {
  public readonly code: number;
  constructor(code: number) {
    super('', code);
    this.name = 'NAAError';
    this.code = code;
    this.message = getNAAErrorMessage(code);
    Object.setPrototypeOf(this, NAAError.prototype);
  }
}

export class SSOError extends MappedError {
  public readonly code: string;
  constructor(message = '', code = '') {
    super(message, code);
    this.name = 'SSOError';
    this.code = code;
    this.message = getSSOErrorMessage(code || message);
    Object.setPrototypeOf(this, SSOError.prototype);
  }
}

/**
 * Checks if a raw error object is a NestedAppAuth error shape from OfficeFirstPartyAuth.
 * This is intentionally not exported — it exists only to classify raw API errors in toError().
 */
const isRawNestedAppAuthError = (error: unknown): error is OfficeFirstPartyAuth.NestedAppAuth.AuthError => {
  if (typeof error !== 'object' || error === null) {
    return false;
  }
  return 'code' in error && typeof (error as Record<string, unknown>).code === 'number' && !('accessToken' in error);
};

/**
 * Checks if a raw error object is an SSO auth error shape from OfficeFirstPartyAuth.
 *
 * The native SSO side rejects with either:
 *   (a) the full AuthResult shape — `{ accessToken, code, message, tokenIdenityType }` —
 *       where `accessToken` is empty on error, OR
 *   (b) a stripped-down object — `{ code, message }` — with no `accessToken` field.
 *
 * Earlier versions of this check required (a) by looking for `accessToken in error`.
 * In practice the native code overwhelmingly produces (b), which meant ~99% of SSO
 * failures fell through to `new MappedError('Unknown')` and showed up in telemetry
 * as `Unmapped+Error` with their actual `code` thrown away.
 *
 * We distinguish SSO from NAA by code type: NAA uses numeric codes (see
 * {@link isRawNestedAppAuthError}), SSO uses string codes. Any object with a
 * non-empty string `code` is treated as an SSO error. As a fallback, the original
 * AuthResult shape (accessToken slot + message, no code) is still recognised.
 *
 * Intentionally not exported — used only by `toError()` to classify raw API errors.
 */
const isRawSSOAuthError = (error: unknown): error is OfficeFirstPartyAuth.AuthResult => {
  if (typeof error !== 'object' || error === null) {
    return false;
  }
  const errorRecord = error as Record<string, unknown>;

  // SSO errors are distinguished from NAA by their code being a string (NAA's code
  // is numeric and is matched earlier in toError via isRawNestedAppAuthError).
  if ('code' in errorRecord && typeof errorRecord.code === 'string' && errorRecord.code.trim() !== '') {
    return true;
  }

  // Fallback: AuthResult shape with the accessToken slot and a string message but
  // no usable code. Covers code-less SSO rejections that nonetheless carry context.
  if ('accessToken' in errorRecord && 'message' in errorRecord && typeof errorRecord.message === 'string') {
    return true;
  }

  return false;
};

export function toError(input: unknown): MappedError {
  const unwrapped = unwrapAuthTokenRejectedPromiseIfNeeded(input);

  if (isRawNestedAppAuthError(unwrapped)) {
    return new NAAError(unwrapped.code);
  }

  if (isRawSSOAuthError(unwrapped)) {
    return new SSOError(unwrapped.message, unwrapped.code);
  }

  // Handle Error instances that carry a string `code` property (e.g. SSO errors thrown
  // as standard Error objects without an `accessToken` field). Without this check, the
  // code is silently discarded and the error is misclassified as "Unmapped+Error".
  if (unwrapped instanceof Error && 'code' in unwrapped && typeof (unwrapped as Record<string, unknown>).code === 'string') {
    const code = (unwrapped as Record<string, unknown>).code as string;
    return new SSOError(unwrapped.message, code);
  }

  if (unwrapped instanceof Error) {
    return new MappedError(unwrapped.message);
  }

  if (typeof unwrapped === 'string') {
    return new MappedError(unwrapped);
  }

  // Safety net: plain-object errors that carry a string `message` shouldn't have
  // that message discarded. The MappedError constructor still routes the message
  // through getMappedErrorStringMessage, so the privacy boundary is preserved —
  // only mapped labels (or 'Unmapped[+Tag…]+Error') ever land in telemetry.
  if (hasMessageProperty(unwrapped)) {
    return new MappedError(unwrapped.message);
  }

  return new MappedError('Unknown');
}

export function unwrapAuthTokenRejectedPromiseIfNeeded(input: unknown): unknown {
  if (typeof input === 'object' && input !== null && 'status' in input && (input as { status: string }).status === 'rejected' && 'reason' in input) {
    return (input as { reason: unknown }).reason;
  }

  return input;
}

const getNAAErrorMessage = (code: number): string => {
  // Map error codes to meaningful messages
  // These codes correspond to OfficeFirstPartyAuth.NestedAppAuth.AuthErrorCode
  switch (code) {
    case 13003:
      return 'UnsupportedUserIdentity';
    case 13004:
      return 'UserAborted';
    case 13005:
      return 'InteractionRequired';
    case 13006:
      return 'ClientError';
    case 13007:
      return 'ServerError';
    case 13012:
      return 'NotAvailable';
    case 13014:
      return 'PopupAuthFlowNotSupported';
    case 5001:
      return 'InternalError';
    case 5013:
      return 'InvalidApiArguments';
    default:
      return 'Unmapped+Error';
  }
};

const getSSOErrorMessage = (error: string): string => {
  return getMappedErrorStringMessage(error);
};

