// Tags appended to unmapped error messages to help bucketize unknown errors.
const unmappedTags: ReadonlyArray<[string, string]> = [
  ['ticket', '+Ticket'],
  ['identity', '+Identity'],
  ['server', '+Server'],
  ['resource', '+Resource'],
  ['invalid', '+Invalid'],
  ['network', '+Network'],
  ['fetch', '+Fetch'],
  ['cancel', '+Cancel'],
  ['user', '+User'],
  ['url', '+Url'],
  ['token', '+Token'],
  ['authoriz', '+Authz'],
  ['authen', '+Authn'],
];

export const getMappedErrorStringMessage = (error: string): string => {
  const code = error.toLowerCase();
  if (code.trim() === '') {
    return 'EmptyErrorMessage';
  }

  // Compound/exclusion checks that don't fit a simple includes lookup
  if ((code.includes('networkerror') || code.includes('network error')) && !code.includes('ticketnetworkerror')) {
    return 'NetworkError';
  }
  if (code.includes('stalled after') || code.includes('timed out') || code.includes('timeout') || code.includes('timedout')) {
    return 'TimeoutOrStall';
  }

  // Simple pattern matching from the table
  for (const [pattern, label] of errorMappings) {
    if (code.includes(pattern)) {
      return label;
    }
  }

  // Unmapped — bucketize with tags as a hint for addressing
  let message = 'Unmapped';
  for (const [pattern, tag] of unmappedTags) {
    if (code.includes(pattern)) {
      message += tag;
    }
  }
  return message + '+Error';
};

export const isRetryableNestedAppAuthError = (error: unknown): boolean => {
  if (!(error instanceof NAAError)) {
    return false;
  }
  return error.code === OfficeFirstPartyAuth.NestedAppAuth.AuthErrorCode.ServerError
    || error.code === OfficeFirstPartyAuth.NestedAppAuth.AuthErrorCode.ClientError;
};

export const isRetryableSSOAuthError = (error: unknown): boolean => {
  if (!(error instanceof SSOError)) {
    return false;
  }
  return error.code?.toLowerCase().includes('ticketnetworkerror') ?? false;
};
