export interface RetryOptions<TError> {
  maxAttempts: number;
  isRetryable: (error: TError) => boolean;
  isRetryEnabled?: () => boolean;
  onAttemptError?: (error: TError, attempt: number) => void;
  backoffDelay: (attempt: number) => Promise<void>;
  mapError: (error: unknown) => TError;
  exhaustedError?: string;
  nonRetryableError?: string;
}

/**
 * Executes `fn` with retry logic: retries up to `maxAttempts` times when
 * `isRetryEnabled` returns true (defaults to true) and `isRetryable` returns true.
 * Calls `backoffDelay` between attempts. `onAttemptError` is called on each
 * failed attempt for telemetry.
 *
 * When retries are exhausted, throws an Error with `exhaustedError` message if
 * provided, otherwise re-throws the last error from `fn`.
 * When an error is non-retryable, throws an Error with `nonRetryableError` message
 * if provided, otherwise re-throws the error from `fn`.
 */
export async function retryWithBackoff<T, TError = Error>(
  fn: (attempt: number) => Promise<T>,
  opts: RetryOptions<TError>,
): Promise<T> {
  let attempt = 1;

  while (attempt <= opts.maxAttempts) {
    try {
      return await fn(attempt);
    } catch (error) {
      const typedError = opts.mapError(error);
      opts.onAttemptError?.(typedError, attempt);

      const retryEnabled = opts.isRetryEnabled?.() ?? true;
      const shouldRetry = retryEnabled
        && attempt < opts.maxAttempts
        && opts.isRetryable(typedError);

      if (shouldRetry) {
        await opts.backoffDelay(attempt);
        attempt++;
        continue;
      }

      // Exhausted all attempts
      if (attempt >= opts.maxAttempts && opts.exhaustedError) {
        throw new Error(opts.exhaustedError);
      }

      // Non-retryable error
      if (opts.nonRetryableError) {
        throw new Error(opts.nonRetryableError);
      }

      throw error;
    }
  }

  // Should not be reached, but satisfies TypeScript
  throw new Error('Retry loop exited without result');
}
