/* eslint-disable @typescript-eslint/no-floating-promises */
import React from 'react';
import { createRoot } from 'react-dom/client';
import { getOfficeJsPathForSdxPath } from 'sdx-resource-loader';
import { App } from './components/App';
import './index.css';

// stop refresh on F5 and Ctrl+R
document.onkeydown = (e) => {
  switch (e.key) {
    case 'F5':
      e.preventDefault();
      break;
    case 'r':
      if (e.ctrlKey) {
        e.preventDefault();
      }
      break;
  }
};

console.log('Initializing Copilot Notebook SDX');
const indexRenderContainer = document.getElementById('index-react-root');
if (!indexRenderContainer) {
  throw new Error('Index root container not found');
}

console.log('Building onenote.js loader script');
const onenoteJS = document.createElement('script');
onenoteJS.id = 'onenote-js-script';
onenoteJS.onload = function () {
  console.log('onenote.js script loaded successfully - rendering app');
  const indexRenderRoot = createRoot(indexRenderContainer);
  indexRenderRoot.render(<App />);
};
const scriptSource = getOfficeJsPathForSdxPath(window.location.href, 'beta', 'onenote');
if (!scriptSource) {
  onenoteJS.src = 'https://officeapis.public.onecdn.static.microsoft/lib/beta/hosted/onenote.js';
}
else {
  onenoteJS.src = scriptSource;
}
console.log('Loading onenote.js from:', onenoteJS.src);
const head = document.getElementsByTagName('head');
if (!head || head.length === 0) {
  throw new Error('Cannot load OneNote JS script: head element not found');
}
head[0].appendChild(onenoteJS);
