import type { OdspFluidDataStoreLocator } from '@fluidframework/odsp-driver/legacy';
import {
  getLocatorFromOdspUrl,
  locatorQueryParamName,
  storeLocatorInOdspUrl,
} from '@fluidframework/odsp-driver/legacy';
import type { ExistingFileInfo } from '@fluidx/1p-loop-types';
import type { NativeInteropError } from '../../interop';
import {
  NotifyClient,
} from '../../interop';
import type {
  NativeEvent_NavigateToLinkArgs,
  NativeEvent_NavigateToSearchResultArgs,
} from '../../interop/nativeEvents';
import { TelemetryLogger } from '../../telemetry/TelemetryLogger';
import type { AppWorkspaceManager } from './AppWorkspaceManager';
import type { WorkspaceManager } from './WorkspaceManager';

type LinkNavigationContext = {
  IsValidUrlFormat: boolean;
  LinkType: string;
  HasOdspLocator: boolean;
};

type SearchResultNavigationContext = {
  HasDrive: boolean;
  HasItem: boolean;
};

export class OdspNavigationHandler {
  constructor(
    private readonly workspaceManager: WorkspaceManager,
    private readonly appWorkspaceManager: AppWorkspaceManager,
  ) {}

  public async navigateToSearchResult(params: NativeEvent_NavigateToSearchResultArgs): Promise<void> {
    const context: SearchResultNavigationContext = { HasDrive: false, HasItem: false };

    try {
      const { driveId, itemId } = this.extractDriveAndItemIds(params.siteUrl);
      context.HasDrive = !!driveId;
      context.HasItem = !!itemId;

      const fileInfo: ExistingFileInfo = {
        siteUrl: params.siteUrl,
        driveId,
        fileId: itemId,
      };

      TelemetryLogger.Instance.logEvent('NavigateToSearchResult', context);

      const odspLocator: OdspFluidDataStoreLocator = {
        siteUrl: params.siteUrl,
        driveId,
        itemId,
        dataStorePath: '/',
      };

      const odspUrl = new URL(params.siteUrl);
      storeLocatorInOdspUrl(odspUrl, odspLocator);

      await this.navigateToPageOdspLink(odspUrl, odspLocator, fileInfo);
      this.notifySearchResultStatus(params, true, context);
    } catch (error) {
      TelemetryLogger.Instance.logError('NavigateToSearchResultError', error, {
        ErrorMethod: 'appNavigateToSearchResult',
        ErrorDetails: 'Failed to navigate to search result',
        ...context,
      });

      this.notifySearchResultStatus(params, false, context);
      throw new Error('Failed to navigate to search result');
    }
  }

  public async navigateToLink(params: NativeEvent_NavigateToLinkArgs): Promise<void> {
    const context: LinkNavigationContext = {
      IsValidUrlFormat: false,
      LinkType: '',
      HasOdspLocator: false,
    };

    try {
      const odspUrl = new URL(params.linkUrl);
      context.IsValidUrlFormat = true;
      context.HasOdspLocator = odspUrl.searchParams.get(locatorQueryParamName) !== null;
      context.LinkType = /(?<FluidHint>\/:fl:\/[a-z]{1,2}\/)/.exec(params.linkUrl)?.groups?.FluidHint ?? '';

      TelemetryLogger.Instance.logEvent('NavigateToLink', context);

      const odspLocator = getLocatorFromOdspUrl(odspUrl, false);
      if (!odspLocator) {
        throw new Error('Failed to extract ODSP file locator from link url');
      }

      const fileInfo: ExistingFileInfo = {
        siteUrl: params.linkUrl,
        driveId: odspLocator.driveId,
        fileId: odspLocator.itemId,
      };

      await this.navigateToPageOdspLink(odspUrl, odspLocator, fileInfo);
      this.notifyLinkNavigationStatus(params.linkUrl, true, context);
    } catch (error) {
      TelemetryLogger.Instance.logError('NavigateToLinkError', error, {
        ErrorMethod: 'appNavigateToLink',
        ErrorDetails: 'Failed to navigate to link',
        ...context,
      });

      this.notifyLinkNavigationStatus(params.linkUrl, false, context);
      throw new Error('Failed to navigate to link');
    }
  }

  private extractDriveAndItemIds(siteUrl: string): { driveId: string; itemId: string } {
    const regex = /\/drives\/(?<Drive>[^/]+)\/items\/(?<Item>[^/]+)/;
    const match = regex.exec(siteUrl);
    const driveId = match?.groups?.Drive ?? '';
    const itemId = match?.groups?.Item ?? '';

    if (!driveId || !itemId) {
      throw new Error('Search result missing required ODSP locator parameters');
    }

    return { driveId, itemId };
  }

  private async navigateToPageOdspLink(odspUrl: URL, odspLocator: OdspFluidDataStoreLocator, fileInfo: ExistingFileInfo): Promise<void> {
    const workspace = await this.workspaceManager.GetWorkspaceForPage(fileInfo);

    if (!workspace) {
      throw new Error('GetWorkspaceForPage returned undefined');
    }

    storeLocatorInOdspUrl(odspUrl, odspLocator);
    await this.appWorkspaceManager.appNavigateToPage({
      docUrl: odspUrl.href,
      podId: workspace.mfsPodId,
    });
  }

  private notifySearchResultStatus(
    params: NativeEvent_NavigateToSearchResultArgs,
    success: boolean,
    context: SearchResultNavigationContext,
  ): void {
    NotifyClient.navigateToSearchResultStatus({ ...params, navSuccess: success }).catch((error) => {
      TelemetryLogger.Instance.logError('NotifyClientError', error as NativeInteropError, {
        ErrorMethod: 'navigateToSearchResultStatus',
        ErrorDetails: 'Failed to notify client of status',
        ...context,
        NavigationSuccess: success,
      });

      if (!success) {
        NotifyClient.failedToNavigateToSearchResult({ ...params, navSuccess: false }).catch((fallbackError) => {
          TelemetryLogger.Instance.logError('NotifyClientError', fallbackError as NativeInteropError, {
            ErrorMethod: 'failedToNavigateToSearchResult',
            ErrorDetails: 'Failed to notify client of status',
            ...context,
            NavigationSuccess: false,
          });
        });
      }
    });
  }

  private notifyLinkNavigationStatus(
    linkUrl: string,
    success: boolean,
    context: LinkNavigationContext,
  ): void {
    NotifyClient.navigateToLinkStatus({ originalUrl: linkUrl, navSuccess: success }).catch((error) => {
      TelemetryLogger.Instance.logError('NotifyClientError', error as NativeInteropError, {
        ErrorMethod: 'navigateToLinkStatus',
        ErrorDetails: 'Failed to notify client of status',
        ...context,
        NavigationSuccess: success,
      });

      if (!success) {
        NotifyClient.failedToNavigateToLink({ originalUrl: linkUrl, navSuccess: false }).catch((fallbackError) => {
          TelemetryLogger.Instance.logError('NotifyClientError', fallbackError as NativeInteropError, {
            ErrorMethod: 'failedToNavigateToLink',
            ErrorDetails: 'Failed to notify client of status',
            ...context,
            NavigationSuccess: false,
          });
        });
      }
    });
  }
}
